/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070227-8","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"建設委員会","time":"午前１０時０３分～午後４時０１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を99件整理しています。","topics":[{"id":"topic-01","title":"昨日、継続となっておりました第１５号議案、品川区手数料条例の一部を改正する条例","agenda":"昨日、継続となっておりました第１５号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"全体で値上げ額が１.２倍ということなんですけれども、今の出された資料のところでは、飲食店の新規が１.９倍、喫茶店等は１.１９倍と。菓子製造が新規だと１.２倍ということなんですが、この中で大体一番多いケースというのは、どういうところなんか尋ねました。","respondent":"谷田部健康課長","answer":"１,１４７軒。このような状況になっております。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"１.２倍の根拠は何なのかなと。この例の中では１.２倍を超えるものというものがちょっとないので、あえて１.２倍に設定したということは、東京都の設定以外にはありますかとの意見を述べました。","respondent":"谷田部健康課長","answer":"東京都がそのような回答をしていますし、私どもも極力１.２倍の範囲内に抑えるということで、今回改正をお願いしているです。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"しかもこれを見ると、１.２倍までおそらく全部含めると１.２倍までいかないだろうというのが容易に推測できるわけです。例えば低く抑えられるんじゃないですかということなんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"大体職員を税金で雇っているわけですから、私はこのコストを出す根拠というのは、そもそも私はおかしいと思います。ちょっと最後は意見になりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"とどのつまりは、例えば飲食店営業（新規）のところで見ると、品川区は１万８,５７５円を負担していただくことが当然だという考えなんですか。喫茶店の問題だと、９,９６４円負担してもらうのは当然だという考えなんか尋ねました。","respondent":"谷田部健康課長","answer":"手数料の改定を予定しているということでございまして、当然これを計算していきますと、高いところも出てくる。今後、社会経済状況が大きく変わるような要素があれば、当然手数料の改正というのは当然出てくるというふうに思ってあります。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたかったのは、激変緩和という話が今出たんですね。１万８,５７５円まで引き上げることが、そこを伺っているんです、区の考えを。","respondent":"谷田部健康課長","answer":"来年このコストの形に近づけるために改正する予定があるかどうかというご質問だと思いますけれども、社会的な情勢がどのように変化していくかどうか。今、具体的にいつどうのこうのというのは、お答えはできないということになります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"意見","question":"結局、今の課長の説明だと、将来的には人権費も含めて１万８,５７５円、ここに向けて当然動いていくんだと。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"新規の場合ですと、９,９６４円のコストに対して改定額が５,７００円ですから、この辺はぜひ１.２倍で激変緩和を抑えたということですから。そういう議論になっちゃうと思うので、ぜひこの１.２倍に抑えたというところを、これからもそういう発想でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"３の事業で教えていただきたいということと、増収である３２０万円は手数料として先ほどおっしゃった食品安全について評価されるようなことであれば。２点お願いします。","respondent":"谷田部健康課長","answer":"１０から１２項目は８年ということで、項目数によって期間は変わってまいります。それから食中毒を出さないための研修に対する支援ですとか、総合的に私どもは取り組んですので、歳出は歳出で私どももしかるべくやっていくです。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"そのことが理解できるということが必要だと思いますので、そういう分では、こういったところを評価したというような政策をぜひ進めていってほしいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、これはちょっと食品衛生のほうが全く根拠がないなと思います。今までどおりの対応でできるわけですから、今回の手数料条例の改正は、共産党は認められないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"第１５号議案に対して、昨日、自民党松澤委員から提案がありました附帯決議","agenda":"第１５号議案に対して、昨日、自民党松澤委員から提案がありました附帯決議","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"今回の手数料改正については、民間の機関による建築確認に対する責任まで負わなくちゃいけないということで、これに対しての責任負担の増大。指定権限は都道府県知事にあるものですから、厳格に機関の監視・監督に努めるようにしていていただきたいということで、２つにまとめて提出しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"品川区が働きかける相手としては、１の国というのはわかるんですけれども、２はやっぱり都道府県知事ということになるんですか。それともこれはこういう書き方をするものなんか尋ねました。","respondent":"片田建築課長、福田まちづくり事業部長","answer":"昨日の説明の中で、こういうピアチェック機関は各都道府県知事が指定すると。神奈川県知事が指定するということになりますので、もし２３区あるいは東京都下の市を含めれば、やはり都知事あてに働きかけるということになります。おそらく共通に認識されておられるのは、一人品川区の問題ではなくて、全国的な問題だろうというふうにご認識があると思うんです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"提案者にお伺いしたいんですけれども、いわゆる確認審査そのものを民間に開放させることが、ボタンのかけ違いかなという思いなんです。そこは前提の整備で、含みががあるのかどうか、ちょっと提案者の趣旨をご説明していただけたらなと思うんですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"松澤委員","kind":"確認","question":"特に民間機関による建築確認なんていうのは全然こっちに話がないわけですからね。民間が建築確認を受けて、その民間機関がピアチェックでもって出すわけだから、それでやったものに関して、最終的な責任は自治体というのはちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"意見","question":"今のそういう仕組みを変えていってほしいということですよね。ちょっと文書だけ読むと、そこのところが何かストレートに伝わってこないので、今の説明があわせてあればとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"質問ということでお願いしたいんですが、それは自治体が設置するということで負担増ということですか。これは自治体が設置をするものだから、負担が多くなります、だからという流れか尋ねました。","respondent":"片田建築課長","answer":"ご指摘の話ですけれども、先ほどお話をしましたように、各都道府県知事が指定すると。各自治体が自前のものが設置できればよろしいんですけれども、それができないために、当然それについて東京都のほうもここに依頼するということです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"確認","question":"僕もまだなかなかどういうものなのかよくわからない部分があるのでお伺いしたいんですけれども、そういう関係にピアチェックという新たな確認事務ですとかそういうものというのはどんなふうに、ちょっとご説明いただけますか。","respondent":"片田建築課長","answer":"基本的には議会のほうの審議をもってというようなことは記載されてございませんので、いろいろな経過の中で報告することはあろうかなと思いますけれども、設置者である知事の判断の中で進めるというものです。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"意見","question":"本来であれば、もうちょっと今の仕組みで自治体にそのまま来るのが疑問だというふうな、何かそういうふうな文言があればなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"意見","question":"問題意識はわかるんだけれども、そういう問題意識であれば、ストレートにそういう表現のほうがいいかなというふうに。このまま文書は文書でいきますから、今のこの議論がそのまま使わないから、どんなものかなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-03","title":"平成１８年陳情第１２号、（仮称）戸越６丁目ワンルームマンション建設に関する陳情","agenda":"平成１８年陳情第１２号、（仮称）戸越６丁目ワンルームマンション建設に関する陳情","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ほかの自治体なんかでは、緩衝地域というか、その間に何らかの用途地域があってできているということを伺っています。そういう用途地域の緩衝エリアみたいなものを検討するというようなことは、品川区のまちづくりの中では、考えとしてはないんか尋ねました。","respondent":"片田建築課長","answer":"今回のように、近隣商業地域のほうに建物が建ってなくて、後背地への影響というのは確かにあるということは認識しております。これを活用することになっておりますので、住民への法的な整備の中では、十分になされているという認識です。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"区内のワンルームマンションの建設が伸びているのか、それともどういう状態なのか、ちょっと教えていただきたいというのが１点。対策とか、いろいろ求められているのかなと思うんですけれども、もし何かお考えがありましたらお聞かせいただけますか。","respondent":"齋藤住宅課長","answer":"どの場合によりましても、あるいは金融機関から進められるのはワンルームマンションの業者に売ると一番高く売れると、現在のところの実態のようです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"最後に、地域に溶け込めるような検討をしているというお話なんですけれども、これは何か具体的なところで、今もし考えていることがありましたら、そこだけもう少し教えていただけますか。","respondent":"齋藤住宅課長","answer":"説明していますが、古い方から言われると５人組の制度があるんで、そんなものに入れないと。ただ、どこまで、どうするかについては、まだ検討中で、いろいろなものを考えながら、総合的に考えていきたいと思っています。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"意見","question":"３分の２ぐらいは合意が、いわゆる住民の会というふうにはっきりしていたかどうかわからないんですけれども、そこら辺がわかったらとの意見を述べました。","respondent":"齋藤住宅課長","answer":"説明し難いところでございまして、会としての固まりはあります。固まりの中でいろいろご要望もあるので、いろいろなお話をしてほしいと事業者に働きかけていらっしゃる方もいらっしゃいます。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"現在のところ、大体何戸ぐらいが参加されているか説明を求めました。","respondent":"齋藤住宅課長","answer":"本件におきましては、２０人ぐらいの方が、当初、会のような形で参加されておりました。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、その会以外にも、個別に住民の方々と交渉されているという理解でよろしいんか尋ねました。","respondent":"齋藤住宅課長","answer":"その会の方に私もお会いして、具体的な、どういうふうに交渉したほうがいいのか、こういう話は聞かせていただき、アドバイスをさせていただきました。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問・要望","question":"それぞれ独身で住む方だっているわけですから、やっぱりどんどん話し合いをしながら、いいものをつくっていただきたい。結論的には、まだもうちょっとで妥協すべき話し合いをしているというのですから、推移を見守るしかないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"平成１９年請願第１号、目黒線立体交差事業に伴う旧西小山四号踏切上車両通行の代替案に反対する請願","agenda":"平成１９年請願第１号、目黒線立体交差事業に伴う旧西小山四号踏切上車両通行の代替案に反対する請願","exchanges":[{"speaker":"井上委員","kind":"質問","question":"地元の方に伺うと、地域ではなかったような話を伺ったんですが、この５回の説明会をどこでされているのかということが１点。それからもう１点、シミュレーションをされて、この代替道路にどのぐらいの通行量があるかということも、説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"地域住民への説明会については、東急の現場や目黒区の住民センター、あるいは品川区の区民センターというところでやっております。２点目の、説明会の中で十分にと言いますけれども、代替施設全体を図示しながら説明をしています。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"どうしてここにつくるんですかということも含めて言うんですけれども、１日１０３台ぐらい通る道路というのは、必要性のある道路ということなんか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"それで、今回、これをつくることによって、その台数が３０台前後になるというふうになっております。ですから、大体予想に近い数字で、今推移しているということです。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"平成１５年の住民からのまちづくり事業部長への質問書の中に、この代替案の道路は危ないから通すべきではないという声に対して、その要望に対して。さまざまな安全対策を講じるということは、具体的にはどういうことをして、これを通そうするものなのか、質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問・要望","question":"住民に対してどうかというところでは、地域住民が本当に求めているかというところは、非常に危険な個所だということだけは認識をします。","respondent":"浜脇街路事業担当課長","answer":"今の自転車の話なんですけれども、きのうも歩いていただきましたけれども、今回、自転車は歩道のほうに行っていただいて、押してくださいというルールになっております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"交通量から、代替道路をつくる基準みたいなものというのはあるんですかね。これだけの交通量が予測されているんで、代替道路をつくらなければいけませんと、そういう基準というのがあるんですかね。","respondent":"浜脇街路事業担当課長","answer":"これは４ｍ以上道路が今まで一方通行だったんですが、結構、代替道路に行かなくなったことに寄与していただいているという部分があります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局、さっき質問した、交通量を減らすための道路をつくる基準というものは、じゃあ、ないということなんですかね。緊急車両の話が出ましたけれども、シミュレーションの結果をまた伺いたいのは、ここを通るのと、通らないのと、実際に何分違うんか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"いろいろ高さをどうするかということを検討したときに、どうしても数カ所、完全立体化ができない個所があった。こういった車が現存している中で、この立体化案を地域にご説明したときに、大きく反対の声が挙がりました。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"今までの経過は伺いましたけれども、これがないと、こっちから向こうへの時間がどのぐらい変わるのか。さっき、代替道路をつくる主な理由が、緊急車両の通行、一般車の通行という２点をおっしゃっていたので、そこを伺っているんですけれども。","respondent":"岩田まちづくり事業部次長","answer":"現実に、ここの道路だけじゃなくて、この周り自体が輻輳した一方通行で、荏原地区はよそものが進入できないような道路形態にしてあるんです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"地域の方に伺いますと、今、車両が１０３台ぐらいなんだと。雪が降ったら、アイスバーンにならないように除雪をやるっていうけど、いちいちここへ除雪に行くわけですか、雪が降るたびに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"藤田委員","kind":"質問・要望","question":"それを今回、今までの要望があって、車道と歩行者、自転車を分けたということです。ですから、雪が降ったらどうのこうのという話がありましたけれども、ここだけではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問・要望","question":"じゃあ、危険じゃないかというところの対策は一体どうなのかということも、ひとつやっぱり考えていかなきゃいけない。それから、ここのところはどういうふうな考え方があるのかというのがあれば、ちょっと説明していただきたいと思うんです。","respondent":"岩田まちづくり事業部次長","answer":"広い道路、わざわざこのような４ｍを切るような狭いところへ入ってくるというのは、よほどのことでない限りないと想定しています。今後も様子を見ながら、地域の方の意見を聞きながら、必要なところには次の手を打っていくということもやってまいりたいと考えています。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"ですからこういう形状の下り坂となると、私自身の経験からいくと、非常に危険だという感じをしています。例えば速度表示が２０kmとなっているからいいかどうかと、私も運転しますけれども、私は守りますけれどもね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"住民の方に伺うと、自転車とか通る人たちが一番使うところであるということが、地域の方の認識なんです。そういう方向転換というものはあるのか、どうなのかということを、お願いします。","respondent":"岩田まちづくり事業部次長","answer":"もう供用開始をしておりますので、今後も地域の方の意見は聞きながら、必要な対策はちゃんとやっていきます。逆に、圧倒的多数のこの地域の方たちから反対されるんではなかろうかということを、私は思っております。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"リスクがあるかどうかというところについての答弁がないので、ここの部分でとまらなかったり、リスクがあって、もし人身事故が起きた場合には、道路管理者として責任を負わなければいけないので、税金で道路をつくっていながら。","respondent":"岩田まちづくり事業部次長","answer":"ただ、だからと言って、じゃあ１００％事故は絶対にないかと言われますと、これは、たらればの世界になりますので、わかりません。必要な対策がもしあるのであれば、十分に対応していくという姿勢ですので、ご理解をお願いします。","id":"exchange-040"},{"speaker":"阿部委員","kind":"質問・要望","question":"よくこれだけの道路と歩道橋、そしてエレベーターなどをつくられたなと、むしろ敬服しております。そういう新しいニーズができてくれば、それはまた早期に対応していただきたいと、これは意見と要望だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"本多委員","kind":"意見","question":"できる前と、できてからの状況と、いろいろなシミュレーション、そして状況をもう少し見ていきたいと思っています。結論を出してもいいという判断もありましたが、もう少し状況を見たいと考えていますので、継続でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"宮崎委員","kind":"意見","question":"今の状況がこういう状況なので、将来的にどうなるのかというのは、はっきり言ってまだよくわからないところがあるというのがわかるんですよ。こういう意見をしっかり担保してというか、そういう意味では、採択を主張したいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"藤田委員","kind":"質問・要望","question":"すっきりした見通しのいい道路にするということを、今後、ぜひ取り組んでいただきたいなと考えています。きょうのところは、継続で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"阿部委員","kind":"意見","question":"大変悩ましいところではありますが、ここで採択を取ってもいいのかなという気持ちも半分はあるんですけれども、供用開始してまだ時間がないということで、この道路が、今後どのように使われていくかという観察期間という気持ちも含めまして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"井上委員","kind":"意見","question":"署名をされた方たちの声というものもあり、なおかつ、必要であれば安全対策をとるというまちづくり事業部次長の言葉もありました。住民の皆さんの意向を反映させたいと思いますので、採択をしていただいて、結論を出すということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明の後半のほうに、北側の隣地との境界線の話の中で、民法上は５０cmというお話、それがどういうものなのか、教えていただきたい。目の前に２０ｍ強の建物があるわけですから、それにしても５０cmしかないというのは、いくら何でも狭いなという感じがするんです。","respondent":"齋藤住宅課長、片田建築課長","answer":"民法のことについてご説明します。５０cm隣地境界から離さないでつくった場合は、建築の差しとめもできますと、こういう条文があるんです。ただ、建築基準法と民法は法体系が全く違うもので、契約上、あるいは民事的な対応、法令上の制限とは全く異なります。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"例えば、こんなことを聞いてもあれでしょうけれども、形を目いっぱいやるということは、業者とは、そういう考えにはならないんでしょうかね。近隣の方への配慮が感じられないんですけれども、何か業者から聞いていることがありましたら、教えていただけますか。","respondent":"齋藤住宅課長","answer":"ただ、例えば資料の１ページをごらんいただきたいんですが、全体配置図です。隣地と５０cmのところから建物を建てないと、部屋の数、大きさが取れないということだと思います。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"今、請願が出ている方のアパートというのは、Ａ棟の北側だと思うんですけれども、もしご存じでしたら、このアパートから隣地境界線までの距離はどのぐらいなんか尋ねました。","respondent":"齋藤住宅課長","answer":"わかりません。","id":"exchange-049"},{"speaker":"阿部委員","kind":"質問","question":"現地を見た感覚だと、そちら側も相当詰まっていたという感触を持つんですけれども、あれだけ詰まって建てられるというのは、これが準工業地域だからなんですか、それとも、どういう地域でも詰まって建てられるんでしょうか、説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問","question":"目隠し等々もされているということですから、こういうマンションの請願を出されたんですけれども、やっぱりちょっと推移を見たいと思います。ちょっと気の毒かなとは思いますけれども、改めてまだまだ話し合いをしているようですから、次の機会に出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"宮崎委員","kind":"意見","question":"当たり前のことが、本当に私は、建築行政そのものが住民から支持が得られなくなっちゃうんじゃないかと思うんです。それはちょっと感想ですけれども、この請願自身も、今、話し合いを進めているということですので、継続でしようがないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"藤田委員","kind":"意見","question":"７階、８階というものが１ｍも離れずに建ってしまうということは、住民の皆さんの気持ちはよくわかります。ですので、粘り強く建主との交渉をお願いしたいと考えていますが、きょうのところは、継続ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"阿部委員","kind":"意見","question":"確かに、これまでとあまりにも環境かがらっと変わるということで、住民の方のそういう声というのは、確かにそうだなろうと思う気持ちは十分にありますが、話し合いを進めているようですので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"井上委員","kind":"意見","question":"民法上の５０cmというところでは、後に室外機だとか、何かこれを仕組みとして対応できるものがないのかなと思います。どこかで、だれかが何とかしたいという項目でもあると感じていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"}]},{"id":"topic-05","title":"平成１９年請願第８号、東急目黒線立体交差事業に伴い新たに発生した騒音の対策を求める請願","agenda":"平成１９年請願第８号、東急目黒線立体交差事業に伴い新たに発生した騒音の対策を求める請願","exchanges":[{"speaker":"井上委員","kind":"質問","question":"それから、今の騒音については、どれだけ騒音があるのか、測定をされたのかどうかという、今の状況について。ぜひ説明をしてほしいということに対して、なぜ説明会をしようとされないのか、その点を説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"工事前の平成２年３月が７９dB、平成１８年１２月１日が７３dBということで、砕石を散布して急行運転を開始したところです。いろいろな説明会等を二十何回もやったんですが、これまでの具体的な説明はしないで、それをそのままやることで済むというふうに考えてあります。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"防音の設備とか、そういう根本について聞いてほしいということだと思うんです、この文章は。チラシをまいてどうのこうのという説明ですけれども、事業者も、説明会をすれば別によろしいんじゃないかか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"当然、１２.５ｍというところもありますけれども、同様に、６dB下がっております。住民に対して説明責任というのがありますので、改めて説明会といったことは開かないけれども、個々に説明をして。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"きめ細かいという思いがあるのかもしれないんですけれども、地方住民の合意というところでは、しない理由がわからないんです。すればいいじゃないですかという、その先いろいろなトラブルがないわけですから、してほしいということに対して。","respondent":"浜脇街路事業担当課長","answer":"当初からこの代替施設をつくるときには、こういう構造といいますか、仕様でやりますということは伝えてあるものです。これについては、工程が進めば目隠し板や防音壁がつくですので、改めて説明会というものをする必要はないと。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話の中で、途中から出てきた意見を聞かない理由は何なんですか。今の説明では、いや、途中からの意見は聞かないですというのは、その理由は何なのか、ちょっと伺いたい。","respondent":"浜脇街路事業担当課長","answer":"途中での意見ではなくて、私どもは最初から、こういうことは取り付けるということでやっておりましたし、そういう説明をさせてもらっていますです。先ほど申しましたように、これまで以下になるように取り付けるものですので、効果は出るものと考えております。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"今ある区の考えでなぜ説明会を開かないのか、全く説明になっていない、まちづくり事業部というものはそういう部なんですか。住民の方々のご意見を伺いながら云々と言っていますけれども、特別な理由があれば、あえて説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"説明会の意味なんですけれども、私どもと事業者側も何回かの説明会、それからそういった説明会については行わないと決めたという経緯があります。説明をしない、特に東急ですけれども、東急にお願いして工程表等を配っているものです。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"要は、説明会を開かない理由は何なのか、もう１回整理してお答えいただきたい。それを最後に説明を求めました。","respondent":"浜脇街路事業担当課長、岩田まちづくり事業部次長","answer":"説明会を開かない理由というか、これからは説明会ではなくて、それを守っていることは事実です。それについては今後とも検討する材料だと認識しておりますので、また私どもも入っていいものを使っていただくように努力してまいります。こういう素材で対応するように考えていますということを十分に説明するのは当然のことでありますから、できれば１軒１軒説明して歩いて、理解を求め。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"今の防音壁の効果、最終的にはまだ先の工事だということなので、その工事があって、まだそれでは対応が不十分だということであれば、その後の対策というのはきちんとやりますということでよろしいか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"それを含めて、騒音のレベルの問題というのはちょっとわかりませんけれども、当然、そういうご質問に対してはお答えするように、やはり皆さんにある部分迷惑をかけていることですので、迷惑が減るような努力は、今後してまいることは事実です。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"意見","question":"歩道橋のほうも、きのうも歩いてみて、大分音がするので、私は、どうして鉄板でやったのかなという、そういう気持ちが強いんです。話し合いの進め方と、今実際に考えられることなのか、その効果はどういうふうなものなのかということが、わかったらお願いしますとの意見を述べました。","respondent":"浜脇街路事業担当課長","answer":"検討している最中ですけれども、階段の裏が太鼓状になっていますので、そこのところに触れないようなマグネットみたいなものを装着していく。これは事業者側の問題といいますか、やらなくちゃいけないことですので、責任を持ってやらせていただくです。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"音が出るのは当たり前ですから、つくる側のほうがどういうスタンスでいくのかというのは、なかなか理解されないんじゃないかと思います。同じ各駅だけの比較なのか、そこの部分はどうか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"それから、地下化後にやったのが、平成１８年１２月です。それは急行運転のところでやって、今言ったように、前回が７９dBで、今回が７３dBだったという結果が出ております。","id":"exchange-064"},{"speaker":"宮崎委員","kind":"確認","question":"こういうふうに言っているものですから、はかり方というか、問題になるのかどうなのか。実際の住民の感情に合った測定になっているのか、どうなのか、そこら辺のところはどういうふうにお考えなんか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"それから、先ほども冒頭に申し上げましたけれども、高架だったものを下げて、コンクリートにして砕石をまいたということが１点。若干音質の変化があって、私どもが考えている音質より、皆さんがこれまで聞いたのと違った音質というふうに受けとめた方もいるかなとは思います。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ある意味では今の機械のレベルでいくものですから、実際に住民というか、人間の感覚とはまた違うレベルがありますので。そこら辺のところの住民の感覚、実際に受けとめている感じというのを直に聞いていくという、そういう姿勢を強く求めたいと思うんですね。","respondent":"浜脇街路事業担当課長","answer":"詳細な説明とか、対応とかが必要ということは考えておりますので、今後とも考えてまいりたい。","id":"exchange-066"},{"speaker":"藤田委員","kind":"質問・要望","question":"１軒１軒、また地形等もありますので、その辺の説明をぜひ丁寧にやっていただきたいということを要望します。きょうのところは、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"阿部委員","kind":"質問","question":"先ほど来伺っていて、区側でもいろいろと対策に力を注いでいるという印象を受けました。むしろ住民の日々の苦しみに耳を傾けるということを含めての説明というものを続けていかれることを期待しつつ、今回は継続ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"井上委員","kind":"質問・要望","question":"今、本当にこれからそういう意味で住民に対応していくということがわかりましたので、さらに住民の方たちの要望を応援する意味で、結論を出すということで、採択をするということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-06","title":"を行います。(1)の品川南ふ頭公園の都市計画決定","agenda":"を行います。(1)の品川南ふ頭公園の都市計画決定","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"東京都から移管をされるときは無償だというお話を伺っているんですけれども、大体幾らぐらいで、どこから買うとかということ。あわせて、多目的広場に整備する工事の費用、幾らぐらいなのか、ちょっと教えていただけますか。","respondent":"松代管理工事課長","answer":"１２月２０日に開きました説明会、夜の７時から８時半という予定で開催しましたが、残念ながら、参加者はございませんでした。これに隣接をしまして、港湾局の持っている土地約１,５００m2ほど、有償で購入をする予定です。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"団体の中で意見を伺っているというお話だったんですけれども、その中でもどんな意見が挙がったのか、教えていただきたい。こちらの財布の準備ぐあいといいますか、見込みといいますか、大体幾らで調節しようかなというのがありましたら、教えていただけますか。","respondent":"松代管理工事課長","answer":"スポーツ団体等の懇談会の中では、何とか取りやすいような、また枠を広げられるようなことができないかというようなことがございました。少しでも安く購入させていただけるように、今、お願いをしている状況です。","id":"exchange-071"}]},{"id":"topic-07","title":"の北品川五丁目第１地区市街地再開発事業に関する都市計画素案","agenda":"の北品川五丁目第１地区市街地再開発事業に関する都市計画素案","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ここを赤い地域に指定したということで、どういうことが、今後あるのか。優先的に公費がここに補助されていくとか、区としてはいろいろなメリットがあると思うんですけれども、そういう状況を説明を求めました。","respondent":"青木都市開発課長","answer":"先ほどご説明しましたとおり、この説明会、あるいは品川区という行政側での都市計画手続に進んでまいります。そのための近隣の意見集約をしたいということで、お願いした説明会です。","id":"exchange-072"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと準備組合のほうに伺ってみたところ、区側にも実は出席してほしいというような打診はしたのだけれども、聞いております。そういう判断があって欠席、あるいは出席していらっしゃらなかったのか、その辺も伺ってみたいと思います。","respondent":"青木都市開発課長","answer":"これはあくまでも事業予定者といいますか、近隣の方々にご説明する内容ですので、地元の方々に詳しくご説明できなかったというのは。それに連動して建替えを検討していくということでご答弁しておりまして、その方針は、現在も変わっておりません。","id":"exchange-073"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただわからないことだけが増えていって、不安だけが増えていくというような場では、説明会を開くことがもったいないと思うんです。ですから、それを最大限活用できるような形で柔軟に考えてほしいと求めましたが、いかがか尋ねました。","respondent":"青木都市開発課長","answer":"委員もご出席いただいたという説明会は、区のほうでは、開発事業に連動して建替えを検討しているようだというところまでは事実なので。情報の確認を取った上でご説明いただいておりますので、１０日の段階で、同じことであったと思います。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つかまとめて伺いたいと思うんですけれども、赤いほう、総事業費は幾らなんですかね。それから、補助金の投入ですけれども、どういう補助金になるのか、そしてその金額も教えていただきたい。","respondent":"青木都市開発課長","answer":"２ページの絵にありますＤ棟の東側に細い道路が通っておりまして、ここを一体的な活用ができることによって、この道路は廃道できる見込みです。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"それから、教育委員会にも相談したというお話がありましたけれども、じゃあ、教育委員会はこの日影の影響をご存じなんですかね。それを踏まえて、Ｅ棟を下げてＤ棟を上げるというこの計画に、教育委員会もいいですよと、その辺の協議のぐあいを説明を求めました。","respondent":"青木都市開発課長","answer":"一番外側が２時間の影が及ぶ範囲ということで表示されておりますので、今、そちらには午前中いっぱい日が当たる計画にしています。影が落ちるんだったら、それをどのぐらい高くしても御殿山小学校への影響は変わらないということで、ある意味では高くなっているです。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"３時間から４時間、今の話ですと、今ある校舎の位置ですと、校舎が１日中日影になるんでしょうか。向こうがよしとしているのか、悪いとしているのかわかりませんけれども、何か意見が挙がっていないんですかね。","respondent":"青木都市開発課長","answer":"影を落とすこと、もちろん議論になりまして、望ましいかどうかいろいろ検討した結果を、今、Ｅ街区を低くしたというご説明を申し上げております。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"じゃあ、教育委員会との協議は１年以上にわたって行われているんですか。しかも、区がみずからやることは、私はあってはいけないと思うんですけれども、最後のところだけ説明を求めました。","respondent":"福田まちづくり事業部長","answer":"できる限りの配慮を、この場合は図ってまいりました。ひいては、学習環境の向上にも寄与するというふうに考えております。","id":"exchange-078"},{"speaker":"本多委員","kind":"質問・要望","question":"この計画の真ん中にある地区幹線道路３号についてお聞きしたんですけれども、１５ページ、本当に心臓部分だと思っていたんです。１６ｍでもっとまっすぐいくと思っていたんですが、１５ページのところで、ちょっと教えていただきたいと思うんです。","respondent":"青木都市開発課長","answer":"今、委員からご指摘いただきましたのは、１５ページでごらんいただいておりますので、ご説明申し上げます。マンション建替え等の計画が検討されておりますので、その沿線の開発が進むときにあわせて整備していこうということで、話を進めているところです。","id":"exchange-079"},{"speaker":"本多委員","kind":"確認","question":"では、１本道ではなくて、将来は、１６ｍがＴの字になるということですか。１６ｍ拡幅する、その辺は引き続きやっていくのか、それだけちょっと確認を説明を求めました。","respondent":"青木都市開発課長","answer":"今の私の説明が足りなかったんですが、ソニー第２工場と書いてあるところの北側になるんですが、東西に道路網が形成されることになっております。","id":"exchange-080"},{"speaker":"宮崎委員","kind":"質問","question":"１９名の参加権利者数というんですか、個人や企業、それからあと主な事業者、そこのところを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"宮崎委員","kind":"質問・要望","question":"主な参加企業があったら教えていただきたい。そういう動きもあるんですけれども、そこら辺の、この計画というのはどういう計画になっているのか。","respondent":"青木都市開発課長","answer":"先ほどの委員のご指摘にありました地区幹線３号という通りを、物販、飲食等を想定しております。それから、近所にお住まいになる方々の利便性向上を図るという観点から、小規模なスーパーマーケットを誘致したいということで計画されております。","id":"exchange-082"},{"speaker":"宮崎委員","kind":"質問","question":"事務局の企業名がわかったらお願いしたい。それとも大きなキーテナントを考えているのか、そこのところは、わかっている範囲で説明を求めました。","respondent":"青木都市開発課長","answer":"それから、大規模な権利者としましては、品川区のほかに地元の巴工業、愛知産業などいらっしゃいます。沿道型のものを考えておりまして、委員ご指摘になりました、何がご商売するというような店舗は想定していないと聞いております。","id":"exchange-083"},{"speaker":"井上委員","kind":"質問","question":"Ｂの地域コミュニティ施設等というのは、よくこういったところで地域センターの無償誘致だとか、いろいろなところでありますけれども、これはどういうものなんか尋ねました。","respondent":"青木都市開発課長","answer":"Ｂ地区、地域交流施設というものは、地元の権利者の方々で運営することを想定しております集会場のようなものを考えております。あるいは、今、地元の防犯のステーションというようなことでも活用していきたいということで検討されていると伺っています。","id":"exchange-084"},{"speaker":"阿部委員","kind":"質問","question":"先ほど、中塚委員の質問に答えられまして、学校への配慮ということを具体的に幾つか挙げていらっしゃいました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]},{"id":"topic-08","title":"大崎駅西口南地区市街地再開発事業に関する都市計画素案","agenda":"大崎駅西口南地区市街地再開発事業に関する都市計画素案","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この理由を聞きたいんですけれども、計画どおり進むということを、区が認めているから載せているんですか。ここに扇状に載っておりますけれども、これはどういう意味なのか、再開発事業の中の一環としてのことなのか、ちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"冒頭申し上げましたとおり、これは再開発準備組合の皆さんが地元の近隣の方々にご説明する資料ですので、区の用意した資料ではございません。","id":"exchange-086"},{"speaker":"中塚委員","kind":"意見","question":"２月１３日に、区長が都知事あてに出した回答の中でも、事業計画案にこだわらず再検討されたいというのが区の立場ですよね。にもかかわらず、今のＪＲが勝手に示している計画どおりここに書かれているというのがどうしても意味がよくわからないので、ご説明いただけますかとの意見を述べました。","respondent":"阿部都市計画課長","answer":"区としては、住民の方の考え方がありますので、ルートに対して再検討していただきたいということは申し上げております。もう１点、位置にかかわらず、短絡線は鉄道ネットワーク上は有効だというふうに、私どもも思っていることは事実です。","id":"exchange-087"}]},{"id":"topic-09","title":"東品川四丁目地区地区計画の変更","agenda":"東品川四丁目地区地区計画の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"３点ですけれども、何がどういう感じになったのか、ちょっとそこだけ教えていただきたい。素朴な疑問であれなんですけれども、なぜ鹿島建設と住友不動産の開発に区が協力するんですか、教えていただけますか。","respondent":"青木都市開発課長","answer":"１点目の変更というお話ですけれども、資料の表の説明の中で、５番のこれまでの経緯のところでの私の説明だったんですが。これを、私ども支援というよりも、むしろ望ましい方向に開発が進むように誘導しているものという意識で取り組んです。","id":"exchange-088"},{"speaker":"中塚委員","kind":"意見","question":"誘導して、企業に対して環境への配慮を義務づけると、その分高い建物になるわけですよね。何かＣＯ２だ、その関係があるんであれば、ご説明いただけますかとの意見を述べました。","respondent":"青木都市開発課長","answer":"これは既に古い時代から用途地域も商業地域にしておりまして、容積率も５００％とか、７００％という指定があります。そういったことで、事業者もご納得いただける中で、区民にとってもよりよい環境にできるようにということで誘導しているものです。","id":"exchange-089"},{"speaker":"宮崎委員","kind":"質問","question":"さっきのこととも絡むんですが、これはオフィスだと思うんですけれども、まあこれは民間ですので、民間が勝手にやっているんだということなんですけれども、需要の予測というのは一体どういうふうになっているのかというのが、区のほうはどういうふうに見ているんか尋ねました。","respondent":"青木都市開発課長","answer":"品川区１４８に対して、お隣の港区は５２６ということ、一方南側の隣の大田区は１０１という数字になっております。就業機会の確保とかというようなまちづくりの視点から考えますと、企業立地というもの、誘致を図っていきたいということで開発を進めております。","id":"exchange-090"},{"speaker":"宮崎委員","kind":"質問","question":"朝夕の通勤時に非常にラッシュだと思うんですけれども、これができると、またすごく出るのかなと思うんです。そこら辺のアクセスだとか、そういうところの新たな需要だとか、そういう見込みというのは、どういうふうに見ていらっしゃるんか尋ねました。","respondent":"青木都市開発課長","answer":"品川シーサイド駅も新しいもので、そこそこの設備が整っておりますので、今回の建物２棟で大きな影響はないという試算をしています。","id":"exchange-091"},{"speaker":"宮崎委員","kind":"意見","question":"それが０.７５で、これから０.８６ということですと、相当増えるかなという感じがします。ちょっとそういう感想も持ちましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"}]},{"id":"topic-10","title":"小関橋架替整備工事の契約変更","agenda":"小関橋架替整備工事の契約変更","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"今、供用開始からほぼ３カ月経っているんですが、この３カ月間で全部こそげ取られてつるつるになっているような状態なんですね。このままそれを２年間使っていくのかと思いますと、１年が２年に延びたら、いかがか尋ねました。","respondent":"青木都市開発課長","answer":"私どものほうから、再度確認させていただいた上で、指導を徹底して皆様の安全を確保するように努めてまいります。ご指摘、ありがとうあります。","id":"exchange-093"}]},{"id":"topic-11","title":"品川区葬祭場の設置に関する環境指導要綱の改正","agenda":"品川区葬祭場の設置に関する環境指導要綱の改正","exchanges":[{"speaker":"井上委員","kind":"質問","question":"これは、指導要綱ということで、こういう形で改正をされたことはすごくよかったことなんですが、たびたび問題になる、要綱である以上、どれだけの効力があるのかというところでは、どういうふうなものか尋ねました。","respondent":"齋藤住宅課長","answer":"建築基準法に上乗せはできないことになっておりますので、地区計画では住民協定で決めたから、こういったものは建てられないという決めはできません。","id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"区がつくった要綱ですから、最大限、そちらを尊重して事業者に当たるという姿勢を貫いてほしいと求めました。まちづくり事業部ではなくても、区がつくったものを守らせるという姿勢を、区全体で貫いていただくことを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"中塚委員","kind":"質問","question":"２点目ですけれども、ああいう橙色のパンフレットというんですか、そういうのをつくる考えはあるんでしょうか。今、考えているのかどうか、まず２点教えていただけますか。","respondent":"齋藤住宅課長","answer":"葬祭場を設置したいという相談はありませんが、区の窓口に来られますので、建てる方に対しては説明ができていると思っています。区民の方一般に、葬祭場の要綱を変えたということを周知する予定はございません。","id":"exchange-096"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の変更点の、景観を損ねる公告物とありますけれども、公告物って何を指すのかという例示というんですか。２番目の商店街等、区が何を例示として考えているのか、あわせて説明を求めました。","respondent":"齋藤住宅課長","answer":"あまりにも大人数の方が来られるような葬儀は、管理規定を置いて受けない。あるような場合があったとすれば、必ず人を配置をして、商店街の営業を妨害するような行為にならないようにといったことを想定しております。","id":"exchange-097"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそういう例示も含めて、ちゃんと冊子をつくったほうがいいんじゃないかなと思いますので、その考え方を伺いたい。周辺関係住民から求めがある場合は、これが品川区で盛り込まれなかった理由というのはどういうものなのか、教えていただけますか。","respondent":"齋藤住宅課長","answer":"なかなか葬儀自体を抑止するような形での指導というのは難しいというのが、正直なところです。京都との関係ですが、今の私どもの要綱の中でも、そういった規定により住民の方とお話し合いをするような形に指導してまいりたいと思っています。","id":"exchange-098"},{"speaker":"中塚委員","kind":"質問","question":"こういう計画で進みますよと、その時点でいわゆる協定を結びなさいという、さらに踏み込んでいるんですね。その内容を、今回、盛り込まなかった理由が何かあるのかなと思ったので、そのことを伺ったんですんですけれども、僕の理解が間違っていたら。","respondent":"齋藤住宅課長","answer":"そういう意味で言いますと、京都より、私どものほうが厳しくなっております。要するに、事実上、立地させませんから。","id":"exchange-099"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3876#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":81454,"voices":291}},{"id":"h19-20070227-9","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"文教委員会","time":"午前１０時０２分～午前１１時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２枚目の資料に小一プロブレムということも書いていますけれども、どういった必要性というか、その問題意識というのをもう少し聞かせていただきたいなと思います。","respondent":"河野指導課長","answer":"それが１カ月、２カ月たって、これは就学前教育に問題があるのではないかというような指摘がなされております。そのような子どもの変化に対応するための就学前教育のあり方ということで、このような検討が進められるようになってきたという経緯です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。品川区内でも、そういった実態というのはやっぱりあったということなんか尋ねました。","respondent":"河野指導課長","answer":"この問題につきましては、どこそこで特定の区域、あるいは地域ということではなくて、全国的な傾向ですので、品川区内におきましても、そういう傾向は見受けられているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。教職員が交流して現状を指導に生かすというふうに２枚目の資料にもありますが、これは、そういったことも含めて交流ということなのか尋ねました。","respondent":"河野指導課長","answer":"それぞれの小学校に進学をしていく、いわゆる園児に関する情報交換につきましては、既にすべての小学校で積極的に取り組まれているところです。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"この文章を読むと「時代の要請を受けて自主的に」近隣の小学校がやり出したと。その自主的にやられたころの状況というのは、教育委員会では把握をされていたんか尋ねました。","respondent":"河野指導課長","answer":"ただ、単純に言いますと、いわゆるそれぞれのところで独自に行われていたという経緯があります。モデル園ということで取り組みを進めていくという背景は、それぞれがやっていた取り組みについて、特に予算編成をしたです。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"２、３年ぐらいの先生方というのはだいたい決まっているとすれば、実りを聞くというところから僕は始めるべきだと思うんだな。品川区では特にではないけれども、未然という部分も含めて、そういうところもむだにしないようにしてほしいなというふうに思いますとの意見を述べました。","respondent":"河野指導課長","answer":"小学校との連携、あるいは小学校側のほうも幼稚園との連携というようなことがかなり意識的に浮上してきたという、そういう経緯があるかと思います。今後、人事権が区のほうに完全に移ってきたあとには、そういうようなことも可能になるのかなというふうに期待をしています。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"やっぱり実施体験という、授業を１日受けるというのは、なかなかすぐは難しい。そうすると１日１時間、１時限だけ受けてくるということも大事なことだろうと思うんだけれども、そういうところまで入るんか尋ねました。","respondent":"河野指導課長、古里学務課長","answer":"現在も、一部の幼稚園・保育園では、そういうような形で実際に交流活動を行っているケースはあります。これからモデル校を中心として取り組んでいく中で、その情報提供の中には… 教室を借用した学校内の専用スペース等を活用して、小学校と保育園等の状況に応じた個別の年間計画により柔軟に実施する」ということがあります。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ちょっと言葉を説明しておいてほしいのは、上の「目的」という中の下から２行目に「将来の児童の現状を知り」ということは、どういう意味なんですか。どういうふうに位置づけていくのか、その辺の言葉と、あとのほうの内容との部分を聞かせていただきたい。","respondent":"古里学務課長、河野指導課長","answer":"それから、マイスクールのところについては、ちょっとこれは私は説明を聞き損ねておりまして、状況を把握してございません。これはわからないです。 １校当たり平均の数ですけれども、１名いるかいないかですので、今のところは個々に対応できる実態かなというふうに私どもはとらえております。申しわけございませんが、この事業の中に、現在は中学校は含まれておりません。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"いろいろ子どもたち、中学生にとって幼児にとっても大事な部分かもわからないけれども、特に中学生にとって。それは、これと切り離し、切り離しというか別の場所で続けていく、それは教育委員会としても支援はしていくというふうに理解しておいていいんですねとの意見を述べました。","respondent":"河野指導課長","answer":"そのとおりです。","id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"もしくは保育園それぞれ１校ずつというふうになるのか、それとも複数の幼稚園・保育園がその１校に対して連携していくのか、その辺のところを説明を求めました。","respondent":"河野指導課長","answer":"現在、それぞれのブロックごとの連携をする小学校あるいは幼稚園・保育園については、校長会あるいは園長会等を通して呼びかけをしています。","id":"exchange-009"},{"speaker":"武内委員","kind":"質問・要望","question":"幼稚園でも全園で今１００％、例えば同じ公立の幼稚園だと今８園ですか９園ですか、同じブロックのＢというところに行く方が例えばいますよね。自分は、そういうことも出てくるのかなと思ってお聞きしたんですけれども、どういうふうにお考えかということをお答えほしいと求めました。","respondent":"河野指導課長","answer":"あくまでも小学校という一つの枠に就学前の子どもたちがスムーズに就学するためのさまざまな取り組みというふうに私どもは理解しています。","id":"exchange-010"},{"speaker":"築舘委員","kind":"質問","question":"私立ということが書いてあるんですけれども、実際はお話を聞いていると、公立保育園・幼稚園との交流になっているような感じがするんですね。その辺の現状をどうするんか尋ねました。","respondent":"河野指導課長","answer":"金管バンド的な音楽活動を取り入れているとか、そういうさまざまな取り組みがありますので、こちらのほうから積極的にお声はかけしています。","id":"exchange-011"},{"speaker":"築舘委員","kind":"質問","question":"要するに区立保育園を中心にやってきた課ですから、どうしても保育園のほうを重視していくとか、幼保一元化の場合はいいですよ。私立幼稚園というのは別なわけですから、そこに任せちゃうと、どうしてもそこの全体の。","respondent":"古里学務課長","answer":"委員のおっしゃるとおり、先ほど、この就学前教育の充実ということを公立、私立を問わず進めてまいりたいというのが本事業の性格です。そうした観点から私立、公立の隔てない事業の展開に努めるように、私どものほうも努力してまいりたいと思います。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"さっき、未就園児が２１名という話があったんですけれども、全体像、公立保育園、私立保育園、それぞれ幼稚園、もしどんな割合でどれぐらいというのがわかったら教えていただけますか。","respondent":"河野指導課長","answer":"平成１８年の私どもでいただいている統計的なデータで申し上げますと、幼稚園のほうの就園率が、公立と私立合わせまして、５歳児ですが６１.７％。それから保育園の園児数が、公立と私立を合わせまして３５.６％という割合になってあります。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"前に文教委員会で、たしか佐賀でこれはかなり先行的にやっていたので、１年生の問題というのはかなり深刻化しているので期待も大きいんですけれども。品川区の単独なのか、全国の流れとの関係で、もしあったら教えていただけますか。","respondent":"河野指導課長","answer":"これは全国的にそういう傾向があるというふうに認識しております。ちょうど１年ほど前に、それぞれの地区ごとに積極的に取り組むようにということで、情報提供をいただいているところです。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"それで、子どもたちと接したい、あるいは子どもたちの要求は、アンケートをやると「先生と遊びたい」というのがトップなんですね。先ほどもちょっと話があったんですけれども、なりはしないのかなというのがちょっと心配なところがあるんですが、その辺はいかがか尋ねました。","respondent":"河野指導課長","answer":"委員ご心配の点については、私どももきちんと踏まえていきたいと考えています。現状において１学期の前半部分、かなりの時間がこういう傾向を持っている子どもたちの対応に追われているという実態を考えると、ここは。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっといいですか。そうもなかなか難しい面もあるだろうけれども、受けていくという第一歩が必要なのかなというふうに思うんですけれども、そういう意味でやってほしい。","respondent":"河野指導課長","answer":"それぞれの代表の方にご説明していますし、この取り組みに対する私立の幼稚園、あるいは保育園の立場からもご意見もいただいております。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/120587?Template=document&Id=4600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":19259,"voices":55}},{"id":"h19-20070227-5","meetingId":"h19-cm02","date":"2007年2月27日","dateIso":"2007-02-27","committee":"総務委員会","time":"午前１０時０２分～午前１０時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"平成１９年請願第２号、ＪＲ不採用問題の早期解決に関する意見書の提出を求める請願にかかる意見書","agenda":"平成１９年請願第２号、ＪＲ不採用問題の早期解決に関する意見書の提出を求める請願にかかる意見書","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"正副のところでまとめられた案文ということで異存はないですけれども、ちょっと寂しいかなという気がしまして、請願の中には別に入っていなかったんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"どういったものなのかということをもう少し聞かせていただければということと、そこら辺をもう少し教えていただいて、あと品川区としてはどういうふうに求めていくのか教えていただきたい。","respondent":"日下部企画財政課長","answer":"平成１９年度から具体的に算定するわけでありますけれども、算定の方法をどうするのか、それがまず１点。平成２０年度以降の取り扱いについてしっかりと都区間で、そういう姿勢でこれから取り組んでいくです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"資料に沿ってうかがいますけれども、都区財政調整方針ということなんですけれども、この方針を示したのはだれですかということについて、答えるよう求めました。","respondent":"日下部企画財政課長","answer":"この都区財政調整方針につきましては、協議は都側から、ずっと財調協議が続くわけですね。最終的には今年度については１月３１日の都区協議会、ここで都区双方でその内容について確認をされたというものです。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"都区間がいろんなやりとりの中で、今年はこういうふうに行動したよというふうに解釈すべきなのか、大きく分けてその二つがあると思うんですね。どっちだという意味なんか尋ねました。","respondent":"日下部企画財政課長","answer":"そのことによって効力が発効する。そういう仕組みです。","id":"exchange-004"},{"speaker":"塚本委員","kind":"意見","question":"１％上げれば自治の拡充の助けになるだろうなんて、だれがどういうつもりで言っているんだという、上から物を言っている。この文書はだれの責任で、どういうふうに出てきたんだということを改めて聞きますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"だれの責任でということでありますけれども、東京都の責任において原案が提出された。それに対して、都区の正式な法定機関であります都区協議会の場におきまして、両者で合意を見たです。","id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"都区協議の機関で合意を得たというなら、やはり、そういうことをどこかで表現すべきときに来ているんじゃないかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"先ほどちょっと冒頭でご説明申し上げましたけれども、１月３１日の都区協議会においていろんな経過はありましたけれども、最終的に確認されたということで触れさせていただいたものです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと一つだけ具体的なところでお聞きしたいんですけど、５ページにありますけれども、改築経費とかと出されていますよね。これはまだ２３区の枠組みの中で、東京２３区という協議の中での話になっていくのか、ちょっとそういう枠組みのところを教えていただけますか。","respondent":"日下部企画財政課長","answer":"これは要するに１年間の全体の財調三税、一つの見込みでありますので、これを立てる。これをスタートして、３月段階でほぼその区別の算定結果がはっきりしますので、流れとしてはそういう流れになっております。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"何となくわかるんですけれども、これで確定をしているという数字、再調整の中で、確定してしまった数字ととらえていいんか尋ねました。","respondent":"日下部企画財政課長","answer":"それはそういうことです。","id":"exchange-008"},{"speaker":"山村委員","kind":"質問","question":"今ビラが公費負担で無料で頒布できるとおっしゃったと思うんですけど、これは首長だけなんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"よく国政でマニフェストということで政党が政策を掲げたパンフレット等を頒布するができる。そういうことをしたらどうだということが検討されてきて、最終的にはビラを頒布するということに今回の法改正で決まったです。","id":"exchange-009"},{"speaker":"山村委員","kind":"質問","question":"区議選のほうも同じですけど、投票所一覧で、投票区名第１３投票区はシティコート目黒とあるんですけど、これはふつうのマンションか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"これはたしか都市整備公団がつくったマンションなんですけども、そこに居住者用の集会室というところがあるんですね。その１室をそこに住む人たちの利便と同時に、そのシティコート目黒のマンションの１室を使用させていただいている、そういうものです。","id":"exchange-010"},{"speaker":"山村委員","kind":"質問","question":"場所を本当に周りの人は理解しているのかなというのが、ちょっと小学校とかに比べるとあるので、その辺はどういうふうになっているんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"以前は誕生八幡という神社の１室を使ってやっていたんですけど、新しく入居、品川区に転入してきた人はなかなかわかりにくいということがあります。","id":"exchange-011"},{"speaker":"山村委員","kind":"確認","question":"こういう投票所一覧とかは区のホームページとかで場所を確認できるようになっているんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"投票所の一覧はホームページに載せていると、たしかそう思いました。","id":"exchange-012"},{"speaker":"山村委員","kind":"意見","question":"あまりわかりやすくないような気がするときがあるんですよ。もう間に合わないのかもしれないですけど、今後はそういうふうに、やはり住所から地図に飛ぶようにネット上でしていただいたほうがいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"山村委員","kind":"意見","question":"投票用紙の色というのは、どういう基準で何色だとか、さっきと色が違うのか。それからあと、区画面数が６０名というお話だったんですけど、今のところ、予定６０名で足りそうなのかとの意見を述べました。","respondent":"野田口選挙管理委員会事務局長","answer":"投票用紙の色はさして大きな意味はありませんけれども、明らかに説明しやすい色にする、そういうことを心がけております。一応５５人出て足りるかなという程度でつくってありますので、現時点では飛び込みが入ったとしても、十分対応できるかなというふうに思ってあります。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/495406?Template=document&Id=1748#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":16060,"voices":67}},{"id":"h19-20070228-11","meetingId":"h19-cm02","date":"2007年2月28日","dateIso":"2007-02-28","committee":"自治制度特別委員会","time":"午前１０時０２分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"そういうことをお聞きしたいのと、なぜという意味はわかるんだけど、内容の部分。ちょっと聞きたいんだけれども、品川区はどういう組織になるのか聞かせてくれますか。","respondent":"中山資源循環推進課長、堀越行財政改革担当課長","answer":"後ほど組織改正のご説明もする予定なんですが、そこに会計管理者を一般職で置くという形になっておりまして、課長級の職員を置きます。現在、副収入役が平成１６年度から代理を行っておりまして… 区のほうの事務改正の管理者への制度の変更につきましては、一般職という形でもちろん会計管理者を置くという形です。会計管理者については今のところの予定では部長級を充てるという形で予定をしております。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"わかっている範囲で結構ですから教えてほしいのと、四役、三役と呼ばれていたポジションなわけですよね。出るお金の管理が非常に大事な部分であるわけですから、きちんと責任が果たせるポジションになっているのかどうかという、それを聞かせてください。","respondent":"中山資源循環推進課長","answer":"ご質問がありましたように、当然、収入部分だけではなくて支出も含めた適正な会計の執行の確保を行うための組織ということで設置をするです。先ほどすみません、課長級となっているということは、課長級の会計管理者を配置するということではございません。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"確認","question":"説明するにはきちんとその辺を確認をした上でしておいてもらわないと困るし、大丈夫だという答えしかないんだろうけれども、大丈夫なんでしょうね。一応聞いておきます。","respondent":"中山資源循環推進課長","answer":"一組の今回の説明においても、必ずしも特別職である収入役という形で設置しなくても適正な執行が可能になってきているという経過の中で。会計事務に関しては、そういう中での適正な執行を確保する体制を図っていく中での、今回のそれに伴う組織改正というふうに認識しております。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"首長の権力が非常に大きく、ひとつ大きくなっていくということになるわけですから、きちんと仕事がスムーズに間違いなく進むように伝えてほしい。それだけお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"区側の要望なのか、あるいは区側の中でも小さなところと大きなところといろいろあるんですけど、あるいは都側のあれで入ってきているのか。それは自由ですから何を言おうといいんですけれども、ちょっと説明願いたいんですが。","respondent":"日下部企画財政課長","answer":"そういう前提のもとで検討委員会の検討が進められるというものでありますが、都側の認識としては事務を移管する。今まではどちらかというと、都区制度改革、自治権をどうやって拡充するかというところに力点を置いてずっと検討が進められてきました。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"確かに今の説明では、私は２３区のこのような形で２区あるいは３区が合併をするようなあり方、やるべきではないというふうに思うんですね。２３区の中で公然と議論はしていないけれども、区域のあり方を合併も含めて考えようというような実際の動きというのはあるんか尋ねました。","respondent":"日下部企画財政課長","answer":"この間、そういうところで正式にこれを検討の俎上に上げて議論をしてきたというような経緯は今のところないというふうに承知をしています。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"逆に、都のほうが総務局長を入れているのか、そこら辺の考え方はどういう形で総務局長は両方なっているのかなという部分が１点。その区側の対応の説明が今全然なかったんで、この部分の説明をしていただきたいというふうに思います。","respondent":"日下部企画財政課長","answer":"ですから、これはおそらく今まで以上に区長会で２３区の区長さん方が議論をしっかり集約をして、こちらの検討会に臨むということになる。ただ、これは高橋区長が以前から検討会の段階から言っておりましたけれども、非常にこれからの検討の中で一番中心なのは幹事会ですね。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"そこの実務的な部分を整理するこの３パターンなのかな、助役会とするならば、だれがどのようにやろうとしている部分なのか。それを教えていただきたい。","respondent":"日下部企画財政課長","answer":"区長会がどういう政策的なあるいは政治的な観点から１つの調整、判断をするか。ですから、さっき申し上げましたように、今回のあり方検討委員会を２年間の間しっかりと進めていく上でやっぱり重要な役割。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問","question":"そういうことをもちろんわかって言っているんですが、もちろん区を代表しているわけですから、もちろん区長会は最終判断をする。私は部長会ぐらいは最低必要なんだろうと思うけど、そこら辺の考えはどういうふうになっているの、水平調整の部分は。","respondent":"日下部企画財政課長","answer":"事務配分の検討ですから、いろいろなレベルの検討をしてまいりますので、論議の集約というのはできないということだと思います。ですからそういう意味では、委員に大分ご心配いただいておりますが、実務的な検討整理を行っていくということになると思うんです。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"これは議会は議会として対応するものは議長会もあるわけですから、今のところ、各区の考えをぶつけていくんだという部分が必ず部分的に出てくる。議会に対して１つは全体の、今の時点で決まっているというか考え方があるなら、教えてもらいたい。","respondent":"日下部企画財政課長","answer":"これから非常に重要なこういう制度的な問題について検討を進めていくわけでありますので、議会にいろいろバックアップいただく必要があるだろう。","id":"exchange-010"},{"speaker":"石田委員","kind":"意見","question":"非常に大きな問題も絡んでくるし、そうなってくるとある程度今みたいな形だと水平調整が議会も必要になってくる可能性があるわけね。どうしていったらいいんだということを、本当は区長とか助役がいるところで言うべき話だから、それだけお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"２３区が嫌だと言ったって都が言い出すとか、それをまた政治的に選んでいくという作業は、毎回いろいろ入っていかなきゃいけない。そこら辺が見えてくると少し今の話も見えてくるんじゃないかなというふうに思うんですけれども、そこら辺のところはどうなんか尋ねました。","respondent":"日下部企画財政課長","answer":"区長会の中で改めて今、例えば税財政部会とか３つの部会に七、その辺の勉強の成果も含めて区長会のほうに集約をして２３区間での調整を図っていく。そういったことを早目早目に２３区間の水平調整をやれるような体制づくりはこれから非常に重要なところだろうと考えておりますし。","id":"exchange-012"},{"speaker":"土井委員","kind":"意見","question":"２３区が全体にそのような格好でやっていかなきゃいけないとすると、品川はどうなるの、まず。皆さんもやってくださいというふうな形になっていかなきゃいけないんじゃないかなと思うので、品川はどうするのかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"これは前回、区長会でも強く主張してまいりたいというふうに言っておりましたけれども、非常にそういう意味ではかなり広範囲な議論が必要になります。","id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"そこに部長が行くときには、うちの少なくとも品川区はこういう対応、態度というのを全部そこに網羅していなきゃいけないんだと思うんですよね。その段階等でも我々のほうにも場合によっては意見を求めていただければ本当はありがたいんだけれども、そういう仕組みをつくっておいてもらって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"本田委員","kind":"意見","question":"見解をまとめて発表していくというようなことをやって、その辺はどのように区のレベルでは見通しているのか。その点をお尋ねしたいと思いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"確かに都と区の今のお互いの認識のずれというのは非常に大きいわけでもありますし、その辺どうなのかというのがまず１つ重要なことはそのとおりです。こういう２点にわたってご答弁申し上げておりまして、そういう姿勢でこれから品川としても動いていく、このような考えです。","id":"exchange-015"},{"speaker":"本田委員","kind":"質問・要望","question":"区民がどこの区民も２３区側はどういう姿勢でこの問題に臨んでいるということが、今後これを進めて行く上で非常に重要になってくるのではないか。ですから、もっと歯切れよく２３区の統一区長の見解を随時発表して進めるようにしていただきたいということを強く感じますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"そこのところの考え方というんですか、１つの動き方なんですが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"ただ逆にこの２年間という期間設定をする中で、それをさらにどうやって大局的な見地に立ってさらに検討を深め、方向性を出していくか。ただ逆に２年間ぐらいの期間をしっかり、あまりこれをだらだらと先に延ばしてしまいますと、また方向性を出すのもあいまいになってしまう。","id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"２年間も３年間も非常に難しいところだろうと思うんですよね。それから今お話のように７年間やってきたところであるので、一生懸命やっていくというところで、しっかりやっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"先ほど来出ているように２３区が全員が合意なんていうのは不可能だと僕は思っていますけれども、でもこの人もうやめるし、周辺区が多いわけだ。考え方として、品川以外の２２区の色分けというのは、品川区役所の企画では持っているんか尋ねました。","respondent":"日下部企画財政課長","answer":"これだけで見ますと、それぞれの区長さんによっていろいろ考え方も違いますから立地の条件だけで見るわけにいかなんですが、港区は都心区ですね。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"もちろん２３区の考え方をまとめながら出ていくというお話もあったから、２３区の考え方をまとめていくほうが都側と交渉するよりは難しいと思う。スケジュールの中に入っていって、区側の考え方をまとめるということについて、区長会はどういうコメントを発しているんか尋ねました。","respondent":"日下部企画財政課長","answer":"いずれにしろ、都区のあり方について抜本的な検討をしっかりやっていこうということで。おそらくこういう機会、最後はやはり大きな立場から判断されるという方向で区長さんに頑張っていただくしかないと考えております。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"確認","question":"その次にどういう事務をという、そういうことをここで言っていても、事務局にはそういう情報はないですかね。それをしっかり踏まえているんですねという確認をしておきます。","respondent":"日下部企画財政課長","answer":"２３区個々の利害の問題もありますけれども、やはり都と区のあり方をこれを機会にしっかりと議論をしていく、まとまっていく。難しいことでありますけど、非常に重要なことだというふうに考えております。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"確認","question":"２番が具体的な事務移管の是非を判断する。前２段は総論的、抽象的、事務ということになると総論的な仕事が進められるのかなというふうに思うんだけれども、その辺の確認を説明を求めました。","respondent":"日下部企画財政課長","answer":"そういう形で１から３というのは一応セットでこういう判断をしていく。そういう仕組みになっているものです。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"今、言っているように公園の広さで決めるのか、あるいは用途で決めるのか、そういう基準が決まったら３番は決まってくるじゃないですか。そういうふうに理解すればいいんか尋ねました。","respondent":"日下部企画財政課長","answer":"１で大きく、当然それを踏まえて３に自動的にといいますかね、そういう流れでいくのではないかというふうに考えております。ただ、２がすべて３というイコールということにはならないと思います。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"前２段のこういうふうに説明がされてきたときに、２番の説明で来たときにおのずと具体的な事務は全部ここに羅列されている。そういうふうに考えていていいんですねって聞いているんですとの意見を述べました。","respondent":"日下部企画財政課長","answer":"ちょっとこれ、もう少し具体的な事例としてご説明させていただきませんと、正直言いまして私自身も十分整理できていない部分もありまして、この辺はもう少しまた具体的な事例も含めて、その辺はまたご説明するような機会を持ちたいというふうに考えております。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"４番なんだけど、面積あるいはこれは大事なことだけど、２３区だけの話ではなくなってくる問題もある。そういうことを検討するということなんか尋ねました。","respondent":"日下部企画財政課長","answer":"視点ということでありますので、今、委員がおっしゃったような人口、面積はもとより、そういう今の区を取り巻く首都の問題とかいろいろそういうお話もございましたけれども、その辺を視野に入れての視点という表現になっていると考えます。","id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"この部分については触れていないわけで、一品川区、２３区の中の２３分の１という立場でどう考えるのか。それは品川区としてどう考えていらっしゃるのかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"非常に難しいところでありますけれども、確かにおっしゃるように品川区としてどうなんだ。このように考えています。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"質問","question":"基本構想、４次長計を検討していく、変えると区長はおっしゃられているわけだから、だったらこの問題を品川区としてどうとらえる。考え方を早急にということじゃないけれども、入っていかなければいけないと僕は思うんだけれども、その辺いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"２０年度で基本構想、ご指摘にありますようにしっかりした検討をした上で、構想計画の中にその辺の基本的な考え方を盛り込んでいく。これはもう当然のことだと思います。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"意見","question":"それはお願いしておきます。決意を述べますかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"しっかりした議論を検討してまいりたい。","id":"exchange-028"},{"speaker":"石田委員","kind":"確認","question":"今の話で１点だけ確認したいんだけど、さっきも言ったんだけどはっきり聞いておきたいのは、相差の部分をしっかりやっていくにはという部分なのか。国際フォーラムが来たら受け取った区はどうするんだという話にもなるわけだから、受け取れないその基準、そういう理解でいいのかね。","respondent":"日下部企画財政課長","answer":"昨年の検討会の中で大分入っていたんですが、今後の検討委員会の検討にあたっては、この財源配分の問題というのはひとまず置いておきましょう。そういう今までとは少し論議の進め方を大きく変えているのが今回の検討委員会の進め方であるということでご理解いただきたい。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"あるいはそういうこともきちんと報告をするようにしていってもらいたい。２３人の退職をされる方が新会社へどういうふうに動くのかとか、所管する委員会へ僕は報告をすべきだと思いますけれども、その辺はだれが答えるのとの意見を述べました。","respondent":"中山資源循環推進課長","answer":"若干人数が少ない４０人程度の体制で大田工場内には東京エコサービスの大田管理事務所という形で事務所を設置して運営していくというふうに聞いてお…清掃工場の行政のＯＢが中心になっていくという体制で安定的な運営を図るということを聞いております。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"この表にある出先機関の清掃工場でマイナス２３という方々がいらっしゃって、この人たちともその新しい会社に行くんですかって聞いているんです。","respondent":"中山資源循環推進課長","answer":"この数字がそのまま新会社に行くという形ではございません。いわゆる行政ＯＢが先ほどのところだと１３～４名になるですから、全体の中での現実の数は２３です。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/523861?Template=document&Id=5612#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":32439,"voices":88}},{"id":"h19-20070228-16","meetingId":"h19-cm02","date":"2007年2月28日","dateIso":"2007-02-28","committee":"街づくり特別委員会","time":"午前１０時０２分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"本日は、災害に強い街づくりに関することのうち、密集住宅市街地整備促進事業","agenda":"本日は、災害に強い街づくりに関することのうち、密集住宅市街地整備促進事業","exchanges":[{"speaker":"南委員","kind":"質問","question":"それは一定程度の時間、民間の方々の自主的な意識を高めていくということが伴うわけですから、大変苦労されるところだというふうに思うんですよね。いつまでたっても改善はされていかないというふうに思いますので、改めてちょっとそのことをよくお伝えしておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"５５０棟ぐらい、５００棟ということですか、明確に補助２９号線の整備を関係部局に働きかけるということで打ち出されているわけですから。この間、協議会の中で、反対の声もありましたという話がありましたけれども、そこを説明を求めました。","respondent":"伊勢住環境整備担当課長","answer":"全体の説明会ですけれども、もちろん発言の機会が全員にあるわけではありませんけども、１名ございました。積極的に賛成という声は、その中では聞いてございませんが、説明会では、非常に反対だというような雰囲気ではございませんでした。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"すみません、私がお聞きしたのは、さっきも言ったように、２９号線の整備を担当部局に働きかけるという以上は、実際に２９号線の線引きをされた中にお住まいの皆さんの賛否というのは、当然、聞いているということなんだと思うんですけれども、そこをちょっとお聞きしたんです。","respondent":"伊勢住環境整備担当課長","answer":"密集事業のまちづくり計画（案）に２９号線の位置づけをしておりますが、それでこの放射１号、これを抜いてこの計画を立てるわけにはいかない。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"考えていないというのは非常におかしな話だと思うんですよ。うちの宮崎議員が質問したときも、そうすると、そのことはやらないよという話なんでしょうかね。","respondent":"伊勢住環境整備担当課長、福田まちづくり事業部長","answer":"こちらの計画（案）は、そのために地区の皆様、特にその２９号線に係る方だけ特別に呼んでとかということは考えてございません。現実的に道路が整備されていくというようなプロセス、その時点で… 都市計画道路全般に言えることですけれども、これは既に都市計画決定をされておるものです。できるだけ丁寧に説明をし、何かで決をとる、こういうふうな性格のものではないというふうに考えております。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"ここに書かれていないんだったら、それは確かにおっしゃるとおりなのかもしれないんですけれども。もう４月には事業実施というんでしょうかね、都に対して計画を上げていくという話ですから、ちょっともう少し詳しく教えてもらえますか。","respondent":"福田まちづくり事業部長","answer":"この都市計画を無視、軽視をして、このまちの将来を語ることはなかなか難しいだろうという意味で書き込んであるものです。私ども、この都市計画道路は必要なものであるというふうに考えておりますので、十分な理解を得るように最善の努力を尽くしたいというものです。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"このまちづくり計画案の説明にしても、１月２５日と、あとあしたですか、２７日にやるというわけですから。これ、一体いつ、どこで、だれが、理解を得るために説明をし、論議をするんか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"この２９号の道路事業が着手されるときには、そのときには東京都が地権者の方々への十分な説明と理解を行う、これは当然のことであります。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、やっぱりそこの住民の皆さんの意見を聞くべきでしょうし、私よくわからないんですよ。ですから、一体いつ、どこで、だれが話をし、論議するのか、ここだけは徹底的に決めていただきたいなというふうに思います。","respondent":"岩田まちづくり事業部次長","answer":"実際、説明会をやりますと、表向き反対というのは若干ありましたけれども、やっぱり思ったほどではない。２９号線の地権者の方もいらっしゃるわけですから、それに対してはきちっとお答えしていく、こういうことです。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"ほかに移したらどうなるんだみたいな話を次長はされていたけれども、今の話というのは、これもやっぱり単に品川区は決められないということ。でも、実質的にはそこにいらっしゃる方たちを追い出すわけですから、全く民主主義という基本概念がないまま推し進められるという感じがしますけどね。","respondent":"岩田まちづくり事業部次長","answer":"この２９号線を含めて、これ住民が反対されているので廃止してくれと、こういう言い方はできないですね。こうすればいいんではないでしょうか、だから廃止してくださいとか、あるいは移してくださいという、こういう責任を持った対応をせざるを得ません。","id":"exchange-008"},{"speaker":"菊地委員","kind":"意見","question":"最後にしますけども、要するに、今の２９号線、ここで事業促進をするという地域にお住まいの皆さんというのは、犠牲者なわけですよね。だからこそ、本会議でも答弁されていたように、住民に理解を得る体制づくりをしてくださいということをお願いしているんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"確認","question":"ちょっと確認なんですが、あれですよね、あらかじめ都市計画道路ですよということを了解の上で建てているということではないんでしょうかね。それだけちょっと説明を求めました。","respondent":"片田建築課長","answer":"都市計画法の５３条１項ということで、必ず、２階建て以下のものは許可しなければいけないといった規定があります。今、３階まですべてを認めるということになっていますので、きちっと建て主の方にご認識していただいた中で建築許可をしているというような状況です。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうのは了解のもとでやっているんですから、その辺はぜひきちんと説明していただいて、ご理解を得るようにしてほしいと求めました。私、ちょっと１点、不燃領域率っていうのがありますが、これは、中身としてどういうことか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"それが例えば８０のうち２０あったとすると、空地の２０と、それからこっちの２０で４０と、こういうふうな形になります。基本的には幅６メートル以上の道路、半径１０メートル以上の土地、これらを空地といっております。","id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"３０年、場合にすれば５０年、１００年かかる事業だと思うんですね。それをちょっと希望として言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"私もこのときにちょっと出席させていただきましたけど、要するに、お尋ねしたいのは、協議会を１０回やってきたと。あしたですか、４月から実施しますよというふうに我々、理解するのか。","respondent":"伊勢住環境整備担当課長","answer":"１月３１日に、ニュースでもちろん全戸配布しましてお知らせするとともに、説明会への参加を呼びかけたです。事業開始前にニュース等でお知らせをするという形で、説明会は特に予定しておりません。","id":"exchange-013"},{"speaker":"堺委員","kind":"意見","question":"そうすると、事業は、もう説明すべきことはしたと。何かあれば個々にというふうにとれたんですが、もう１回、ちょっとの意見を述べました。","respondent":"伊勢住環境整備担当課長","answer":"出席者が全体からするとそんなに多くありませんので、協議会以外の方々からのいろんな問い合わせに答えていきたいというふうに考えております。できるだけご理解していただくように、いろんな方法を使って、地域の方にお知らせをするというふうに考えております。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問","question":"遅々として進まないわけですから、そういう意味での、これからこちら側として進めていくには丁寧にというふうに思います。私は、可能な限りこの防災生活道路Ｂという幅員６メートルに拡幅するところについて、可能な限りそうしてほしいなという気がするんです。","respondent":"伊勢住環境整備担当課長","answer":"４メートルで電線地中化している例はほとんど、銀座で若干あるそうですけども、技術的には難しい状況です。耐震性の高い建物に改善することで防災性の向上につながるということを説明するとともに、検討はしていきたいと考えております。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"見通しというんですかね、腹案というんですか、そんなものはあるんですか。今ある３つの公園から離れた場所と想定されるのはこの辺だろうと、腹案的なものがあって、その辺はいかがなんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"例えばですけれども、あるいは区のほうとしては駐車場のところで公園にならないかとか、地域に入ってやっていく予定です。それから、先ほど、失礼しました、銀座のほうは狭い道路じゃなくて、広幅員ですけど、あそこは地下にこういう機器を埋めたです。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"いろんなご事情等もあって来られなかった場合ですかね、要するに区の方からはこういうところについて、いわゆる積極的に説明をされているのかどうか。要するにお願いしたいのは、防災上というんですかね、ここに住んでおられる方々の意向はどうなんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"一遍に８０戸というのは難しいですので、その辺の進め方、そうでない方も。それらの意向を伺いまして進めてまいりたいと。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"Ｃ地区と言うんですか、なかなか地権者のご理解とご協力をいただけなかったというふうに言っていいのかどうかわかりませんが、進められない。浪花会通りと昭和通り商店会ですかね、この商店街通りについて、この辺についての商店街の人たちの意向はどうなんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"調和のとれた商店街の街並み形成をはかるということで、特別このゾーンになって、こんなようなことをやりますとかということはございません。容積だとかそういうのもありますから、そういうのを追認と言いますか、現状を踏まえた形でゾーンの位置づけをしたということです。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"公園というふうに位置づけているのかどうかわかりませんが、駅に行く人なんでしょうか、大変な悪臭と合わせて大変なことになった。何か工夫されていったほうがいいかなという気がするんで、その辺、いかがか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"協議会で町歩きしたときにも、あの時計台の下にごみがたまるというようなことがございました。具体的にどうこうというようなご提案は特にありませんでしたけど、今後、いい形になるような形でそこの三角地帯を活用していきたいと思います。","id":"exchange-019"}]},{"id":"topic-02","title":"の２その他","agenda":"の２その他","exchanges":[{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"皆さんからご意見をお伺いしたいのは、調査を完了すべきか、または継続にすべきかという点です。何かご発言ありますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/823348?Template=document&Id=6342#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":20671,"voices":53}},{"id":"h19-20070301-14","meetingId":"h19-cm03","date":"2007年3月1日","dateIso":"2007-03-01","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件整理しています。","topics":[{"id":"topic-01","title":"１の特定事件調査を行います。 （１）の民間委託等に関すること","agenda":"１の特定事件調査を行います。 （１）の民間委託等に関すること","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"確認をさせていただきたいと思うんですけれども、平成１９年度より運営されるということをおっしゃっていましたけれども、ここの議論をもって決定という流れになってしまうのかどうなのかという２点をお願いします。","respondent":"堀越行財政改革担当課長","answer":"庁内の中で全体検討会等も開いて、議論をしながら進めてきているというものです。ですから、平成１９年度より運用を開始していきたいというふうに考えております。","id":"exchange-001"},{"speaker":"井上委員","kind":"提案","question":"今、説明をされた中でも読み込めない部分とか、確認をしたい部分とかというものがたくさんあると思うんですね。ただ追認機関ではないわけですから、議論の中に入る前に要望して、議会のほうでも検討していただきたいということをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的な質問ですけれども、この中で議会の位置づけというんですか、これがちょっと見る感じ浮かんでこないんですよね。ＰＤＣＡサイクルの中にも、この冊子自体の目的としてあるでしょうけれども、その考え方をちょっと教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"このガイドラインの考え方は、区と指定管理者の間の関係として、より良い施設運営に当たっての考え方をまとめたものです。必要に応じてご報告するべきものはご報告していくというような考えは変わってございません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"それもなくして適宜という、それではちょっと議会の位置づけはどうなのかなと疑問に思ってしまうので、そこをちょっと教えていただきたいのが１点目。そこをちょっとはっきりご説明いただきたいし、ちょっと薄いんじゃないかなと思うんですけれども、お考えを教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"３年目終了時評価というお話がありましたけれども、やりながら適宜といいますか、ご報告をするという考え方はまず基本のベースであります。それともう１つ、そういったいろいろな場面を利用しながらご報告はしていきたいと、基本的な姿勢はそういう形で持っております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"具体的に例えば伺いますけれども、３７ページに記されている総括シートや事故報告書、行政情報の部分は公開の対象として考えているのか。ちょっと適宜というだけだと、それは何なのかなというふうに思ってならないんですけれども、もう少し具体的に教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"先ほどもご説明させていただきましたけれども、そういった部分、さまざまな場面を活用しながらご報告を必要に応じてするという考え方です。情報公開については、情報公開の条例にのっとって対応していくという形で考えてあります。","id":"exchange-005"},{"speaker":"中塚委員","kind":"確認","question":"３４ページから３７ページのこの報告書の中身は基本的な行政情報部分に関しては開示をしていくということでよろしかったのか確認をさせてください。それを含めた人員配置なのかどうかちょっとわかりませんけれども、その職員配置の状況は、今後つかんでいきますよということなんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"この総括シートの部分については、条例に基づいて公開をするです。これについては、先ほどから繰り返しの答弁ですけれども、そういった部分は必要に応じてという形で考えているところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん行政のほうから一方的に変更する場合は、とんでもない話ですけれども、その変更によってサービスを受ける利用者の利便性というんですか。議会のほうでいいのか悪いのか意見を求められますと、安全の最も重要な機構ですから、僕らも議決した責任があるわけですから。","respondent":"堀越行財政改革担当課長","answer":"ただ、その中で適切に業務が遂行されているかどうか、それを一定程度の把握は区として必要だということで、そういった部分の報告を求めたです。一定のモニタリングの中で必要に応じてご報告等は考えていきたいというのは、先ほどからご答弁させていただいているとおりです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"いわゆる人員配置を把握するとは何を具体的に把握をすることを意味しているのか、ちょっと具体的に人員配置とは何を指しているのか、最後にご説明いただけますかとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"こちらの部分についても、様式で定めて入れてありますけれども、施設の性格によっても違ってくると思います。社会福祉の関係のそういった福祉施設設置基準等があるところと、いろいろ施設の特性に応じて把握をしていくという、そういうことです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"２６ページのところの趣旨でもありますけれども、やはりどういった条件で人員が配置されているかというのは、そういったことに関しての区の把握というのはいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"より良い施設の運営が図られているかというところを考え方として指定管理を行っているという部分ですので、労働関係の部分については、そのような考え方です。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"やはり一定、そういった視点が必要になると思うんですけれども、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"団体なりとして、そういった労働関係法令を守ることは当然のことですので、区としてはそういうところを指定しているという考えです。ただ、それに対して日常的なチェックといいますか、指導等については、その法人のほうで対応すべき問題というふうに考えております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"これはあってはならないことなんですが、万が一、法令順守がなされていないということが判明した場合の区の対応だけ教えていただければと思うんですが。","respondent":"堀越行財政改革担当課長","answer":"労働基準監督署等によりまして対応がなされるものと考えております。その対応状況等を見ながら、また必要があればその時点で判断をしていくという、こういうことになろうかと思います。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"質問は、どう活用していくかということの説明がなかったように思われますので、そのことについて改めて説明をいただきたいのが１つと。ですから、実はそこが一番大切なのかなと思ったりしますので、そのことについての品川区の考え方を説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"まず基本方針といたしましては、この後ろの部分についてあります指定管理者制度活用に係る基本方針、これが基本原則になるものです。このガイドラインも進めていく中で必要があればまた見直し等も図っていきたいというように考えております。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのところの最終的な力量を判断する仕組みを品川区が責任をとっていくわけですから、そのことについて再度確認の答弁をいただきたいのと、それから。その出口のところと言ったらいいのでしょうか、契約のところまでの考え方をお聞かせいただきたいのと、事務事業評価を品川区はやっていましたよね。","respondent":"堀越行財政改革担当課長","answer":"このガイドラインをつくるに当たりましても、全庁的な検討会を開催しまして、議論しながら進めてきたという部分があります。その中で先ほどご説明した３年目の終了時評価ですとか、それから、そういった形での活用を図っていきたいというように考えております。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"例えば３年間は指定業者をやってくださいとか、つまり、品川区がはっきりと責任の所在を追求できるものがまずそこにあった上で３年間やってください。そこまである程度縛りをかけていかないと、立ち上がるまではちょっと怖いなという感じがするんですが、このことについてはいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"ここの部分について、先ほどご指摘がありましたような３年間の禁止、なかなか難しいかなというように考えております。今回、モニタリングの項目としても入れておりますので、そういった中でしっかりとチェックをしていきたいというふうに考えております。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、さっきの所管職員との関係があるんですが、やりっ放しというのはいけないと思うんです。ですから、利用者サービスが行き届いているかどうかというのは、これは最後は意見です。","respondent":"堀越行財政改革担当課長","answer":"今回、全庁的な検討会を設けて指定管理業務にかかわる担当課長、それから係長等を集めまして議論をしながら進めてきたというところです。２点目の文書なのか回答なのかという部分ですけれども、日常的な協議ですとか、そういった部分がまずあります。","id":"exchange-015"},{"speaker":"川西委員","kind":"意見","question":"新任、異動の場合の研修、これをぜひ考えていただかないと、温かい指導ができないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"そのあたりが今度どういうふうになるのかなという点と、今度、そのあたりをどういうふうにするのかなと思うことを教えてください。我々が２日前に出されて見てくることはこれで大丈夫だと思うので、できるだけ早く、それをまとめられたのが今回だと思っています。","respondent":"堀越行財政改革担当課長、新美企画部長","answer":"施設の設置条例がございまして、その中の設置目的等がございまして、先ほどご説明した年次協定の中で。その後また指定管理者としての手続を経ていくという、そういった手続きで言えば、同様の手続きを進めさせていただいているところで… 変更の問題ですが、変更の問題は重大な瑕疵があって排除する場合はちょっと別といたしまして、そういう政策上の５年たたない上での変更というのは。それは事例事例で適切に対応していくということになるかと考えています。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"ですから、管理者にどうのこうのというのではなくて、いろいろなことが出てくるなと思っているんですよね。我々は今、議運でいろいろまだそのあたりを詰めていかなければいけないのかなと思うんだけれども、理事者のほうはどういうふうにお考えかなと。","respondent":"新美企画部長","answer":"区として管理をしていくかというところの問題です。新築する場合は、導入時ですが、そこは導入時は十分指定をきちんとしていただけるような報告をしていくべきだというふうに考えております。","id":"exchange-018"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、その受けた業者がどういうサービスをノウハウを使って知恵を絞って実施をしていくか。今回、受け手をどういうふうに吸い上げていくかというのが大事だと思うので、その辺はちょっとどういうふうにお考えなのかをお聞きしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"今、区民の意識というようなお話がございましたけれども、いろいろ今、ご説明させていただいた中で、利用者アンケート等がございました。それをどう生かすかによって、そういった部分はこのガイドラインの管理の運用をしながら十分に検討していきたいというように考えております。","id":"exchange-019"},{"speaker":"藤田委員","kind":"質問","question":"ですから、これは例えば５年なら５年、そうした体制をぜひとれないものかどうかと。これは区としても大事な作業だと思うんですが、それだけお伺いしておきます。","respondent":"堀越行財政改革担当課長","answer":"このガイドラインの中におきましても、直接区の職員が現地に赴きましていろいろ現場を見たりですとか、意見交換するところがあります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日１回、ぜひ中身をどんどん改善していって充実をしていただきたいので、まず先に言いたいと思うんですが。そういう部分をどうつかんでいくのかが大事で、その辺をどうお考えなのか、まず２点お伺いします。","respondent":"堀越行財政改革担当課長","answer":"まず第１点目といたしまして、先ほどもご説明しましたけれども、その他いろいろなさまざまな方法を取り混ぜながらやっていくという考え方です。それともう１つ、より適切にモニタリング・評価を行っていきたいというふうに、そういう予定です。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"その辺をちょっとお伺いしたいのと、４４ページのところに、私はここのところをもっと透明性を高めるべきであると思うんです。この間、公開にできない部分について明らかにするという姿勢がより透明性を確保するということにつながると思うんですが、この辺はいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"再委託先管理の情報公開の部分については、そういった区と協議を進めながら対応していくという形になるのが基本だと思います。議会に対しては、先ほども申し上げましたけれども、必要に応じてご報告をするというような考え方です。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４４ページのところの審議について、私は原則は公開、私はこういう文書について原則公開というところにぜひ踏み切っていただきたいなと思います。適宜議会に報告ということなんですけれども、議会が直営と同じようにチェックができることになるのかどうか、そのところを再度お尋ねをします。","respondent":"堀越行財政改革担当課長","answer":"先ほどご説明をいたしましたけれども、いろいろな委員会の場、それから予算特別委員会、決算特別委員会の場等もありますし、例えば事務事業概要の中でそういった施設についてご質問いただくですとか、いろいろな場面でご報告をするというふうに考えているところです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後のところが、直営と同じようにチェックができる仕組みになるのかという、そこを答えていただきたい。","respondent":"堀越行財政改革担当課長","answer":"繰り返しになりますけれども、予算特別委員会等の中でご意見、ご質問いただく形で十分チェックしていただけると考えています。","id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"このモニタリング・評価のプロセスの中でアンケートの実施というのがあるわけなんですが、これを見ていますと、このアンケートの実施というのは、指定管理者が行うということか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"基本的には指定管理者側のほうで行うです。","id":"exchange-025"},{"speaker":"中島委員","kind":"質問","question":"そのアンケートなんですが、利用者に対するアンケート調査でしょうか。それとも、それ以外の方なのか、利用者を面倒を見ていらっしゃる方、家族とか、そういったところからもアンケートをとるのか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"施設の性格にもよると思うんですけれども、基本的には利用者の方を考えています。福祉施設等によっては、利用者の家族の方ですとか、そういった部分についても考えられるかなです。","id":"exchange-026"},{"speaker":"中島委員","kind":"質問","question":"中には利用者がそこでお世話になっているという立場になっている場合もありますので、果たして自分が思っていることを十分にアンケート調査に答えられるのかどうか、その辺に対する配慮はどういうふうにしていらっしゃるかお伺いします。","respondent":"堀越行財政改革担当課長","answer":"そういったことは考えられると思いますので、活用できる部分は活用しながら、利用者の方の声を反映させていきたいというように考えております。","id":"exchange-027"},{"speaker":"中島委員","kind":"質問","question":"第三者評価の方がアンケートをとるということですか、そういった場合は。","respondent":"新美企画部長","answer":"サービスを運営しているところが基本的にやるというのは、そういう趣旨で、基本は指定管理者が利用者の方のご意見をきちんと把握するということです。","id":"exchange-028"},{"speaker":"中島委員","kind":"質問・要望","question":"確かに今、この福祉の施設に対しては、やはり私たち現場の中でいろいろな形で情報が入ってきているわけです。ですから、また、より良い運営ができるように指定管理者に指導していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"意見","question":"つまり、ちょうど年度が変わる時期ですので、平成１９年度からされていくのかということが１つ。業者側のいろいろなプランをつくってきていただいた上で応札したほうが、と思われますので、その２つをお答えくださいとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"平成１９年度からスタートする予定です。それとあと、協定書のほうにもモニタリングという項目を入れて対応をしていくという予定です。","id":"exchange-030"},{"speaker":"井上委員","kind":"提案","question":"１つは、先ほどの改善をしたところにおいて最終的に事業者と区と経営会議で決定をした改善提案があるとすれば、いろいろなプールの事故だとか。区長の方針である区民の声を聞くとか、情報提供の考え方ということだけ先ほどの私の提案に対してご意見があればお聞かせほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"その定着をさせ、より良い施設運営を図っていく中で、その公表の部分についてはまた検討をしていきたいというように考えています。これについても個別に応じて対応をするべきものかなと思っています。","id":"exchange-031"},{"speaker":"井上委員","kind":"提案","question":"どういう改善があったのかということを私たちも区民の方から伺って、いろいろな意見を提案する予測とか、もうそれでいいでしょうということではなく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一番下の４の小中一貫校６校構想のところを、やっぱり学校の統廃合が前提になっている内容ですから、これは私たちと意見は違う。この２点を含めて、どうして両論併記にしなかったのか、そこを委員長のご意見も伺いたいんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"「原則社会福祉法人」であれば、その辺の意向をちょっと伺いたいのと、４のところですけれども、小中一貫校６校構想のほうですよね。だから両論併記をすべきではないかというのが私の意見であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"私も４番のところの小中一貫校６校構想は出されたけれども、この部分で提言いたしますという部分が４番に載ることは困ります。そこのところは慎重に対応すべきだというふうに考えていますので、どういうふうにすれば、検討をしていただきたいなというふうに思います。","respondent":"本多委員長","answer":"前回さまざまな意見をいただいた上で、検討した結果、このような文言修正をさせていただきました。これはもう皆さんから理解を得られるのではないかと自信を持って今回お示しをさせていただきました。","id":"exchange-035"},{"speaker":"川西委員","kind":"質問・要望","question":"小学校２校、中学校１校があくわけですから、それと同時に、例えば今、要望されている老人施設、子どもの施設はもう要りません。ですから、どっちが重点に今の企画部を中心に区がお考えになっているか、それだけ聞いておきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"須藤委員","kind":"質問・要望","question":"下から２行目のところで、「住民の声を広く求めるとともに、「区政全般的な視点で」というような表現にしたほうがいいかなと思います。ここにどうしても書きたいというのなら、なおかつ印をつけて、少数意見としてこういうことがあったよというような表現であればいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私、ここはしっかり確認をしていかなければいけないなと思っています。そういった面では、あくまでも今後生ずる公有地の跡地についての活用について論議をしてきたというまとめにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"須藤委員","kind":"質問","question":"今の４番目は、あれは基本計画の中に構想として出てきているんですから、それはもう当然前提の話だろうと我々は認識しています。そういうことを含めての考え方をもっと広くご提言いただいたなというふうな認識ですので、学校跡地ということで書いていいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"井上委員","kind":"意見","question":"６校構想の計画というようなところを削除して、そこら辺は先のこととして予測されることでもありますので、そういう話でよろしいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"藤田委員","kind":"提案","question":"この（２）については、これは丁寧な意味で（社会福祉法人等）という委員長のほうでご提案されたのではないかと思うんですが、しかし。ですので、委員会としては、そうした対応をするために、この４番を入れるべきだというふうに私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問","question":"行財政改革特別委員会として１つの方向性を持ってまとめたわけですから、ですから、私はそれはまとめにはなじまないと考えています。ですから、当委員会として１つの方向性を示すべきでもあると思っていますので、最終的には正副委員長に一任していこうと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"中島委員","kind":"意見","question":"６校構想と決めつけると、今のところ、品川区では６校構想により学校跡地という問題が出ているのは現実なんですね。６校構想と決めつけるのではないということであれば、「６校構想などにより生ずる学校跡地」と、こう思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"西本副委員長","kind":"提案","question":"確認をさせていただきたいのですが、まず、公有地等の活用に関することというのが大きなテーマになっております。その場できちんと話をしている段階のものですから、先ほど須藤委員の提案がありましたように、ここで議論するべきでもないものを議論するのはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"川西委員","kind":"意見","question":"それから、言うならば、（２）番目、西本副委員長のご意見ですと、要らないんじゃないかと思います。これであとは正副委員長にお任せしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"提案","question":"今の委員長のまとめで一任するというわけにはいかないと思っています。飯沼委員から先ほど具体的に提案がありましたけれども、この（２）のところで「等」をとるとか、あとはお任せしますというわけにはまいりませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"藤田委員","kind":"質問","question":"そうしましたら、「社会福祉法人を含め、民間事業者に委託するにあたっては」とされたらどうですか。ちょっと私の意見ですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"今の「社会福祉法人等を含む民間事業者」と言ったら、全く先ほど私が言っている中身に反してしまうわけですよね。そっくりこの（２）は削除をしていただくほうが一致するのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"川西委員","kind":"質問","question":"この括弧を全部とるということは、それだったらかえってこのまま入れておいたらいかがでしょうか。区というのは民間業者で、株式会社中心なのかという意向をこの委員会でまとめたということになりまして、それですと私は承服できない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"須藤委員","kind":"質問","question":"民間事業者の中には社会福祉法人も入ってくるんですから、もっと大きな視野に当委員会ではという考え方ですから、このあたりでまたノーになってきてしまうといろいろ大変だと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"川西委員","kind":"提案","question":"ですから、やはり括弧書きは最初の提案なんだから、むしろ入れておいたほうがいいと、含むということですからというふうに思います。多数決のところですから結構ですよ、このまま通していただいてもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"中塚委員","kind":"意見","question":"それを「民間事業者に委託」となると、それこそ民間事業者の中に株式会社も入るのか入らないのかの議論は別にして、含みが残ってしまうんですよね。社会福祉法人に限定すべきだと思っているんですけれども、じゃあ、もっと悪くなってしまうというのが私の意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"中島委員","kind":"質問","question":"ですから、その前のところで論議するのは、この委員会ではなじまないのではないかなと思います。〔「原案賛成」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須藤委員","kind":"提案","question":"最終的に（２）については、こういうふうにしてもらったらいいですかというところでコンセンサスを得たものは、そこをとっていかないと。いかがでしょうかというご提案をしないと、こんなに時間がかからなかったねという思いが出てきてしまうので、そのあたりをお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"この案に対して賛成ですか、反対ですかと言われれば、反対をとるのかというところをはっきりさせていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"須藤委員","kind":"提案","question":"２番のところで、「大きな視野で」という言葉も議会の言葉としてどうかなというので、「大局的な」とかという表現をご提案させていただきましたよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"伊藤委員","kind":"意見","question":"これだけ意見が出ておりますので、大変だとは思うんですが、一たん休憩をしていただいて、文言を整理したほうがいいと思います。そういうものを整理していただいた上で、再度委員会を開いたほうが私はいいと思いますので、これは意見として述べさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"須藤委員","kind":"提案","question":"それぞれ２、３、４のほうは、ある程度コンセンサスが得られつつあると思うんですよね。ですから、あとは全部１つずつ採決をとらないといけないよという提案では私はないと思っているので、ここまでしっかりやってきているんですからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"４番の６校構想のところをとっていただいたことは評価をしますけれども、広い意味でこの間、私はさっきこういうふうに言ったんじゃないんですね。１の（２）のところ、申しわけないんですが、このままではとても私たちは賛成をできないということを表明したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"須藤委員","kind":"質問","question":"先ほどお話がありました１の（２）のところについては、ですから、ここのところで結構じゃないですかというようなお話をさせていただきました。ですから、我々は十分なところというところまでですけれども、この案で賛成をしていきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"それを求めるときに、意見が違うものを、言葉は悪いですけれども、ごり押しをする形では、私はふさわしくないと。委員長に一言伺いたいのは、先ほどの提言をまとめる、そこを今回、活動現況報告ではなくて提言に至ったと、それはなぜなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"中塚委員","kind":"意見","question":"みんなの意見を集約するという委員長のお考え、そのとおりだと思うんですよね。だから、一致できないところは提言として上げるのは正しい形ではないのではないのかなと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"中塚委員","kind":"提案","question":"いわゆる議会が提案するんだけれども、議会がどうチェックするのか、その担保が具体的にここに記されていないと思うんですよね。具体的に３の部分になるんですか、この仕組みとは何なのかというところが何もないんですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ議会としてのチェックの担保を書き込んでほしいし、ぜひ４点目で加えていただきたいのが、民間委託で生ずる問題点の検証を行う。ぜひ議会のありようというのもしっかり入れてほしいと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"須藤委員","kind":"質問","question":"あえてここで議会がどうのという大上段に構えてしまうとそれも非常に難しくなってくるので、我々の考え方をどうやって生かせるかというふうにつくっていかれたらと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"中塚委員","kind":"意見","question":"議会がどうのというお話がありましたけれども、議会として行政にいわば注文をつけるわけですよね。委員会の提言とは何なのかと、行政がつくったルールをそのままどうぞという、そういうわけには私はいかないなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"中島委員","kind":"質問","question":"ですから、それとチェックのところというのは、予算でも、決算でも、また意見を申すところはいっぱいあるわけです。ですから、そういった意味では、やはり区民の意見がしっかり反映されるようにという、今、須藤委員のお話、私はいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"意見","question":"特にこの特別委員会で１年間論議してきたという意味では、デメリット、この検証こそが大事であったと思うんですね。この委員長、副委員長がご苦労いただいてつくられた案ですけれども、この案に対しては賛成いたしかねるということを申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"西本副委員長","kind":"質問","question":"皆様の活発なご意見をいろいろお聞きしまして、ますますこの特別委員会が発展していくのではないかなという、そういう感じを受けました。本当にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/471723?Template=document&Id=5816#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":49025,"voices":132}},{"id":"h19-20070305-3","meetingId":"h19-c-budget","date":"2007年3月5日","dateIso":"2007-03-05","committee":"予算特別委員会","time":"午前１０時０４分～午後５時５９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちにとりやめていただきます。第６項、従前どおり５階の理事者控室に当委員会の模様を放送いたしますので、そちらでお聞きいただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"大沢委員","kind":"確認","question":"確認といたしまして、この増額分は中学生の拡大された部分の増額と考えてまずいいわけでしょうか。確認をさせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"じゃあ、すみません。約１,４００万円の追加になるわけですけれども、この追加分、どういうふうにこの金額が算出をされたのか説明を求めました。","respondent":"諸岡児童課長","answer":"推移を見極めておりますと、経費面での不足が出てくるということで、概ね１１月まで１人当たり１２.７回程度受診をされているという数字があります。そういったことで算定をいたしまして、約１,４００万円強の補正ということで、このたびお願いしているわけです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"１２.７回ということが基準になっているということなんですけれども、１２.７回、この数字に関しては、他の区と比べて多いほうなんでしょうか、少ないほうなんか尋ねました。","respondent":"諸岡児童課長","answer":"１人当たりの受診回数におきまして、他区との比較というのはちょっとしてございませんけれども、概ね同程度というふうに考えてあります。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"自己負担額が３割、これが区からということで無料になるということですけども、先ほどちょっとお伺いしました入院時の食事の標準の負担金というのは、幾らなんか尋ねました。","respondent":"諸岡児童課長","answer":"入院時の自己負担額ですけれども、保険適用のほうで算定をやっていまして、今ちょっと金額は具体的に把握してございませんが、それについて自己負担額がなくなるように助成をしているというものです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"標準ということで今お伺いをさせていただいたわけですが、おわかりになりましたら、また後ほどでもいいので教えてほしいと求めました。これは減額１,３００万円と３,１００万円ということになっておりますけれども、効果の是非について、ちょっとご意見を伺いたいと思います。","respondent":"谷田部健康課長","answer":"平成１８年度新規事業で取り組んだ事業でございまして、平成１８年度当初におきまして、１０組に１組の方が不妊に悩んでいらっしゃると。","id":"exchange-006"},{"speaker":"大沢委員","kind":"意見","question":"２５０名あるだろうという予想で、味の決め手、最後の味つけが何か足りないような気がしてなりません。もっともっと隠れた数の方がいらっしゃるんじゃないか、そのように考えますけど、もう一回ご意見を説明を求めました。","respondent":"谷田部健康課長","answer":"まず区内に不妊治療に取り組める医療機関、やはり、医療機関の中にこういう制度があるということを私どもも今後ＰＲしていきたいと思ってあります。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"すみません、あと３分ちょっとになりましたので、次の質問に移らせていただきます。何も補正をプラス・マイナスしなくてもいいのではなかろうかと思いますけれども、そこのあたりのやりくりを説明を求めました。","respondent":"原国保年金課長","answer":"平成１７年度は同じようにやった場合に、月に４１件ということで減ってあります。今年は、月４７人ということで、そういった背景の中で２４人の分を追加させていただいたということでご理解いただきたいと思います。","id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"２４名分の追加ということで、プラス・マイナスすることがいいのかどうか、ちょっとご見解をくださいとの意見を述べました。","respondent":"日下部企画財政課長","answer":"当初予算以降のいろんな事情の変更もありますので、できるだけ最小限にこしたことはないんですが、必要なものについては増減計上すると、その辺はご理解いただきたいと思います。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"私は５９ページの公共施設整備基金積立金の追加分と、これに関連して基金についてもちょっとお伺いしたいと思います。どういうふうなものが積み立てになってきているのかというところをまずお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"今回の９２億円の、これに基づいて最終補正をさせていただいているわけでありますけれども、先ほどご説明をさせていただきました。不用額、契約落差等も含めて、このような形で年度末の最終段階で財源的に余裕が見込まれると。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"しかし、今回の補正予算のところ、総額では５６億９,０００万円の増額なんですよね。その全体の増額が５６億円なんですけれども、積み立てが９２億円ということで、そこら辺のところの全体像をちょっと教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"それから老朽更新、大変に財政負担の増大が見込まれるということも含めまして、基金の積み立てをできる限り増やしてきているという状況です。最終段階で、これは非常に単純なちょっと説明で申しわけないんですが、そういう形で予定をしてまいりますけれども。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それとあと、基金については、いろいろ出入りもあるんですが、大体このぐらいは置いておくんだとか、そういう目標額はあるんでしょうか。毎年これだけは積み立てるんだと、そういう目標額というのはあるのかどうか、教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"それから、目標額でありますけれども、これは具体的に今目標をどのぐらい持つべきなのかということで、難しい面はあります。当面する施設需要に対応していくためには、なかなかこれに対応し切れないんではないか、このように考えてあります。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"意見","question":"今の２０年間かけて、毎年四、先行的に区が進めていくというのは非常に財政的な使い方としてちょっと腑に落ちないところというのがあるんですよね。","respondent":"日下部企画財政課長","answer":"起債は当然借金で返すものですから、そういった意味では、財源２５億円で１校を建て替える、そのうち１割ぐらいしか補助金というのは見込めません。にも、基金を有効に活用するということが必要ではないかと、このように考えているところです。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"今回の９２億円のところでいくと、おおよそどういう財源が何パーセントぐらいなのかというのが何かわかったら教えていただければと思うんですが。大体毎年６０億円から１００億円ぐらい超える基金の積み立て、それが大体何割ぐらいになっているのかというのをお聞かせほしいと求めました。","respondent":"日下部企画財政課長","answer":"先ほど申し上げました９２億円に関しましては、基本的には一般財源が大半です。その分一般財源の負担が減りますので、そういったいわば残余の余裕の出た一般財源を基金に積み立てると、それが基本的な考え方です。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"提案","question":"まさに一般財源ですから、やっぱりこれは暮らしのほうに向けてもいい、おかしくないお金だと私は思います。そういう提案をさせていただいたんですけれども、ちょっと改めて伺いたいんですが、そこのところをちょっとお聞かせほしいと求めました。","respondent":"日下部企画財政課長","answer":"最後はやはり政策判断以外の何物でもないと考えております。一定の余裕が出たものについて積み立てをして、逆に全体のサービス水準を落とさないためにもそういうしっかりした基盤の土台づくりをやっているです。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やっぱり、福祉のほうにもこうした基金が活用されるべきだということを私は思います。そういう立場で、今後の活用のところもいろいろ検討していただければということで、今日は要望させていただいて、終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"私は７ページの歳入、それから６９ページの不妊治療相談・助成事業更正減額、８３ページの大間窪小学校用地取得減をお聞きしたいと思います。この辺の理由というか、傾向というか、この辺をまず教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"そういった点では、今現在の見込ではまだ確定はしておりませんけれども、２６億円ぐらいは見込めるだろうということがまず１点であります。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"今までは都のほうからは支出されていなかったということで、それが支出されるようになったと、こういうことでよろしいか尋ねました。","respondent":"日下部企画財政課長","answer":"ただ、残りの４分の３につきましては、翌年度から４カ年で分割をされまして、これも財調算定の対象になるということであります。都市計画交付金の対象になるわけですから、その分２３区側にとっては財調全体の算定の一つのパイが広がるというような効果を見込めるというものです。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"続きまして、４７ページの安全・安心な学校づくり交付金、これについてお伺いします。これも先ほどの説明で過去の清算分２００億円のうちの品川の分がこれだという説明があったので、その辺のところをもう少し詳しく説明を求めました。","respondent":"市川庶務課長、日下部企画財政課長","answer":"老朽化の建て替えのみならず、大規模改修まで含めた助成制度ということで、本年度安全・安心な学校づくり交付金というものができました。それから耐震補強の工事、こういったものが事業の対象として見られるようになった… これについて平成１２年度の改革時にさかのぼって過去の分については清算をするということでその分、大体年間１２２億円でいろいろ計算します。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今後耐震補強、また耐震改修、また学校改築、それぞれ違うとは思うんですけども、国と東京都と、また区がそれぞれ予算を出し合う配分比率というのは今後どういうふうになっていくのか、教えていただけますか。","respondent":"日下部企画財政課長","answer":"残りについては起債が大体２割ぐらいですね。残りは一般財源で手当てをするというのが基本的な財源構成です。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、今回補正で幼稚園、小学校、中学校それぞれありますけれども、あとどれぐらいでこの小中学校、幼稚園、例えば保育園とか、この辺のいわゆる教育施設とか、区有施設はどれぐらいの予定で終わるという予定になっているんでしょうか、教えていただければ。","respondent":"市川庶務課長、小林保育課長","answer":"これの設計を来年度、平成１９年度に行います。実質所要経費については、その実施設計を待って確定される、こういった今後の見通しです。 最終的にはこの実施をもちまして、建て替え等別途予定しているものを除きましては完了ということになります。実施を予定しておりまして、合計２０園で、平成２０年度までにすべての耐震を完了する予定です。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"小中学校、幼稚園、保育園、それぞれ平成２０年度ぐらいを目途にすべて耐震が終わるということで受けとめします。２５０組ということで予算組みがされていたわけですけど、実際まだ３月途中でありますけども、実績を教えてほしいと求めました。","respondent":"谷田部健康課長","answer":"２月末での申請の受け付けですけれども、１６件の申請がございまして、助成額は約５０万円という状況です。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問・要望","question":"２５０件の予算組み、実際にはやっぱり１６件ということで、そのほかに何かもし理由があれば教えてほしいと求めました。","respondent":"谷田部健康課長","answer":"件数につきましては、それの潜在的な一般治療に結ぶ方が３倍から４倍ぐらいあるんではないかというふうに私ども見込んで２５０組程度、それと。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"今回もたしか平成１９年度、ＰＲ法等も検討いただいて、かなり大勢の方がこういったことでやられるように期待をしておきたいと思います。今回約１３億円ぐらいですか、そうすると、大体１０億円で購入できたということで考えておけばよろしいんか尋ねました。","respondent":"市川庶務課長","answer":"したがいまして、今年度当初におきまして、先ほど申し上げたような計算で出しました２３億円という額で計上いたしました。結果、２分の１の減額ということで、９億３,８００万円という購入価格で、その差額について今回補正をお願いする次第です。","id":"exchange-024"},{"speaker":"大西委員","kind":"質問・要望","question":"４４ページのプールの温水費ということで、現在何校ぐらいのところで温水という状態でやられているかというのをまず教えていただきたい。６０ページの選挙費のほうで、職員手当費ということですけども、もう少し具体的に中身のほうをちょっと教えてほしいと求めました。","respondent":"富田生涯学習課長、野田口選挙管理委員会事務局長","answer":"学校温水プールにつきましては、現在は日野学園温水プールと戸越台中学校温水プール、２校です。それと、一般開放につきましては、本年５月から伊藤学園温水プールをオープンする予定でおります。 給料の差です。更正した理由ですけれども、４月１日正規職員に変わったために必要な額を更正したものです。","id":"exchange-025"},{"speaker":"大西委員","kind":"質問・要望","question":"これは区のほうとしては、今後全部区立の小学校において、これをどんどんなしていくつもりであるのかどうかということを少しお尋ねしたい。国に何らかの形で求めていかないと、品川区としてはどういう方向で持っていけばよいというふうに考えているか、ちょっと説明を求めました。","respondent":"日下部企画財政課長、野田口選挙管理委員会事務局長","answer":"区のほうといたしましては、今後につきましては、改築ですべて温水プールということは考えてございません。そういったことも含めまして、地域バランスに配慮した上でこれは考えていくべき、そういう性格のものだ… それで、国に対する働きかけですけれども、区長選挙とか区議選挙については、区の負担でということになってあります。","id":"exchange-026"},{"speaker":"大西委員","kind":"質問・要望","question":"選挙をこのわずかな期間で２回もやらなきゃいけないというのは、法改正を求めていくのかどうなのかということを少し教えていただきたい。１０６ページの解体というのがございましたが、これは具体的にどの部分の校舎の解体だったのか、ちょっと説明を求めました。","respondent":"日下部企画財政課長、野田口選挙管理委員会事務局長、市川庶務課長","answer":"かなりそういう意味では整備が進んでまいりましたし、区民の皆様方のニーズにも十分対応してきたと、このように考えてあります。要するに… 例えば２月１日から５月３１日の間に任期満了が来る選挙については、４月に統一してやる、こういうふうな定めになってあります。任期を統一しようとすると… そのほかはすべて解体工事の対象となりました。方角で申し上げますと、旧校舎の立会道路側の一部分です。","id":"exchange-027"},{"speaker":"大西委員","kind":"質問","question":"同一にできるという、その余地があるようにも少し感じたんですけど、その辺はどうか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"ただ、その特例法として、４年に１回の統一地方選挙については、２月から５月までの満了については、統一するよと、これも法律で定まっております。法律で定めているものです。","id":"exchange-028"},{"speaker":"大西委員","kind":"質問・要望","question":"法の変更というんですかね、そのような形を要望していって、今のものが現実的になり得るという解釈でいいのかということが１点。それとあと、９６ページ、品川区ではグループホーム自体をどれぐらい整備していかなければならないというふうにお考えなんか尋ねました。","respondent":"野田口選挙管理委員会事務局長、蓼沼高齢福祉課長","answer":"任期が４年なのが３年になるとか、あるいは５年にするとかしなければ、なかなか法改正ができないわけですね。そういったことで、本当に歩調が合わせられるかどうかというのは、なかなか難しいものがあろうというふうに理解しております。今のところ、あわせてグループホームも整備していこうというふうに考えて、状況を見ながら今後計画的に進めていきたいというふうに考えてあります。","id":"exchange-029"},{"speaker":"大西委員","kind":"質問","question":"入所したいというニーズをとらえてのグループホームをどれぐらいつくっていかなきゃいけないのかという認識をされているのかどうか、ちょっと薄かったように感じるんですが、そのところをもう少し詳しく教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"グループホームについてですけれども、今要介護認定されている方が約１万人前後いらっしゃいます。今現在、まだ整備を進め始めたような段階ですので、今後さらにニーズを見極めながら整備を進めていきたいというふうに考えております。","id":"exchange-030"},{"speaker":"大西委員","kind":"質問・要望","question":"要するに品川区内６カ所しかないわけですから。耐震をやっていく中で、そのスペースの確保ということと、この耐震ということを一緒の形で考えていく余地はあるのかどうかをちょっと説明を求めました。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"認知症高齢者に対しましては、在宅を支援するということを含めて、ケアマネジャーがケアプランの中で必要なサービスを提供する。例えば小山のグループホームが今月オープンの予定ですけれども… 保育園は児童センターと併設しているため、一緒に耐震改修、大規模改修をやることもあります。こうした場合には、児童センターの関係等も含めまして、全体の施設計画として考えてまいりたいと思います。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"５９ページの生活安全推進事業更正減額の防犯拠点整備事業についてお伺いしますが、まず、ここで３６５万２,０００円の減額をしておりますが、その内容と減額した理由をお尋ねします。","respondent":"金子生活安全担当課長","answer":"内容と理由ですが、荏原町駅前の跡地に建設予定の荏原町安心安全ステーションのことです。年度内の着工が難しいと、このために補正予算を打ち切りまして、来年度予算に再計上いたしております。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"荏原署でまだ話し合いがついていないということですけれども、何で区民の安全を守るという最重要的な施策なのに時間がかかっているんでしょうか。その辺の協議の内容についてもう少し具体的な答弁をいただけますか。","respondent":"金子生活安全担当課長","answer":"双方言い分を持っての調整ですので、交渉のようなものです。したがいまして、交渉の経過というものにつきましては、相手にも言い分がありますので、先ほどの答えでご理解いただきたいと思います。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"これから質問ができなくなっちゃうかもしれないんですけれども、まず見通しについて、いつごろ解決するんでしょうか。交渉がずっと続いておりますので、何年も何年も先になると大変なことになってしまうんで、具体的な答弁をいただきたいんですけれども。","respondent":"早津区民生活事業部次長","answer":"ちょっと説明が足りない部分がありまして、４月１日からは、当初予定どおり安心安全ステーションは立ち上げます。当初予定しておりました品川区の安心安全ステーション構想は、建物こそ違いますけれども、現交番の跡地を利用して実施するというものです。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"今私が初めに質問した形になるのは、具体的にはいつごろになるんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"相手のあることではありますが、なるべく早目にやりたいと考えていますので、年度が明けましたら、速やかに着工できるようにこれから進めてまいりたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる現場という形でお仕事をしてくださって２年たちますが、また仕事をしていかなくちゃいけないということがあると思うんですけど、その辺はいかがか尋ねました。","respondent":"金子生活安全担当課長","answer":"これにつきましては、私の能力も不足していたと反省しておるんですけれども、もう少々時間をかけないとこの問題は解決できないなという点もあります。","id":"exchange-036"},{"speaker":"山内委員","kind":"質問・要望","question":"産業経済費の７３ページの観光アクションプラン推進事業追加分、この辺についてちょっと質問させていただきたいなと考えています。確認なんですが、観光案内標識設置事業補助金が３３３万５,０００円、これと同じものなのかということをまず最初に確認させていただきたいんですが。","respondent":"金子産業振興課長","answer":"観光アクションプラン推進事業のお尋ねですが、委員ご指摘のとおり、歳入のほうの分とこの分がイコール、つまり、東京都の１０分の１０の補助でこの歩行者用案内標識を設置したものです。","id":"exchange-037"},{"speaker":"山内委員","kind":"質問・要望","question":"先ほど企画財政課長のほうから観光案内標識設置事業補助金で天王洲の水辺に標識をつけるというご説明があったんですが、これはまずどういうものなのかというのをちょっと具体的に教えていただきたいんですけど。","respondent":"金子産業振興課長","answer":"私どもとしましても、天王洲地域で少し距離を延ばせば、旧東海道まで含めた形で可能かということで、これについて検討を進めてまいりました。２カ所についてどちらも、両方を入れられるような格好になりましたので、この事業を受けて実施したというものです。","id":"exchange-038"},{"speaker":"山内委員","kind":"質問・要望","question":"今回私この標識についてちょっといろいろと質問させていただきたいなと思っておったんですが、街角、そういうものが多くなってきた。その人たちが、例えばそういうような街角サインみたいなものというのをお考えになっているのか、ちょっとお聞かせをいただきたいんですけれども。","respondent":"中川原広報広聴課長、金子産業振興課長","answer":"観光客の方にまちの案内を、サインをというお話ですが、品川区の場合、戸籍住民課でつくっている住所案内と、それから都市計画のほうでまちを案内する駅ごとにつくるサインにそういった観点を取り込みまして、ご案内をしています。私どものほうでは、観光、それについてはいろんなところで配布して手にとられるようにというようなことを実施しております。","id":"exchange-039"},{"speaker":"山内委員","kind":"質問・要望","question":"ちょっとお尋ねをさせていただきたいんですが、これはどういう、それで結局事業が行えなかったという考え方でよろしいのか。それと、ほかの地域でやっていくというような計画があったものが頓挫したのかということをちょっとお尋ねしたいんですけれども。","respondent":"金子産業振興課長","answer":"商業地リフレッシュ推進支援事業のお尋ねですけれども、既に空き店舗対策として実施しております家賃補助、これは３年間ありますので。もう一店舗の予定については、計画を実施できなかったということで、主としてこういうような要因から減額したものです。","id":"exchange-040"},{"speaker":"山内委員","kind":"質問・要望","question":"いわゆる「おばちゃんち」なんですが、やはり地元の人からは手軽にお子さんを預けることができるという点で非常に便利だという話を聞いております。ほかにも空き店舗対策ということで、今後何店舗ぐらいの予定というか、そういう計画があるのかというのを最後に説明を求めました。","respondent":"金子産業振興課長","answer":"空き店舗対策事業につきましては、いろんな内容があるうちの一つが保育に関してのものだろうと考えています。さらににぎわいが損なわれないような形でさまざま考えて計画していただいて、私どもとしましては、積極的に支援していく考えです。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"私のほうからは、８２ページの学校施設建設費と７６ページの都市開発費、それから６８ページの保健衛生を伺いたいと思います。４８ページの都支出金の都補助金の教育費補助金があるんですが、これはどこの歳出のほうに回っているのかということを教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"東京都の補助金のうち、教育費補助金、先ほどちょっとご答弁申し上げました小中学校の改築事業の特別交付金でありますけれども、こちらは８２ページのほうの学校改築の経費、こちらの財源として充てているものです。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"８２ページの学校施設、今のところになるんですけれども、まず大井第一地区小中一貫校のこの補正なんですけれども、どういう理由で、このような補正に至ったのかということを詳しく説明を求めました。","respondent":"市川庶務課長","answer":"いわゆる解体・外構工事の着工がおくれた、その理由は、本体工事が予定の時期に間に合わなかったです。本体工事につきましては、平成１７年７月から昨年１２月までの１７カ月で本体工事を予定してございました。","id":"exchange-043"},{"speaker":"井上委員","kind":"意見","question":"解体事業の状況でということですが、解体に対してどうしてそれが本工事に至らなかったのかということをご説明くださいとの意見を述べました。","respondent":"市川庶務課長","answer":"解体工事の実施時に、特に近隣の方からさまざまな苦情、陳情をいただきまして、それの調整に大変時間を要しました。本体工事の着工時にその辺の、近隣との特に調整を改めてせざるを得なかった、こういう事情です。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"この保護者の方たちの説明にも工事と調査がおくれているというような説明で、実際にはどういうことなのかということがわからないということも聞いているんですが、実際には余波というのはどういうことなのか尋ねました。","respondent":"宍戸施設担当課長","answer":"二十数年前の木造の基礎が残っていて、本体工事の土工事の段階でその分、２週間ぐらい想定外の期間を要してしまった。それらの１カ月ぐらいの着工早々のおくれの部分がその後取り戻せなかった、そのような事情で本体工事の完成がおくれたというものです。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"この工事の場合には、解体業者と建築業者などは一体だったのか、それとも別の業者がされていたんか尋ねました。","respondent":"宍戸施設担当課長","answer":"今回の場合、着工の時期がどうしても８月になってしまうということがございまして、やむなく解体工事は別の発注にしたというものです。したがって、別の業者です。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"今の契約時期の問題で、そういうふうになったということなんですが、そうでなければ、本来は一貫した事業者のほうがいいと考えていらっしゃるのか。本来であれば１２月、１月末に引っ越しをせざるを得なかったというところで、今後はどうか尋ねました。","respondent":"市川庶務課長","answer":"結果として大変学校教育の現場に影響が出てしまった、こういうことを本体工事の着工時点で改めていろいろ検討させていただきました。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問・要望","question":"やっぱりその辺のところはコストも大事だと思いますけれども、見直すべきところがあれば、積極的に見直して進めていただきたいというふうに思います。一般財源であるのかどうなのかということと、あとどういうふうな形でそれが見込まれるということを考えていらっしゃったのかお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"大間窪小学校につきましては、先ほど庶務課長のほうからご説明させていただいたとおりですけれども、財源としましては、これは基本的には学校の国有地の買収につきましては、起債が適用されますので、かなりの部分について起債の活用を図ってあります。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"かなりの部分というのは、具体的にはどのぐらいというふうに理解したらよろしいんか尋ねました。","respondent":"日下部企画財政課長","answer":"失礼いたしました。実際には９割、取得価格の９割です。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"それで、結果的には９億円ぐらいで取得ができたということは、予算立てとして結果的に先がわからないという状況はあるにしても、この後、更正減額の１３億円というのは、公共施設の基金に入っているのか、どこに繰り入れられているのかということをちょっとお伺いしたいんですが、そこら辺は。","respondent":"日下部企画財政課長","answer":"今回の補正の要因としましては、先ほど申し上げましたような一般財源から、特定財源から、それから不用額から、いろんな要因があります。","id":"exchange-050"},{"speaker":"井上委員","kind":"質問","question":"すみません、ちょっと質問が違ったかな。１３億円というのは、使わなかったわけですから、どこかに収入として組み込まれていると思うんですけど、どこに入るんか尋ねました。","respondent":"日下部企画財政課長","answer":"先ほど全体の９割が起債でということでありましたけれども、当初の段階でも、要するに９割ほど見込んでおりました。それが約１３億円近く、起債のほうも減ってきたということで、それが財源更正という形で振り替わっているものです。","id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"ちょっと先ほどの基金のところで疑問があったので伺わせていただきました。それぞれ理由を、小関橋はいいですから、大崎駅東口歩行者デッキから３項目の更正減額について説明を求めました。","respondent":"青木都市開発課長","answer":"１点目、小関橋新設整備工事委託につきましては、冒頭企画財政課長からお話がありましたとおり、工期の変更によるものです。これは駐輪場とあわせまして、出来高を年度ごとにチェックしている中で予定どおりの出来高が上がっていないということで減額更正したものです。","id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"これがというような、そういうものではなく、本来こういう監視機能が議会に相当問われているわけですよね。そういう意味では、都市開発の部分だけではないですけれども、そういった資料提供などはどんなふうにお考えなのかお伺いします。","respondent":"日下部企画財政課長","answer":"冒頭で、私のほうから全体の概括的なご説明をするということで審議をお願いしているところでありますので、その辺はご理解いただきたいと思います。必要な資料については出していますし、そういうことを含めてトータルで努力はしておりますので、ご理解をお願いしたいと思います。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"さらに工夫をしていただいて、議会の審議がもうちょっと多岐にわたってできるような形で検討いただきたいということは、今期最後の要望です。ちょっと伺いたいんですが、不妊治療が年間上限３万円ということで昨年のプレスにも出ていますけれども、その辺をお伺いします。","respondent":"谷田部健康課長、倉橋品川区保健所保健サービス課長","answer":"２点目のほうのご質問にお答えいたします。今回平成１８年度取り組みまして、助成の内容を精査していきますと、治療検査だけで２０万円近く自己負担で払っていらっしゃる方もいらっしゃいます。 相談の人数ですが、１６名ということで、６回程度の回数で１６名、予約がそれ以上何例かございましたけれども、実質１６名ということで実施しております。","id":"exchange-054"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"ですから、今後の中でも、それは十分気をつけていただきたいのと、更正減額の中の解体なんですが、今既に始まっています。第２期という感じではないんですけれども、非常にタイトな中での解体工事をし、その辺のところのご説明をほしいと求めました。","respondent":"宍戸施設担当課長、市川庶務課長","answer":"今委員ご指摘のとおり、工事工程の変更については、住民説明会等行っておりません。そういう意味では、周辺住民の方々へのご説明は不足していたと反省しております。 特に４月の伊藤学園の開設当初と時期的に合致するということがありますので、特に新入生の対策を含めまして、十分学校側と対応策を講じながら工事を進めてまいりたいといふうに考えてあります。","id":"exchange-055"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"この工事そのものが今見ていますと、相当やっぱりある程度大がかりな形で解体が進められていますよね。前のところと違ったところと契約されているんだろうと思うんですが、その辺の状況だけもう一度教えてほしいと求めました。","respondent":"市川庶務課長","answer":"現在行っております工事は、本体工事と同一業者が対応しています。特に今回の４月のぎりぎりの工期の設定というのがどういう意味を持っているか、近隣への負担も軽減する方向で調整に努めてまいります。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"確認","question":"ちょっと確認の意味で、工事費は毎年これからも確保されるのかどうか、あと幼稚園も含めて耐震診断は平成１８年度ですべて済んでいるのかどうか。この点の確認と、大幅増となったというところでは、この大幅増になった背景がどういう事情があるのかも説明を求めました。","respondent":"市川庶務課長、宍戸施設担当課長","answer":"新年度の予算に関係する分が出てまいりますが、小学校で６校、中学校で２校予定しています。そのほか、今年度、平成１８年度に実施をいたしました耐震診断の学校につきまして、工事の実施設計を来年度行います。 耐震診断、児童施設ですが、平成１８年度ですべて耐震診断を終わっておりまして、平成１９年度、２０年度で工事はすべて終わる予定です。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成７年の時期のときの耐震診断、あと基準がどうだったかというあたりと、第２期のところの違いというのがどこにあるのかというのをちょっと鮮明にお答えほしいと求めました。","respondent":"市川庶務課長","answer":"後になって、品川区はこの０.７に合致していないということで、耐震化未対応ということで調査の結果が出た経緯があります。次に、第２期、平成１５年度から耐震診断を実施した部分につきましては。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どこがどう違うのか、Ｉｓ値が０.７の段階で法律的に合致しているというところが国の見直しのところでＩｓ値が０.７を求めて、それで。私は具体的にこれがどう行われたのかなというのをちょっと今日お伺いしたいなと思っていたので、耐震診断の１校の額とか、いかがか尋ねました。","respondent":"市川庶務課長","answer":"第１期のときの耐震診断、これは平成８年度、９年度、２カ年にわたって実施をしています。０.７という数字を求めている一つの根拠といたしましては、子どもたちが教育を受ける場であるということと、こういうふうに理解をしています。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺でこの品川区の平成８年度、先に向けての計画性というのがかなり求められるのではないかなと思うんですが、この辺はいかがでしょうか。私がちょっと聞いたところによると、早く改善をしてほしいという催促のようなこともあったということなんですけれども、その辺はどうなんか尋ねました。","respondent":"市川庶務課長","answer":"９年度に実施した診断の結果、そのときに採用した基準値が０.６という、法律に基づいた基準を設定して対応したものです。当時実施いたしました耐震補強工事については、平成１５年度から私どもが第２期として対応しているところの事情としては、大きく違っている。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどの答弁だと、ほとんど変わらないといった見方でよろしいんでしょうか。４９ページの改築事業特例交付金のところに移るんですが、冒頭に伺った、基準のところをお聞かせほしいと求めました。","respondent":"市川庶務課長","answer":"一切その点では問題はないという認識を持ってあります。２点目の耐震補強に当たって、原則補強工事で対応する、こういう考え方を持ってあります。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よろしくお願いしたいんですが、耐震補強のところもそうなんですけれども、ぜひその辺を先のほうまでの計画を明らかにしていただきたいなと思います。よそから来たり、その辺はいかがでしょうか、ぜひ同じにしていただきたいんですが。","respondent":"市川庶務課長、小林保育課長","answer":"今後の学校の改築、それから改修、これにつきましては、現在進めております耐震補強、これに喫緊の課題として取り組んですので、その次の段階で検討すべきもの、そういう認識です。 ただ、この認証保育所の制度の基本が、東京都で制度設計されたものですので、２３区ほぼ同様の対応、基本は同様になっております。その他の点につきましては、各区の状況による判断と考えております。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区内の認証に入れなくて、お隣の区に出っ張ってしまった方がいらっしゃるので、そういう方にも助成を受けられるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"私のほうからの質問としては、先に質問をさせていただいて、もしくは二つ入れて通していくのかどうか。それをどういうふうに、それまでの間の約３年前後はどういう処理をされているのか、あわせてお答えほしいと求めました。","respondent":"宍戸施設担当課長、原田下水道河川課長","answer":"横浜方式です。区有の施設の場合は、適切に民間に委託化しながら効率よく進めているということで、ちょっと横浜方式とは違うやり方でやっているかと思います。平成２１年度完成予定ですけど、これは完全に区のスケジュールで区が検討した結果、平成２１年度末完成予定ということにしております。","id":"exchange-064"},{"speaker":"若林委員","kind":"質問","question":"平成１７年９月に起きた都内の集中豪雨、杉並区方面だったと思いますけども、これに関連をして要請があったです。平成１７年９月の事例がどういうものか、また、なぜこれが目黒川においても適用されてしまうのかというところをお聞きしたいと思います。","respondent":"青木都市開発課長","answer":"１１月から５月の間、渇水期にのみ川の中で施工ができるというような形に協議が整いましたので、それに伴って施工の内容を変更したものです。平成２０年、当初予定しておりました工期までには、今回の債務負担行為という形でのご報告をしたものです。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"杉並区、中野区の事例に沿って、どうしても強い指導があったというふうに理解をしてよろしいわけですね。その強い要望に対しては品川区として、これは１カ年延びるわけですので、そこら辺のお話し合いの様子というのをお聞きしたいと思います。","respondent":"青木都市開発課長","answer":"そういった工事をやることにやって、今までの目黒川の改修に対する取り組みが何ら悪く評価されているということではございません。私どもも強く当初の計画どおりにやりたいという協議は進めてまいりましたけれども、そういったことを勘案しますと。","id":"exchange-066"},{"speaker":"若林委員","kind":"質問・要望","question":"債務負担行為によって１カ年延びるです。今後の目黒川の再生について、どのような影響があるか、想像できるものがありましたらお教えいただきたい。","respondent":"青木都市開発課長","answer":"私ども今進めております目黒川周辺での整備、環境整備等については、何ら今後も支障があることはないと考えています。これは一貫して現在協議中の内容です。","id":"exchange-067"},{"speaker":"若林委員","kind":"質問","question":"大変に大きな、自治体が財政破綻をするということは、どういうふうに受けとめればよろしいんでしょうか。そのような見地から、自治体が破綻をするというのはどういう意味なのか、ちょっと教えていただけますか。","respondent":"日下部企画財政課長","answer":"通常では、ちょっと考えられない事例であります。それのかわりに借金で穴埋めをする、その悪循環というのが財政破綻につながったと、このように理解をしております。","id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"最終的には今ご説明があったようないわゆる予算の中であらわれてこない一時借入金というんでしょうか、そういうもの。ここら辺、これは品川区がどうこうという意味じゃなくて、これからの国の新しい政府から健全化法案も出されるというふうにお聞きをしております。","respondent":"日下部企画財政課長","answer":"ただ、ここで先行きを考えてみますと、必ずしも状況は楽観できない。トータルでいけば２０億円ぐらいの減収という問題も出てきますし、今後少子高齢化に伴う財政需要の問題とか、このように考えております。","id":"exchange-069"},{"speaker":"木下委員","kind":"質問・要望","question":"そういう点でちょっと質問させていただきたいんですが、計画的な人員構成の部分でどうだったのかな、仲間についてはどうなのかな。いろいろな採用状況だとか、それから今現状としてどういう動きでやってこられたのか等々、この部分についてお聞かせ願えますか尋ねました。","respondent":"榎本人事課長","answer":"冒頭に企画財政課長のほうから説明がありましたように、平成１７年１０月１日の現員現給をもとに見積もりを立てているところです。","id":"exchange-070"},{"speaker":"木下委員","kind":"質問","question":"そういう意味では、減の中身ですかと、原因ですとかをお教えいただければと考えています。将来的にはどういう形で推移していくと見ていらっしゃるのか、そこら辺を、ちょっとお聞かせ願えますか尋ねました。","respondent":"志村生活福祉課長","answer":"平成１８年度当初予算の策定に当たりまして、これからの増加が見込まれておりましたので、平成１７年度予算から扶助費を３％ほど伸ばしたものです。ですので、こうした傾向が当分の間続くのではないかと、かように考えている次第です。","id":"exchange-071"},{"speaker":"木下委員","kind":"質問・要望","question":"そこら辺の原因というか、その中身、どのように考えていらっしゃるのか教えていただきたい。先ほど、効果が上がったんじゃないかというお話をお伺いしましたけれども、もうちょっと詳しく説明していただければありがたいと思います。","respondent":"志村生活福祉課長、青山品川区保健所長","answer":"１件１件個々に当たってはございませんけれども、この後は居宅で受け入れということで、ケースワーカー等で対応しているものです。それから、就労支援ですけれども、そうした専門員の方をお招きして、実は、平成１７年度… 精神障害者の方たちの社会的な自立支援という意味をも含めてなんですけれども、一方において、病院にとっても難しくなっている現状もあります。","id":"exchange-072"},{"speaker":"木下委員","kind":"質問","question":"今、ちょっとご説明をお伺いして、要するに、経営が成り立たないので、そういう病床を閉鎖しているというようなことなのかなと。何か原因があるということでしょうから、九州のほうでは、悲惨に目にお遭いになったお話とかも聞いております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"伊藤委員","kind":"確認","question":"改めて、なぜ計画を見直ししたのかという背景を、確認してお伺いしたい。お願いいたします。","respondent":"市川庶務課長、日下部企画財政課長","answer":"平成１８年度に、第一日野小学校の校舎改築の基本設計への着手を予定してございましたが、この平成１８年度に予定してございました。… それから実施設計ということで手順を踏んでまいりましたけれども、今、当初計画の変更を余儀なくされたという経緯があります。よりきめ細かに議会にも報告… 平成１９年度に第一日野小学校の校舎改築、教育総合会館の改修、これの基本設計および実施設計を行います。","id":"exchange-074"},{"speaker":"伊藤委員","kind":"確認","question":"これは、大きな問題になると、私は思っています。こういう方々が品川区の仕事を一部負担しているわけですから、ざっくりとした部分で確認したいのが、お願いします。","respondent":"日下部企画財政課長","answer":"従前もそういう取り組みを進めてきたわけですが、さらに委託水準をより高めていくということも含めまして、さまざまな検討を進めている。","id":"exchange-075"},{"speaker":"伊藤委員","kind":"質問・要望","question":"個々に相談をしながら調整は進めていると言うけれども、現に、そうではないという声も届いていることも事実です。品川区の仕事の一端を担ってくださっているわけですから、責任は公務員と同時にどんどん重くなっていく可能性があるわけですから、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"明日以降の平成１９年度予算の中でも、またご提案をする予定でございましたが、いろいろ地域の環境整備ということでご協力をいただいております。金額アップということでご提案をするということも予定しておりますし、区としても、ご理解いただければと思っています。","id":"exchange-076"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、これからは、ほかの考え方かもしれませんけれども、要望ですけれども、２００７年問題、団塊の世代の方々が入ってくる。ですから、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からは、８７ページの生涯学習施設費の図書館経費更正減額、職員給与費のところで、お尋ねしたいと思います。２,９９６万円余の減ということなんですけれども、まず、この中身を教えていただきたい。","respondent":"工藤品川図書館長","answer":"こちらのほうは、私ども、平成１７年度から平成１８年度にかけて定数減がございました。内容としましては、正規職員のマイナス２名、そして、再任用職員のマイナス２名、嘱託員のマイナス１名のトータルのいわゆる人件費分の減です。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"そういった定数減になった部分というのは、いわゆるその業務は、かわりに違うところに依頼になると思うんですけれども、それは区長の所信表明演説にもございましたけれども、図書館窓口の民間委託ということでよろしいんか尋ねました。","respondent":"工藤品川図書館長","answer":"平成１６、１７年度という形で、業務委託による、いわゆる人員減というのをやっております。安藤委員ご指摘のような、いわゆる委託による減ではない、内部による見直しの減です。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"非常勤職員と、いわゆる窓口委託している委託会社の社員の方の、それぞれの職員数を改めてお伺いしたい。その１日の業務内での職員の配置の数といいますか、平均的に一日の業務を回しているかというか、その構成をお伺いできますか尋ねました。","respondent":"工藤品川図書館長","answer":"図書館によって、いわゆる１階と２階を有しているカウンター等があります。１０館あるわけですから、正規職員が７１名ということですから、１館当たりそれに応じた数を配置しているです。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"平成１７年度に全館に広げたということで、窓口業務をどうして民間委託させるのかという、その基本的な考え方をお伺いしたい。そういった点では、委託が進んでいるわけですけれども、サービスの水準というのは維持されているという認識なんか尋ねました。","respondent":"工藤品川図書館長","answer":"効率的、効果的な執行体制を目指すということは、従来から区の方針だと考えております。運営コストを削減し、基本的には、削減されたコストで新たなサービスへの対応へ向けていくというものです。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"ふさわしい均等待遇というんですか、そういう高度なサービスを提供している皆さんにも、きちとした待遇というのを保障してあげるべきだと思うんです。そういう方が、やはり区はきちんとした待遇を保障するべきだと思うんですけれども、この点に関しての認識はいかがか尋ねました。","respondent":"榎本人事課長","answer":"これは、本会議でも答弁いたしましたように、民間企業が雇用条件等を決めるのは、契約によって決まっているものですから、区が実際に働いている人の賃金等を云々すべき問題ではないと、考えております。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問","question":"考え方としてお聞きしたいんですが、区のほうとしては１年間一生懸命努力して、大切に皆さんの税金を使ってやってこられたと。９２億円は残ったわけですから、それをどうして一般会計のほうに、その処理について説明を求めました。","respondent":"日下部企画財政課長","answer":"９２億円の対応の仕方ということでありますけれども、私どもは、基本的にこういうふうに考えています。そのほうが、何と言いますか、ちょっと大げさに言えば、財政認識といいますか、そういう観点からも適切ではないかという判断です。","id":"exchange-083"},{"speaker":"須貝委員","kind":"意見","question":"２億円から３億円で２０年以上もつということならば、筋交いを入れたり何かして、こういうふうに大切に学校を残していますよと。行動も必要じゃないかと思うんですが、その辺、ちょっとご見解を説明を求めました。","respondent":"日下部企画財政課長、市川庶務課長","answer":"これは先ほどもご説明させていただいたような形で有効活用を図るということが、逆に、早い段階で方向性がはっきりする。そういうような基金の果たす役割も含めて、ご提案を申し上げているということで、ご理解をいただきたいと思います。 これまで改築の対象としてまいりました学校について見ますと、教育環境としてどうなのかというところを常に比較検討しながらきているわけです。ただし、原則は、先ほど申し上げたとおりです。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと周りの自治体を見たら、どうでしょうかね。その中で、じゃあ、そのお金がどういうふうに流れたとか、そういうことまでは、果たして読み取れるものか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"本多委員","kind":"質問","question":"初めに、５９ページの退職手当追加分。当初予算では１８億円に対して、補正額６億９,０００万円ということで、まず理由ですとか、人数ですとか、状況を説明を求めました。","respondent":"榎本人事課長","answer":"３月で、定年退職以外の方が３０名ということで、合わせて５０名の退職者が出たという形で把握しております。ということで、その追加分６億９,０００万円ということで、補正で組まさせていただいたものです。","id":"exchange-086"},{"speaker":"本多委員","kind":"質問・要望","question":"予定よりも５０人の追加ということなんですけれども、退職される方には、当然さまざまな理由があると思います。当然あいてしまったところを補うという部分で、組織力を挙げて努力されている点について、ちょっと教えてほしいと求めました。","respondent":"榎本人事課長","answer":"退職予定でいきますと、それから主任主事以下で１９名、係員で１５名というような内訳になっています。その対応としては、そういう人事異動での対応の中での適材の中でも、組織力を維持していこうという考え方に基づいております。","id":"exchange-087"},{"speaker":"本多委員","kind":"確認","question":"区議会議員の任期は４月末までですから、新年度を超えないで３月末以前に退職すると受給率が増えるとか、以前ありました。そういう視点から、以前は、５７歳までの勧奨退職がありましたけれども、今、もろもろの手当等、そういうものがないか、確認をさせてください。","respondent":"榎本人事課長","answer":"２３区でそういう制度ができたんですけれども、品川区では平成１３年度、その制度については適用をやめたところです。そういった意味でも、きちんと定年まで勤めていただくという前提のもとに、区の職員の活動を図っていくという考え方です。","id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"そういう前倒しすることによって受給率が上がるというのは、何かちょっと住民本位ではないという、その視点から確認をさせていただきました。これからの人事考課の制度がどう変わるかはわかりませんけれども、定年まで勤めるというか、その辺の考え方について教えてほしいと求めました。","respondent":"榎本人事課長","answer":"同じ数ではありませんけれども、それに見合う、今までのレベルとは違うかなりの新規採用を考えなければならないときにきております。１年から３年の期間だけ正規職員として採っておりますので、職員としてきちんと能力アップをした上で職務についていただくという考えです。","id":"exchange-089"},{"speaker":"本多委員","kind":"質問","question":"勤め上げるといいますか、そういう方針といいますか、よろしくお願いしたいと思います。その中で一番目立ったのが、７３ページのまちづくり事業部の２億６,６２３万９,０００円の減ということで、まずこの内容について説明を求めました。","respondent":"榎本人事課長","answer":"人数的には０なんですけれども、採用人数が増えた関係で、全体としては職員給与費は減っているという形になります。先ほどの退職手当の部分が補っていますので、昔で言う職員給与費の全体でいきますと、７,８００万円ほどの減という形になってあります。","id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"一つだけ、ちょっと聞きますが、６１ページの地域センターの職員費が、ここでも減になっているんですけれども、この辺の理由といいますか、説明を求めました。","respondent":"田村地域活動課長","answer":"もう１点は、武蔵小山のサービスコーナー設置に当たりまして、研修という形で地域センターに配属しておりました。平成１７年１０月１日現在は、サービスコーナー開設に伴って減になったというのが約１,１００万円、合わせて３,３００万円です。","id":"exchange-091"},{"speaker":"本多委員","kind":"確認","question":"見積もりというか、もう少し読めなかったのかなと思って、ちょっと確認で聞かせていただきました。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"山路委員","kind":"質問","question":"４８ページ、もう１点は５６ページ、お伺いをいたします。交付金も平成１８年度の１１月で終了いたしましたので、財政予算面ではどういうふうな展開をしていかれるか、お伺いをいたします。","respondent":"西島障害者福祉課長","answer":"当初は、生活支援センターの事業費が約２,１８０万円余ですが、そのうちの１,０４０万円余が補助金として交付される予定になっております。精神障害者生活支援センターも、その自立支援法の枠組みとは別といたしまして、都として補助をしていくというふうに聞いております。","id":"exchange-093"},{"speaker":"山路委員","kind":"質問・要望","question":"まだ具体的には財政の見通しはついてないのでしょうか。そのまま都の包括補助金が充てられる可能性は高いんか尋ねました。","respondent":"西島障害者福祉課長","answer":"同一の枠組みになりますと、いわゆる精神障害者の生活支援センターは、地域生活支援事業の枠組みに入ってまいります。ほかの２障害とは別の枠の形で、細かいところまでは承知しておりませんが、同様の保障はしていきたいというふうな返事をいただいているところです。","id":"exchange-094"},{"speaker":"山路委員","kind":"質問・要望","question":"款別がちょっと違うところで聞きまして、申しわけございません。ご要望聞いておりますと、さらなるご努力で、充実と拡大をお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１５４ページの介護保険会計についてお聞きしたいと思います。その計画に対して現状がどうなっているかということに対しても、お聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"平成１８、１９、２０年度で約５億３,０００万円ほど取り崩す予定です。平成１９年度については、これからご審議いただく予定ですけれども、１,１００万円ほど取崩しを予定しているという状況です。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３年目で残りの４億七、八千万円になるんでしょうか、それぐらいの額を取り崩すということになるのか。利用できているときと比べて、介護ベッドと車いすなどの福祉用具で減額になったのかということについて、教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"今の平成１８年度の見込みを基本に予算を立てたわけですけれども、平成１９年度の決算、やはり同じように給付の伸びが見込めるでしょうから。平成１８年度末の実績の見込みから申し上げますと、約１億８,０００万円ぐらい、福祉用具に関しては給付が減しているという状況です。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１％ですか、本当にわずかな額だと思うんですね。これだけの９５.５％の方がベッドを使わざるを得ないという状況の中で、どうか、その認識についてお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"ケアマネージャーが一人ずつその制度改正の趣旨をご説明して、おおむね理解をいただきながら、切り替える方は切り替えてきたです。厚生労働省のほうで基準の見直しを進めていると聞いておりますので、その状況を見極めながら、区としても対応していきたいと考えております。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だって、やっぱり９５.５％の方がベッドを使わざるを得ないというこういう現実の中で、やっぱり必要な人がいるんだとは認識されないでしょうか。改めて、ご答弁いただけないか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"必要ありや、なしやの判断は、なかなか難しいものがあると思います。そういう取り扱いになっておりますで、それに従って、区としては、利用者にご理解をいただいてきたと考えております。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱり国に改善策を求めていく、その改善策を国に求めていくという姿勢こそ必要なんじゃないかと思うんですけれども、いかがでしょうか。それから直接、こういう相談も家族や介護の方からたくさんお聞きしたんですけれども、ぜひ品川区でもつくってほしいという要望が出されています。","respondent":"蓼沼高齢福祉課長","answer":"利用者と接する身近な自治体として、というご指摘ですけれども、これにつきましては、２３区の場でもいろいろ論議もしました。","id":"exchange-100"},{"speaker":"松澤委員","kind":"質問・要望","question":"５２ページの不動産売払収入、７,４００万円のところ、補正が１億２,３７２万２,０００円、これの内容をお知らせほしいと求めました。あるいは、いつごろすべて完成するのかについて、お聞かせほしいと求めました。","respondent":"中島経理課長、市川庶務課長、松代管理工事課長","answer":"１点目の不動産売払収入につきまして、ご説明申し上げます。補正額の１億２,３７２万２,０００円ですけれども… １.６倍、m2単価５６万円ということで、借地面積４,０００m2を掛けまして２３億円という予算計上をさせていただきました。… 昨年８月、地元の説明会等を通しまして、地域の方に説明をしましたところ、いろいろと要望が出てました。","id":"exchange-101"},{"speaker":"松澤委員","kind":"質問・要望","question":"１０年工事があるんだったら、残り３年なんですから、ここをお答えほしいと求めました。あそこにお知らせの看板なんかあるんですかね、ちょっと私は目につかなかったものですから、楽しみにしているものですから。","respondent":"中島経理課長、市川庶務課長、松代管理工事課長、日下部企画財政課長","answer":"一部交換、残りを売却という形で、東京都と進めてまいりました。そういった要素が一番大きくて、今回の補正にさせていただいたです。２分の１の減額というのは必要減額ではございませんで、あくまでも制度としては、任意の減額だということを前提に価格交渉に臨んです。したがいまし… ３カ所ほど、工事の目的と将来の完成予想図を図式化したものを張りつけて、ご理解をいただくようにしております。今、所管課長からもるるご説明させていただきました。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"入る前に、今の松澤委員の質問の中にタコ公園のお話があったんですが、これはちょっと要望にもなりますけれども、今、工事が始まっているんですね。そこだけ、ちょっと看板での告知の方法をちょっと改善をしていただきたいと思うんですが。","respondent":"松代管理工事課長","answer":"ここにあります大小のタコですけれども、それを東京都第二建設事務所の２６号線整備の工事にあわせまして移設するということです。まさにこれから移設する予定になっておりますので、少しでもそこを通る方、利用される方にわかりやすくお知らせをしたいと考えております。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"さまざま委員のほうからも質問がありましたけれども、今後、どういうような形でつくっていくのか。国と都との関係も含めて、今後、どういう形で予算をつくっていかれるのかを聞きたいと思います。","respondent":"日下部企画財政課長","answer":"国も都も、歳入をなかなか、あらかじめその時点で見込みきれないものがいろいろあります。１年間をしっかり見通す形で、歳出ともに計上できるような努力は、引き続きしてまいりたいと考えております。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"病院側、薬局からの回収がうまくいっているのか、どうか、その実態をどのぐらい把握されているのかを、お聞きしたいと思います。自分の意思なんでしょうけれども、どれだけきちんと助成されているか、そこら辺の状況把握はどのように考えられているか尋ねました。","respondent":"諸岡児童課長","answer":"レセプトを国保連合会のほうに送られてまいりまして、支払い機関ということで、医療機関のほうに料金を払う。ほとんどの場合、医療証を病院の窓口に提示していただければ、その場で医療費のほうはかからないというような状況になっております。","id":"exchange-105"},{"speaker":"西本委員","kind":"確認","question":"品川区の助成が現場の病院とか、薬局のほうに行っているのかどうかの確認は、区としては把握をしているのか。それは、自己責任下においてやっていただくというような考え方なのかを、お聞きしたいと思います。","respondent":"諸岡児童課長","answer":"２３区、２３区がそれぞれ東京都に契約委任を行いまして、それから支払いが行われているといった関係です。お支払いしますということで、周知はされておりますので、漏れるということはないと認識をしています。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"きちんと流れの中で入っているかどうかというのは、医師会等々を通して、現場サイドで確認をしていただけないかなと思います。その中で、区の財源がどういう形で何％ぐらい入っているのかとか、認証保育所に関する補助金の仕組みを教えてほしいと求めました。","respondent":"小林保育課長","answer":"あらかじめ区が定めました単価の２分の１を区が負担し、残りの２分の１を、都から補助金として歳入しています。開設準備経費につきましても、都と区と２分の１ずつ、最高２,０００万円までの補助というふうになっています。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"区のほうも２分の１、運営費として助成しているということですが、非常に入りにくい状況なんですね。優先順位というのは、いいのかどうかというところがありますが、いかがか尋ねました。","respondent":"小林保育課長","answer":"認証保育所は、都市型の保育需要に対応するということで、特に駅周辺に立地することが多うあります。もちろん、各区の持ち出しになっておりますので、区内居住の区民が区内の施設を利用していただくにこしたことはないというふうには考えております。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"今後、どういうふうになっていって、この減額というのは、今後どういう形になるのか。ますます減額という形になっていくのか、動向を、どういうふうに考えていらっしゃいますか尋ねました。","respondent":"小林保育課長、諸岡児童課長","answer":"平成１７年１０月１日現在の現員、育児休業中は無給になりますので、その点の影響等が大きいところです。例えば平成１７年度と比べて、平成１８年度は人員が減って、給与財源の構成上の差が生じたものと考えております。 普通退職者、あるいは人事異動ですまいるスクールのほうへ異動したりという者が６名おりまして、９１名ということになりました。この差額です。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"保育園のほうとしては、いろいろ制度上の関係だということで、今後、同様の考え方でやっていくということだったと思います。民間のほう、これが今後やはり増えていくということになると、職員費ということについては下がっていくと考えてよろいしんか尋ねました。","respondent":"諸岡児童課長","answer":"平成１８年度におきまして、４館ほど、一部業務委託を導入しております。５地区、１３ブロック、また検討していきたいと考えております。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"次に、学級環境整備事業、この中の校舎等整備の中には、例えば体育館とか、校舎とかの設備も関係しているという形でよろしいですか。どういう内容のものが入っているんか尋ねました。","respondent":"市川庶務課長","answer":"あるいは、プールの塗装、防火区画の整備、こういったものも含んでおります。それらも一連を含めて校舎等整備ということで対応しております。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"それを改修してほしいので、１月ぐらいに聞きましたら、年度内では予算がもうないと。安全性を考えると、すぐに改修するべきではないのかというふうに思うんですが、その考え方はいかがなものなんか尋ねました。","respondent":"市川庶務課長","answer":"その一方、施設はやはり生き物ですから、随時対応しなくちゃいけないというケースもあるということは承知しております。こういった一連の工事ニーズに対しまして、１年間の予算額の中でどう対応していくか、これが一つあります。","id":"exchange-112"},{"speaker":"土井委員","kind":"質問・要望","question":"さらに５９ページの公共施設整備基金積立金追加分等に関すること、とりあえずこれを中心にお伺いして、ちょっと聞かせていただきたいと思っています。したがって、そこを整理する意味で、特別交付金の違いを、私が間違ったことを言うとまずいでしょうから、正しいものを教えていただきたいということ。","respondent":"日下部企画財政課長、蓼沼高齢福祉課長","answer":"平成１８年度については、一応起債で充当しようということで考えておりましたけれども、そういうことも都区の協議の中でいろいろございました。整理をしてまいりまして、５月末の出納整理期間中に、これを執行するというものです。６５ページの在宅介護支援センター運営費の関係ですけれども、昨年４月の介護保険制度の制度改正に伴いまして、電算システムの改修がございました。","id":"exchange-113"},{"speaker":"土井委員","kind":"質問","question":"伺っておりましても、補正予算はなるべくないほうがいいんだと、できればやらないほうがいいというお話ですよね。１１月の第３回定例会とか、第２回定例会ですと、そもそもについてお伺いをしたいと思います。","respondent":"日下部企画財政課長","answer":"全体像について明らかにして、議会の議決をいただくと、そういう一つの手順としての必要性等もあると思います。そういう一つの年度間のつなぎの役割も担っていると考えておりますので、歳入、ご審議いただくという考え方でおります。","id":"exchange-114"},{"speaker":"土井委員","kind":"確認","question":"だから、その時点では、ある意味では、第４回定例会のころから後のところをどうみんなが見るかということだろうと思うんですね。都の支出金だとか、そういう歳入面は、少なくともここで確認しなきゃならないことなんですね。","respondent":"日下部企画財政課長","answer":"それはそれで、歳入、歳出の関係を財源的な構成について明確になるようにお諮りをするということも一つあろうかと思います。","id":"exchange-115"},{"speaker":"土井委員","kind":"質問","question":"真剣に、まさしく１円も間違いのないようにこういうものをつくらなきゃいけないわけですから、大変だなと思うので。すぐにどうなるというものでもなさそうなので、これをもって終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"新規購入１,５００m2だと思ったんですが、確認として、どのぐらいのグラウンドができ上がってくるのか。その辺から、教えてほしいと求めました。","respondent":"松代管理工事課長","answer":"そういった点は、周辺のフェンスを高くすることで、野球等の機能には満足いただけるような整備にしたいなと考えています。１９台から２０台、何とか設置できればなと、計画を進めているところです。","id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２０台という台数があれば、あそこは１面でしょうから間に合うと思うんですが、あそこもかなり危ない。ですから、利用者の要望をまだ調べていないのか、それとも、現状どうなっているのか、先に。","respondent":"松代管理工事課長","answer":"そうは言いましても、やはり相当雑木林みたいになっておりますので、移植可能なものが約２割弱ぐらいです。人工芝等の計画は、現在のところは考えてございません。","id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その際は、よく現在の利用者の状況も確認していただいた上で、区のほうで考えていってもらいたいと思います。それから入り口の問題も考えなきゃいけないと思うので、その辺、いかがか尋ねました。","respondent":"藤田道路公園課長","answer":"青空野球場ですが、２月１日から、入口が変更になってあります。ご利用者には、現地、あるいは生涯学習課の窓口のほうで、ご案内のビラをお配りしながら、今まで対応してきてあります。","id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それからもう１点のほうに移ります。民生費補助金の福祉施策包括補助金２４７万８,０００円、これでいいんですよね、財源が変わったということでとの意見を述べました。","respondent":"久保田防災課長","answer":"新たな課題に取り組む試行的事業ということで採択されまして、先ほど出ました４９ページにある２４７万８,０００円、採択されて補助金になったです。","id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その中で、高齢者の支援ということからこれに入っているのかなという思いもあったんです。来年以降も同じように続いてきて、新たにまたこれからもアドバイザーの育成を進めていくのかどうか、そこら辺の考え方を説明を求めました。","respondent":"久保田防災課長","answer":"２３区で初めてですので、先駆的事業ということで、そういう意味合いで採択されたと聞いております。今年は全額ということなんですけれども、来年度も半分は見てくれるという話になっていると聞いております。","id":"exchange-121"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"補助金がなくても、区の一般財源でもやっていくべき話だと思いますので、ぜひ活用していってほしいと求めました。これが変わっちゃってどうするの、区のほうもやっていく中で、その辺のお答えをいただけばと思います。","respondent":"久保田防災課長","answer":"それから、ＡＥＤについてなんですけれども、ＡＥＤ講習、今年の８月に、総務省消防庁から変更があったと聞いております。そういう点でいけば、新しく変わったということについても、大きな混乱はないんじゃないかなと認識しております。","id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"だれかこれから防災のリーダーになっていくべき人が、その辺もよく検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"堺委員","kind":"質問・要望","question":"補正予算で９２億８,８０４万４,０００円計上されているわけですけれども、内容というんでしょうか、これについて確認をしておきたいと思います。そのときにおそらく出た要望だろうと思うんですが、その辺の具体的な要望の内容について、確認の意味で教えていただけましょうか。","respondent":"日下部企画財政課長、浜脇街路事業担当課長、松代管理工事課長","answer":"国文学研究資料館跡地の取得、来年予定しておりますので、そちらに充てていくということが１点です。今後の公共施設の耐震化の事業が… 今年度の補助金の交付額が４億７,０００万円になったというようなことで、４億５,０００万円ほどの収入があったものですから、今回の補正に至ったです。昨年８月に説明会等をしまして、その際、また地域の町会等からの要望ということでございました。","id":"exchange-124"},{"speaker":"堺委員","kind":"質問・要望","question":"早く完成をさせていただきたいという思いがあるので、事業は当初予算どおり執行して、確認をしているわけです。あそこもちょっと高いですから、具体的な話が出ていたのか、どうか。","respondent":"堀越行財政改革担当課長、浜脇街路事業担当課長、松代管理工事課長","answer":"それについて、先般、回答をしているところです。建物については、今後、どういった形で利用するのが一番有利な形になるのか等を含めまして… １６３号線の関係ですけれども、あと残り約２年ですので、その工期内に、事業期間内に終わるように、今後とも努力してまいります。それから、先ほど申し上げましたように、やっぱり橋の高さを１ｍぐらい下げなければいけないということで、そういった変更をしております。","id":"exchange-125"},{"speaker":"菊地委員","kind":"質問","question":"７９ページの大井町周辺の地区再開発事業、それとあわせまして、７２ページの中小企業対策に関連して、お聞きをしてまいりたいと思います。それから、これからの展望なんかについても、ちょっとお聞かせ願いたいと思います。","respondent":"青木都市開発課長","answer":"７９ページ、平成１８年度歳出で予定しておりました大井町西地区というところで再開発準備組合が結成されておりまして、減額しています。","id":"exchange-126"},{"speaker":"菊地委員","kind":"意見","question":"安売りなり、飲み屋なり、大型のチェーン店が非常に目につくようになってきています。実際に今のこういう商店街の状況なんかを見ないで形成をしていけるのか、そういう展望があるのかというところを、ちょっとお聞かせを願いますとの意見を述べました。","respondent":"青木都市開発課長","answer":"まちのにぎわいということで考えますと、地元商店街の方々を圧迫するという結果もあることは十分に、委員ご指摘のとおりだと考えています。お客様を呼べるような施設の導入というようなことを検討しながら、まちづくりを進めていきたいと、区としては考えております。","id":"exchange-127"},{"speaker":"菊地委員","kind":"意見","question":"ここに、２０年も前に区の区民部商工課というところが、当時の名前みたいですが、行った近隣の商店街の調査表があるんです。開発というよりも、商業という目線で見たときに、どうなのかを、ちょっとお知らせくださいとの意見を述べました。","respondent":"金子産業振興課長","answer":"大型店とどう連携していくかということが、あるいは来年度においても、そういう予算を組み立てて支援をしていこうとしています。この大型店と連携して、私どもも、そういう方向の支援をしています。","id":"exchange-128"},{"speaker":"菊地委員","kind":"質問","question":"要は、開発を進めて、大型店を誘致をしてくる、そういう形式そのものが、こういう都心部でも崩れつつあるんだということなんじゃないですか。地区計画、開発を進めるということでまちづくりが進む、こういう考え方が、そもそも崩れてきているんだということが言えるんじゃないか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"Ｂ地区、それから問題のＣ地区といったところがまだ手つかずの状態で残っておりますので、いわゆるまだ発展途上の地域であるというに認識です。ただ、私が３０年前に大井町で電車を初めておりたときと比べれば、天国と地獄の違いのように発展しているのは事実だろうと思います。","id":"exchange-129"},{"speaker":"菊地委員","kind":"質問・要望","question":"まだ、核店舗として誘致をした大型店が撤退をしていくというのは、そもそも基本になっている部分が大きな間違いを起こしているんじゃないでしょうか。後継者をつくっても、皆さん廃業されるという実態があるわけですから、ここをもう少しきっちりと見たご答弁をいただきたいんです。","respondent":"金子産業振興課長","answer":"１８年前に、また現在の経済状況から見てどう判断するか、これは丸井の判断によろうかと思います。大井町のにぎわいを継続するような方向で検討されているということですので、今後とも、この商業の支援というのをしていきたいと考えております。","id":"exchange-130"},{"speaker":"菊地委員","kind":"意見","question":"そこに対する責任というのを、もっと明確にしてくださいよ。最後との意見を述べました。","respondent":"山田区民生活事業部長","answer":"これは全国展開の中で、ご自分の経営的な判断ということで、私どもは認識をしております。その後も責任を持って、今の条件のまま新たな企業と話し合いをしているです。","id":"exchange-131"},{"speaker":"石田委員","kind":"確認","question":"品川区というか、特別区側は、東京都がそういうふうに思っていると思っているのか、どうか、それを確認したいと思います。都はそれをすべて黙って承認しろということの話し合いというのはできるのか、できないのか、そこら辺の確認をお願いします。","respondent":"日下部企画財政課長","answer":"この間、２３区が以前からずっと東京都に対して、この見込み差については最小限にすべきであるということを一貫して強く主張しておりました。２３区間の足並みをそろえることも含めて、取り組んでいくということでありますので、今後の課題として受けとめているところです。","id":"exchange-132"},{"speaker":"石田委員","kind":"質問","question":"質問になかなかお答えしてくれてないと思うんですけれども、本会議で強くお話があったと思いますが、改めて伺います。区長も強い姿勢で臨んでいただけると思いますが、改めて、その決意みたいなものをお聞かせ願います。","respondent":"濱野区長","answer":"その中で、どれだけ特別区が自主的な水平調整をできるかというのは、正直申し上げて、かなり難しい問題だろうと考えています。徒手空拳というのか、何か研究といいましょうか、技術的に水平調整の研究をする必要があるのではないかなと思っているところであります。","id":"exchange-133"},{"speaker":"石田委員","kind":"提案","question":"それで、がんがん品川区から提案をしてやっていく。それをもし品川区から提案してやっていったとしたら、ぜひ提案をしてがんがんやってほしいと思うのか、これもあわせて説明を求めました。","respondent":"濱野区長","answer":"といいますのは、５２％から５５％にすることについては、２３区だれも異論はありません。ある程度、２３区が足並みをそろえた運動の中で進んでいくべきではないかなと、こんなふうに思っているところであります。","id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/472478?Template=document&Id=874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":122157,"voices":329}},{"id":"h19-20070306-3","meetingId":"h19-c-budget","date":"2007年3月6日","dateIso":"2007-03-06","committee":"予算特別委員会","time":"午前１０時０３分～午後５時４９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件整理しています。","topics":[{"id":"topic-01","title":"◯林（宏）委員長 ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１９年度品川区一般会計予算","agenda":"◯林（宏）委員長 ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１９年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"１１６ページ、介護福祉専門学校修学資金貸付金元利収入のことで伺います。裏返せば３年以上、理由を伺いたいと思いますので、答えるよう求めました。","respondent":"蓼沼高齢福祉課長","answer":"修学資金貸付金の減ですけれども、手元に詳細な資料がございませんけれども、回収についての返還の状況が、一定程度働きかけ等もあって、スムーズにきているということで、平成１８年度の実績の見込みから今年度、こういうような予算立てをしたものです。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"これは回収不能というので、私は今、受け取ったんですけれども、このような受け止め方でいいんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"例えば貸付の新規貸付の件数が平成１８年度は従前と比べて減ってきております。それから、償還の免除になった方等が増えてきているということの入り繰りの関係で、今年度はその実績を踏まえて予算を計上したものです。","id":"exchange-002"},{"speaker":"大沢委員","kind":"確認","question":"私、最初にそれを伺ったんです。そこが先ほどのご答弁であった回収不能ということでおっしゃっていたので、そうではないですかということで、もう１回確認させてください。","respondent":"蓼沼高齢福祉課長","answer":"回収不能ということではございません。","id":"exchange-003"},{"speaker":"大沢委員","kind":"意見","question":"しかしながら、この介護福祉の専門学校、近年、生徒数、定員は４０人ですけれども、卒業生が減少しております。３０人の半ばということですけれども、それについての減少をどのようにとられていらっしゃいますかとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"その減少の傾向の要因といたしましては、まず第一に少子化の傾向があって、そういう子どもの数が少なくなってきているということが１つあります。","id":"exchange-004"},{"speaker":"大沢委員","kind":"意見","question":"きついとか、いろいろな３Ｋではありませんが、そのようなものがこの介護福祉の現場は非常にイメージされています。ここらあたりの問題意識というか、危機感でとらえられているのか、お答えくださいとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"そういう、なかなか福祉的な現場に対する希望といいますか、そういう方が若干少なくなってきているのかなということは認識しています。しばらく、この入学者の確保の状況についてはＰＲ等に十分努めながらも、状況の推移については見きわめてまいりたいと考えています。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"平成１５年度２３人ということで、１０人近くが優秀な品川区の介護福祉専門学校で、非常に高度な技術を持った方が区外に転出してしまっている。そこには職業選択の自由がありますけれども、そのような何か工夫はされているところはあるんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"３６人中３３人の方が就職を予定されていまして、まずまず区内の施設のほうに就職されている傾向が強くなっていると考えております。なるべく区のほうとしては、区内の施設への就職をしていただくよう、今後とも働きかけをしてまいりたいと考えています。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、区でも団塊の世代ということで、１０年先、１５年先、非常に大変な状況になりますので、先を見据えて政策を打ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"この間の民間への建築確認ができるようになって以来、実際に建築確認をしている自治体として、国に求めてきたようなものというのは。その辺もまずお聞かせを願いたいと思います。","respondent":"片田建築課長","answer":"それと２点目の改正についての考えですけれども、建設委員会でもご説明しましたように、今回の予算書のほうにも前年度比で件数を３４５件と。４５件ということもありますので、現行の人員体制の中で、鋭意進めていきたいと考えています。","id":"exchange-008"},{"speaker":"菊地委員","kind":"確認","question":"現在の人員で３割増になってもできるというんですけれども、その辺、今現在の職種と担当されている人員をちょっとお知らせ願えますか。新しいコストというんでしょうか、９８年の建築基準法の改正で、民間でも建築確認ができるようになったというのがもとだと思うんですけれども。","respondent":"片田建築課長","answer":"そういう３００件、あるいはその中のピアチェックを含めた検証の中で、現行の体制で進められると判断している状況です。法が改正されたと認識していますので、安全等についての検証を得て、安全に暮らしていただく形での法改正と考えています。","id":"exchange-009"},{"speaker":"菊地委員","kind":"確認","question":"確認を出そうという流れがあったと私は思っているんですけれども、変わってきているのかどうか、その辺をちょっとお知らせ願いたいと思います。今度の改正の中で、すべてが解決をしていくんだとお考えなのかどうか、その辺もちょっとお知らせください。","respondent":"片田建築課長","answer":"処理していきたいという考え方の中で、法に定められた申請期間が２１日間といった中で、そのような体制で進めてきたという経過があります。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"結局はなってしまったわけですから、検査は自治体の委託で行っていくというような形というのが、どうしても求められるのではないかと思うんですね。事件が起きた以降、構造計算をする人員を１人増やしたというだけのようですけれども、この辺をもう少し明確に教えていただきたいんですけれども。","respondent":"片田建築課長","answer":"この法律が改正された平成１０年においては、技術的な判断については民間でもできるといったような考え方で、法が改正された経過があります。それと現在の体制については、やはり技術の継承が大事だと思っていますので、その辺を十分対応していきたいと思っています。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問・要望","question":"６２ページのシルバーセンター使用料、６４ページの健康センター使用料、６８ページの自転車駐車場使用料についてお聞きしたいと思います。昨年の当初予算より０.３％増ということでお聞きしたんですけれども、その辺の考え方を勉強不足なので教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"一番わかりやすくご理解いただくという意味で、前年度当初の段階での比較をしていただくと、これがまず基本です。ただ、最終段階でいろいろな事情の変更等もありますので、年度の比較をまたしていただくということで考えてあります。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問","question":"そうすると、いろいろな考え方があると思うんですけれども、平成１８年度は１,４００億円実際には予算がかかったという中で、ことしは少しそこから比較すると当初予算の組み方は減ってしまったというふうに考えると、変な考え方になるんか尋ねました。","respondent":"日下部企画財政課長","answer":"財調の交付金等も当初見込んだ以上に、いろいろな社会経済情勢も含めまして、歳入の増もありました。いろいろ１年間を通して、この１年間の動きというものを読み取るというのがなかなか難しい面がありますので、そういうことで私どもは理解しています。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問・要望","question":"６０ページの区民保養所使用料というところで、例えばロビーとか部屋とかに置いてあるんじゃないかと思うんですけれども、その辺の確認をさせていただきたい。","respondent":"鷹倉区民課長","answer":"区民の声をできるだけ反映するような形で委託業者が仕事をしていく。あるいは区が仕事をしていくという形で、そのような体制をとらせていただいているところです。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"こういったお声があるよとか、そういった体制というか、連携というのはどのようにとらえているんか尋ねました。","respondent":"鷹倉区民課長","answer":"区民の方によっては、念には念を入れてということで、直接区のほうに要望を申してこられる方もいらっしゃいます。そういうものを踏まえながら、予算の範囲内でこたえられるものについては即対応していきたいと考えているところです。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"何でそういうふうにしなかったんですかと聞いたら、申し訳なくて言えないとか、何かそういう感覚の方もいらっしゃるんですね。その辺の配慮、心遣いということの対応を促していただきたいと思うんですけど、いかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"高齢者の方は遠慮されて、もっと和やかな雰囲気で言えるような雰囲気をつくるように施設の受付のほうをうまくやってほしいと話をしております。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"嫌な思いをして帰るかという、その辺のところをぜひ管理人の方とか、そういうシルバー人材センターの方にもお話をしてほしいと求めました。比較的若い方の健康に対する意欲というか、運動意欲といったものについて、区のほうはどのように考えていらっしゃいますか尋ねました。","respondent":"谷田部健康課長","answer":"その辺の自分で自分の健康を管理するというようなことから、大分運動のほうに注意を向けているという傾向が出てきているのではないかと。そういうことが健康センターの利用のほうにも結びついていると考えているところです。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問・要望","question":"区の関連で２つのセンターでやっているんですけど、前にもご質問しましたけれども、ちょっと行きづらいと言うんですね。方向というか、そういうのもお考えなのかどうか、教えてほしいと求めました。","respondent":"谷田部健康課長","answer":"私ども健康センターを２カ所設けてあります。私ども、これは民間が先行して十分やってきたですので、現行の健康センターの中で十分活用していただきたいと思っているところです。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"何か適切なそういう人たちが体を動かせるような整備をしていただきたいなと考えていますので、ぜひこれは要望します。６,０００台、単純にこの１年間で定期利用が６００台、それから一時利用が１万７,２００台増設されたということでよろしいんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"これはバイクの置き場も考えているところです。現在の区営の駐輪場を自転車の部分をバイクに変更するとか、そういったものも考えておりまして、そういったものの数です。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ私ども今、なかなかその辺の方が簡単に動かせないということもありますので、ぜひバイクも駐車場の増設を早急に図っていただきたいと思うんです。ほかの場所についてもある程度具体的なものがわかれば教えてほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"そういった中で、現在は年間９,０００台を西口だけでも予定をしています。他の部分につきましては、それぞれ駐輪場ごとの数ですので、それはこれからいろいろ十分検討していくです。","id":"exchange-020"},{"speaker":"大西委員","kind":"質問・要望","question":"それともう１点、確認をさせていただきたいということと、事故があったやにも少し聞く部分があります。記念の植樹というんですか、実際にしているかどうか、どんなものか尋ねました。","respondent":"松嶋交通安全担当課長、冨岡高齢事業課長、金子産業振興課長、田村地域活動課長、藤田道路公園課長","answer":"そこはバイクの駐車スペースを現在のところは３０台ということで考えておりますけれども、需要が多いですから、もうちょっと増やす予定もしています… 私からシルバーセンターの浴室についてご説明申し上げます。設置する場所はあまり近過ぎても、区内非常に広うありますので… 商店街におけるポイントシステムというのがありますけれども、これを新しく導入するところがありまして、これの補助が大きいものです。","id":"exchange-021"},{"speaker":"大西委員","kind":"質問","question":"きゅりあんのところにバイクを置くところが２台しかないという状況で、５月ぐらいでしたか、どうも前に一歩も進んでいないと。テリトリーが違うので、区があまり口が出せないのかもわかりませんが、この辺についての考え方を説明を求めました。","respondent":"鷹倉区民課長","answer":"しかし、その課題を何とかクリアできないかということで、検討しています。もう少し時間の猶予をいただきたいと考えています。","id":"exchange-022"},{"speaker":"大西委員","kind":"提案","question":"こういう記念植樹はいかがですかという、区からの企画というんですか、提案をされるのではどうかなと。実は品川区ではお子さんの誕生のご記念として、こういう形での記念植樹をされたらどうですかというご案内をしていますが、いかがなものでしょうかとの意見を述べました。","respondent":"藤田道路公園課長","answer":"この辺をよく見きわめないと、最終的な公園管理の面で、つながっていかないのかなと考えています。委員ご指摘のご趣旨も十分に踏まえながら、今後の検討課題にさせていただきたいと考えています。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"２点あります。１２４ページの特別区職員互助組合保有財産返還金と、まず初めに１２４ページのほうからお伺いしますが、変わった経緯について教えていただけますか。","respondent":"榎本人事課長","answer":"たしか平成１７年だと思いますけれども、大阪市の福利厚生の問題が出たときに、いろいろ見直しをしてまいりました。そういった中で、品川区分として、この１億９,６００万円が返ってきたという形です。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"１億９,６００万円という高額なお金が戻ってきたんですけれども、具体的にこのお金はどのような形で処理されていくんか尋ねました。","respondent":"榎本人事課長","answer":"処理というのは、この使い道という形ですか。これにつきましては、ちょっと明後日の歳出になってしまいますけれども、職員待機寮の建て替えの経費の一部に当てたいということで考えております。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"１億９,６００万円と、やっぱり区民の皆さんに理解をされるような使い方をしていかないといけないと思うんですけれども、改めてその辺についてはどのようにお考えか尋ねました。","respondent":"榎本人事課長","answer":"その１０９億円の中で、２３区のほうに戻すものという形で分配をしまして、その部分が戻ってくるという形になります。今まで品川区のほうで福利厚生のためにずっと出してきたものですので、職員の福利厚生のほうに戻していこうという考えです。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"次に３７８ページの公債費についてお伺いしますが、１８年度末の公債が４１０億円あるということは、その辺の説明をわかりやすくしていただけますか。","respondent":"日下部企画財政課長","answer":"家計で考えれば、この特別区債の平成１８年度末４１０億円、ローンを抱えているということになるわけです。この起債の４１０億円にしましても、そういった意味で考えますと、そういった意味ではトータルで考えれば心配はないと考えております。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"私も公債、区債発行を決してしないほうがいいという考えもないんですけれども、その中で今回、区債ゼロという形で、２３区でもまさに抜本的なといいますか、決断をなさったと思うんですけれども、その辺のバランスというのは、どのように考えているんか尋ねました。","respondent":"日下部企画財政課長","answer":"今回、起債の発行を四十数年ぶりに取りやめたというのは、先ほどもご説明させていただきました。いろいろ考えますと、これは借金をしないで対応できたほうが、それにこしたことはないわけです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"最後になりますが、ここの合計額の４１０億円が、品川区としてする仕事はちゃんとして、そしてこの額が減ってくるということが、やはり区長の手腕だと思うんですけれども、その辺についてはいかがか尋ねました。","respondent":"日下部企画財政課長","answer":"例えば一時的に多額の負担が必要なときに、これを年度間で１つの一時的な負担の軽減が図れる、年度間調整ができるということ。そういう考え方も含めて、できるだけ負担の、借金の軽減は図ってきているということでご理解をいただきたいと思います。","id":"exchange-029"},{"speaker":"三村委員","kind":"質問・要望","question":"私からは６５ページの健康センター使用料について、そして１２８ページの議会費についてお伺いいたします。区民の健康の維持・増進に対して十分活用されているということが伺えるんですけれども、また貸し出し状況についてお聞かせほしいと求めました。","respondent":"谷田部健康課長、高橋品川区保健センター衛生課長","answer":"保健センターの中にあります調理室は保健センターの事業で使う調理室ですから、健康センターの施設ではないです。 この調理室につきましては、栄養の具体的な事業を進めさせていただいている部分でございまして、例えば乳幼児の離乳食の調理の問題とか、あと糖尿病の教室の調理の問題ということで使わせていただいておるところです。","id":"exchange-030"},{"speaker":"三村委員","kind":"質問・要望","question":"区民が借りることのできる、こういう調理スペースは品川区内にどの程度あるのか、お聞かせほしいと求めました。平成１９年度予算を見ますと、力を入れていこうということが伺えるんですけれども、お考えを伺いたいと思います。","respondent":"富田生涯学習課長、川口品川区保健センター保健サービス課長、谷田部健康課長","answer":"文化センターは荏原文化センターと五反田文化センター、２カ所に料理講習室があります。うちの所管ではございませんが、きゅりあんにもあります。先ほども健康課長がお答えしていますけれども、保健センターの調理室は保健センターの各種事業ということで利用しています。… それから離乳食の中期教室ということでも年間６回ほど。","id":"exchange-031"},{"speaker":"三村委員","kind":"質問・要望","question":"最初に議長交際費についてお伺いいたします。区長交際費、また議長交際費は区民へどのように情報提供されているのか、その内容について伺いたいと思います。","respondent":"市岡区議会事務局長","answer":"全般に区長交際費に比べると、ほかの自治体も含めて、議長交際費の公開度が低いという記事かなと考えています。それから議長交際費については、当然これは情報公開によって公開しておりますが、いわゆる公表という形では今現在行ってございません。","id":"exchange-032"},{"speaker":"三村委員","kind":"提案","question":"議長交際費のほうなんですけれども、執行率、内容についてお伺いをしたいと思います。その投げかけに対して、どういった検討が行われたのか、もし把握をされていればお伺いしたいと思いますとの意見を述べました。","respondent":"市岡区議会事務局長","answer":"それからいわゆる弔辞の儀礼、香典ですけれども、これが２３件等です。これは私がお答えすべき内容ではございませんので、当然、会派にはその結果というのはご存じだろうと考えています。","id":"exchange-033"},{"speaker":"三村委員","kind":"提案","question":"議長の専用の公用車があるというふうに伺っておりますけれども、専門のドライバーもついて、そういった認識で間違いがないのかどうか。こちらの１２９ページの議会費のところには、どうしてなのか、その点についてお伺いしたいと思いますとの意見を述べました。","respondent":"市岡区議会事務局長","answer":"２番目のご質問にも関連するんですが、総務費の自動車運行管理費、明後日の款のところになります。","id":"exchange-034"},{"speaker":"三村委員","kind":"質問","question":"ほぼ１台丸々占有されているような状況にあるというふうに認識しているんですけれども、それぞれ車１台と人１人が専用で張りついていると聞いているんですけれども、その点についてはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"三村委員","kind":"質問・要望","question":"１,７３８万円、こういった費用弁償の支給対象には、この議長も含まれているという認識でいいのかどうか。交通費としての意味合いもある、交通費の二重支給に当たるんじゃないかと考えるんですけれども、その点についてはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"三村委員","kind":"質問","question":"費用弁償については、いろいろご意見があるということで、さまざまな費用というふうにおっしゃっていらっしゃったんですけれども、このさまざまな費用を具体的にいろいろな項目があると思うんですけれども、どういった項目になってくるのか、ちょっとその点について詳しくお伺いしたいと思います。","respondent":"市岡区議会事務局長","answer":"今申し上げたとおり、いわゆる出会手当の費用弁償は積み上げ方式ではありませんので、１件幾らという額で規定をされているです。","id":"exchange-037"},{"speaker":"三村委員","kind":"質問","question":"質問の仕方が悪かったです。さまざまな費用ということで、認識をさせていただいているんですけれども、その点についてはいかがか尋ねました。","respondent":"市岡区議会事務局長","answer":"私の説明が悪いのかもしれませんが、そういうご意見もあると、そういう見解もありますが、いろいろな見解がある中で、現在は１件定額で支給されているです。","id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"永年在職議員表彰についてお伺いをしたいんですけれども、３０年在職で２０万円、この中でどういう議論によって決定がされているのか。条例ではどういうような規定になっているのか、お伺いをしたいと思います。","respondent":"市岡区議会事務局長","answer":"議会運営委員会でどういう議論があったかは、委員も十二分にご案内のとおり、非公開ですので、私がお答えすべきことではございません。議会のほうの問題ですので、これはいわゆる議員表彰の内規で決まっているということで、これも議員ご案内のとおりです。","id":"exchange-039"},{"speaker":"三村委員","kind":"質問","question":"条例に基づかない形での支給になっているということでよろしいんでしょうか。どういった情報を得る手段があるのか、この表彰自体が見えるような手段があるのかどうか、その点について伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"三村委員","kind":"質問","question":"議会だよりの中でということで、その中でもあるということだったんですけれども、そういうつくられていく議論の過程は見えないというふうな認識でよろしいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"三村委員","kind":"質問","question":"こうせい、ああせいではなくて、どういうふうに区民の方から見えるのか、議論の内容についてどういうふうに外から見たときに、見られる手段があるのかについてお伺いをしたいんですけれども、その点についてはいかがか尋ねました。","respondent":"市岡区議会事務局長","answer":"お答えになるかどうかわかりませんが、区議会全体の予算としてどういう要望をするかということについて、各会派のご意見を議長が集約をされました。そのときに今、今のご質問のようなご意見が出ていなかったということだけ、ご確認をさせていただきたいと思います。","id":"exchange-042"},{"speaker":"三村委員","kind":"質問","question":"公表がどうなっているのかについて伺ったんですけれども、こういった議論の内容についても外に向けてもきちんと公表していくべきではないかと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほどの質問にもあった中で、１２４ページの１９款雑収入、先にこれをちょっと確認したい。必要があるから発行していくということでしょうけど、ある程度目安というのはつけているのかどうかという点を確認したい。","respondent":"榎本人事課長、日下部企画財政課長","answer":"１７年度末で１０９億円、特別区互助組合が持っているということで、２３区のほうに配分されるのが７４億円、特別区互助組合が今後の互助組合事業として使う原資として、３５億円を残すという形です。 いずれにしろ、トータルでの借り入れが過度にならないという前提のもとで、どうやってバランスを保っていくのか。この辺が重要なポイントではないかと考えています。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと同時に財政調整積立基金のほうは６億１,０００万円、こっちもどの辺まで積んでいくのかなというが、基準的なものはあるのか。どういう判断をしていくのかというのもちょっと教えていただきたい。","respondent":"日下部企画財政課長","answer":"つまり、これから特に将来の財政見通しを考えますと、必ずしも楽観できない状況にあると思います。若干足りない部分がありますので、その辺を今回、平成１９年度で少し大目に積み増しをするという考え方です。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その品川区の予算全体を考えたときに、今までの３年間をどういうふうに判断するか。昨日、区長からもその辺の話があったと思いますが、総括して、どういうふうに考えるかを説明を求めました。","respondent":"日下部企画財政課長","answer":"品川区だけではありませんが、品川区の場合はトータルで約２０億円、税源移譲の分でマイナスが出ました。そういうことで、区の財政には非常に厳しい結果になったということで受けとめております。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２０億円という大変大きな金額が税源移譲、これは区としては基準財政の枠の中で、財調で最終的には補てんということで考えていいんですか。その辺だけ聞いて終わりにいたします。","respondent":"日下部企画財政課長","answer":"特に税源移譲でマイナスになる金額が大体１億６,０００万円ぐらいで今、見込んでおりますけれども、交付分については増えると。それが今回、平成１９年度の財調協議の三位一体改革への影響の対応ということで、２３区は主張したという、１つの背景です。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"提案","question":"今回の条例提案の改正点、３点なんですが、これに絡めて、ご質問をします。１点目ですが、なぜ手数料を有料化としているのか、このことについて、区のお考えをお聞きしますとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"地方自治法の第２２７条に基づきまして、それに基づきまして、品川区としても手数料条例を設けているところです。情報公開条例には一定の事務量がかかりますので、相当の労力をそこで割かせていただくということで、手数料を徴収させていただいているものです。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"議員が求めても手数料を取るのが本当に日本国中でこの品川区だけとなっているわけですけれども、この特定の者のためという、もう１度お伺いをしたい。なぜ知る権利が入っていないのかという点と、このことも入れていくべきであると考えますが、この点について区のご見解をお伺いいたします。","respondent":"中川原広報広聴課長","answer":"その審議・検討または協議に支障が生じる場合については、そういった行政情報の公開をしなくていいというふうに定めているものです。区民に混乱を生じさせてしまうおそれがある場合とか、そういった場合に限定しまして、非公開とするという形で運営させていただいているものです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この条例は公文書の公開を求める区民の権利を明らかにするとともに、もって区民の知る権利を保障し、区民の区政への参加の機会の拡大。こういった内容を受けても、なおかつ地方自治法の本旨といった機械的なご答弁で済まされるのか、その辺をお伺いしたいと思います。","respondent":"中川原広報広聴課長","answer":"そういった中で、私どもの条例では情報公開できる権利を具体的に請求しているということで、そういったことを実現しようとしているものです。情報公開制度の運営も適切になされるということで、先ほど委員が話されましたことは十分担保できていると考えています。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つ、平塚中学校の小中一貫校のところに今年の２月の初めに、大変な混乱の状況になっています。区政を進めるに当たって、住民の声を最も聞いていかなければいけないと思っていますが、この点についてはいかがか尋ねました。","respondent":"中川原広報広聴課長","answer":"今の事例に当てはまるかどうかわかりませんが、意思形成過程というのは、行政情報が持っている会議録のことを情報公開条例の対象としているものでありまして、この間、こういった会議、この件に関しましての会議についての意思形成過程の情報公開請求は出ておりません。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区長は今第１回の定例会の中で、ぜひこういった情報公開もよりクリアに透明度を高めていただきたいと思うんですが、いかがか尋ねました。","respondent":"中川原広報広聴課長","answer":"議員のご質問は情報公開制度と情報を公開してほしいということが何か一緒になっているように受けとめられるんですけれども、情報公開制度の運用としては、対象になる文書は公開できる段階で公開をしていますし、それにつきまして請求が出る場合にはお出ししているところです。","id":"exchange-052"},{"speaker":"若林委員","kind":"質問・要望","question":"これは単純に昨年、平成１８年度の当初予算の中では８００件という表示がございまして、今回、平成１９年度の予算では１,５００件です。およそ倍に増えているわけですけれども、内容についてお知らせをほしいと求めました。","respondent":"上川内戸籍住民課長","answer":"前年の実績に合わせてやってあります。平成１６年度が８３４件、平成１７年度が１,３００件になってありますので、１,５００件で予算計上したものです。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"年々上がってきているということで、いわゆる今後の住基カードの利用についてなんですが、多目的な利用について、今後の取り組み、区民の利便性が高まるという意味での交付の数の増大とともに、その内容についてもお知らせほしいと求めました。","respondent":"上川内戸籍住民課長","answer":"多目的活用なのですが、国のほうも一生懸命活用に努めているところなのですが、やはりなかなか制約がございまして、国が思ったとおりには進んでいないという現状があります。","id":"exchange-054"},{"speaker":"若林委員","kind":"意見","question":"それからただいまのご発言でありましたけれども、他自治体等の様子を見ながらですけれども、さらにどういうサービスを視野に入れているのか。少しずつですけれども、年々増加する住基カードのニーズのとらえ方をどのようにされるか、端的にお答えをお願いいたしますとの意見を述べました。","respondent":"上川内戸籍住民課長","answer":"住基カードを単体で、なかなか自治体が独自でサービスを拡充していくというのは国も悩んでいるとおり、難しいものがあります。第一次サービスの情報提供の部分で、品川区の区民の方にも住民票が要らなくなったりとか、そういう点ではかなり年々充実してきているところです。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"引き続きまして、より安価で、よい区民住宅の充実に向けてご質問をさせていただきたいんですが、まず予算書の見方です。それぞれ２分の１、３分の１という係数が掛けられておりますけれども、どのようなものかまずお願いします。","respondent":"齋藤住宅課長","answer":"その４分の１、３分の１と申しますのは、住宅の家賃によって、３分の１補助をいただける住宅と、４分の１補助金をいただける住宅があります。３分の１、４分の１というのはそういう意味です。","id":"exchange-056"},{"speaker":"若林委員","kind":"確認","question":"今、３分の１、４分の１とありましたけれども、今、９０ページの国庫のほうを言っておりますので、２分の１と３分の１で、それぞれ家賃の違いによってという理解で、もう１回確認します。","respondent":"齋藤住宅課長","answer":"委員のご指摘のとおりです。","id":"exchange-057"},{"speaker":"若林委員","kind":"意見","question":"じゃ、同じ意味で、同じ家賃に対して都の補助金も上下、そのまま４分の１、６分の１になっていると理解をします。５億７,０００万円余、歳出のほうで６億６,０００万円余と、お願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"若林委員","kind":"質問","question":"その差額が単純に１億１,０００万円ぐらいですね。昨年の決算のときに伺いましたのは、１億１,０００万円以上に広がっておりますけれども、この考え方はどういうふうにとらえたらよろしいか尋ねました。","respondent":"齋藤住宅課長","answer":"一方で、使用者の方から１６億円ほどの使用料が入ってありますので、何が言いたいかと申しますと、単純に差し引きした部分が区の空き家の部分の持ち出し部分です。","id":"exchange-059"},{"speaker":"若林委員","kind":"確認","question":"そうしますと確認ですが、昨年の決算でいただきました３,０００万円強の区の持ち出しというのは、そのままこの平成１９年度の予算についてもそのぐらいを見込んでいると理解をしてよろしいんですね。","respondent":"齋藤住宅課長","answer":"今、委員がおっしゃった３,０００万円というのは空き室部分に対する区の負担分ですので、空き室部分については、使用料は入ってきませんから、もちろん国・都からの補助金も参りませんので、その部分は区の持ち出しになります。","id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"それから昨年の予算では同じく使用料のところで、およそ４億４,０００万円、このようになっております。収入が多くなってありますけれども、これは家賃が上がるということを前提にこのような算出をしているのかどうかとの意見を述べました。","respondent":"齋藤住宅課長","answer":"委員の今ご指摘の４億５,５８０万円余は入居者が全員入って、使用料もお支払いいただくということを前提にしております。使用料が増えてありますのは、年３％ずつ傾斜型家賃の部分は使用料が上がってありますので、その分が上がってあります。","id":"exchange-061"},{"speaker":"若林委員","kind":"意見","question":"ちょっと角度を変えまして、もう１回、昨年の平成１８年度の予算の中では、同じく使用料の中に連絡員手当という項目が載っておりまして、平成１９年度、来年度の予算では、この連絡員手当というのがありませんですけれども、このご説明をお願いいたしますとの意見を述べました。","respondent":"齋藤住宅課長","answer":"区営住宅には入居者の方の区との連絡をお願いすることで、連絡員という方を１棟にお一人ずつお願いしてございましたが、これを指定管理者に仕事を委託するということにしましたので、連絡員制度というものを基本的に廃止しております。","id":"exchange-062"},{"speaker":"若林委員","kind":"質問・要望","question":"一時たらい回し状態のときがあったようなことも伺いましたので、運営について、この３者の関係性を整理整頓してご説明ほしいと求めました。同時に、ここら辺の共益費の明細というものは指定管理者のほうから区民住宅利用者のほうにしっかりと提示をされるのかどうか。","respondent":"齋藤住宅課長","answer":"第１点目の利用関係についてですけれども、基本的には指定管理者が水回りですとか、修繕の関係については対応しています。その他、それを超えたものにつきましては、私ども住宅課に連絡が来ますので対応しております。","id":"exchange-063"},{"speaker":"若林委員","kind":"質問","question":"ちょっとご答弁をお願いしてよろしいでしょうか。なぜ指定管理者じゃなくて、オーナーのほうから共益費の開示をされるのか。","respondent":"齋藤住宅課長","answer":"大きな修繕、小さな修繕含めて、オーナーの方がなさっております。したがって、その収支・明細を明らかにするのはオーナーの方の責任であります。","id":"exchange-064"},{"speaker":"若林委員","kind":"意見","question":"今後は高齢者住宅等、区のそういう法律の壁を破って、なるべく空き家を少なくする努力をさらに続けてまいりますというようなご答弁がありました。昨年からまた今年度にかけてのご努力、また今後の見通しについても一言お願いをいたしますとの意見を述べました。","respondent":"齋藤住宅課長","answer":"引き続き、次に今後、現在の検討状況ですが、オーナー会の皆さんともこの委員会が終わった後、お話し合いをする場も持ってあります。こういった国の動向、国の考え方を活用しながら、空き室の多い住宅を埋めるような方向で、引き続き努力をしてまいりたいと思います。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問","question":"いわゆるオーナーの損益分岐点、こういう言い方があるのかどうかわかりませんけれども、建設時に国の補助、それから低利の融資を受けて、建築されて２０年間の契約ということですけれども、オーナーとしての損益の分岐点というのはどのように考えたらよろしいんか尋ねました。","respondent":"齋藤住宅課長","answer":"その住宅の質によって、１０年でもとをとる計算のオーナーの方もいれば、２０年を超えてもとをとる計算の方もいらっしゃいます。安定して計算できるわけでございまして、それに従いまして、オーナーの考え方によって損益分岐点というのは変わってきてあります。","id":"exchange-066"},{"speaker":"本多委員","kind":"質問","question":"６１ページの区民保養所使用料について質問いたします。平成１８年度と平成１９年度の予算書を比べて、１５人以上の団体について、箱根荘について説明を求めました。","respondent":"鷹倉区民課長","answer":"今、１５人以上の団体に限っての推移というお尋ねかと思いますが、ちょっと申し訳ございません。手元に団体だけのものを集約した資料は手持ちのほうでは持ってございません。","id":"exchange-067"},{"speaker":"本多委員","kind":"質問","question":"予算書を見ると、この部屋数、人数ですから、比べるとわかるんですけれども、団体はどうなのかなと思って、ちょっと聞かせていただきましたが、送迎バスについて、今度教えていただけたいんですけれども、品川荘、箱根荘の台数ですとか、稼働状況について説明を求めました。","respondent":"鷹倉区民課長","answer":"ただ、これは少し年式が古うございまして、委託業者のほうで用意している車がもう１台あります。箱根荘については２台を使ってありますが、１台はちょっと古うありますので、その２台を効率的に使っているというような状況です。","id":"exchange-068"},{"speaker":"本多委員","kind":"質問・要望","question":"品川荘もたしかあったかなと思ったんですが、稼働はしていないんですかね。大体３０分も歩くと、バスがどうしても民間の旅館とかの送迎バスと比べられちゃっている方が多くて、管理について教えてほしいと求めました。","respondent":"鷹倉区民課長","answer":"もう１台、業者が提供している車については、平成１４年式の車ですので、今お話の件は恐らくたまたま２台のところで、区の部分に乗られたのかなと。平成１４年ですと、それほど古くはないのかなと思っているところです。","id":"exchange-069"},{"speaker":"本多委員","kind":"質問・要望","question":"公有財産を有効的に使っていると理解して、少しでもそういう区民の要望を聞いて、できるところは取り入れてほしいと求めました。新しく取り入れるものですとか、そういった部分の条例とか要綱について、定めについてちょっと教えてほしいと求めました。","respondent":"鷹倉区民課長","answer":"今回、３月３１日で廃止になる暖景苑、これは要綱という形で定めさせていただいていました。これについては、今回、３月３１日に暖景苑が終わりますと、要綱の廃止という形になっていくかと思います。","id":"exchange-070"},{"speaker":"本多委員","kind":"質問・要望","question":"関連性があるものですから、聞かせてほしいと求めました。その平成１９年度から保養所として新しく民間施設を借り上げるというなんですけれども、そうすると、今度要綱になるわけですかね。","respondent":"鷹倉区民課長","answer":"いろいろ行財政改革特別委員会等で検討されて、予算特別委員会でいろいろ議論のある中で、保養所の見直しという形で一定の方向に進んできた。特に要綱等については定めない形で実施していきたいと考えているところです。","id":"exchange-071"},{"speaker":"本多委員","kind":"確認","question":"それをちょっと確認をします。ちょっと確認だけお願いします。","respondent":"鷹倉区民課長","answer":"ご指摘のとおり、それぞれの旅館の運営のままをそのまま借り上げていくということですので、ばらつきがたまたま出てしまうです。できるだけわかりやすい形で統一したいわけですけれども、その部分については統一できないということでご理解いただきたいと思います。","id":"exchange-072"},{"speaker":"本多委員","kind":"質問・要望","question":"今までの４７人という暖景苑の規模に対して４５人ということで、おおむね人数的には同じような方が、そういう健康増進のために利用できると思うんですが、当然、品川荘と箱根荘がありますけれども、さらに団体というところも引き続き見ていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"木下委員","kind":"質問","question":"６６ページの産業振興施設使用料のベンチャー創業支援施設の件についてお尋ねしたいと思います。ですから、現状ですとか、それから応募の倍率、数年の推移、増えているのか、減っているのですかとか、そこのところをお聞かせ願えますか尋ねました。","respondent":"金子産業振興課長","answer":"１件は２区画分使っておりましたので、計３区画があきましたが、直ちに埋まっているという状況です。応募の状況については、先ほどと同じように、２件から４件ほど来ているです。","id":"exchange-074"},{"speaker":"木下委員","kind":"質問","question":"何とか入れませんでしょうかという話を聞いたことがあるんですが、ちょっとお聞きしたいのと、考慮をするお考えはあるのかどうなのか。そこら辺、どのようなお考えを持っていらっしゃるのか等、お聞かせ願えますか尋ねました。","respondent":"金子産業振興課長","answer":"それから平成１９年度予算のほうで武蔵小山の創業支援施設の検討経費を計上していますが、これから検討をしてまいります。その辺を中心に検討を進めていこうと考えているところです。","id":"exchange-075"},{"speaker":"木下委員","kind":"質問","question":"そういう広告だとか、電子商取引というのは加熱しているんだなと、つくづく思いました。ですから、これから考えていただけるものじゃないかなと考えていますし、そういう枠なんかもつくっていただけると理解してよろしいんか尋ねました。","respondent":"金子産業振興課長","answer":"武蔵小山の施設の検討なんですけれども、１つは商業系中心である、あるいはもう１つは女性起業家の支援ができないかということ。それから立地が武蔵小山でありますので、武蔵小山にふさわしい施設というもの、こういった３点中心に考えていきたいと思ってあります。","id":"exchange-076"},{"speaker":"木下委員","kind":"質問","question":"やりがいが出るんじゃないかみたいなお話をお伺いして、ちょっと考え方として、これからいろいろな面でご協力をいただく。それに近いのももしかしたらあるのかもしれないんですけれども、そういうお考えはあるのかどうなのか、ちょっとお聞かせ願えればと思います。","respondent":"堀越行財政改革担当課長","answer":"それを地域の皆様みずからが課題を解決していくということで、町会を初めとして、これまでいろいろな活動が行われてきたと。区民、それからＮＰＯボランティア等と連携の仕組みづくりを行っておりますので、そういうのを参考にしながら検討を進めていきたいと考えております。","id":"exchange-077"},{"speaker":"木下委員","kind":"質問","question":"今回１,５００件ということですから、４,０００枚ぐらい、その手数料のほうが１,５００件の増で６５５万円減。そんなに減るのかなとちょっと思ったものですから、ちょっと何か理由があるかどうかもお教え願えますか尋ねました。","respondent":"上川内戸籍住民課長","answer":"住民基本台帳の証明手数料のほうですが、住基カードの交付の件については増えてありますが、住民票の写しは減ってあります。それは住基ネットの第一次活用が大幅に、着々と増えているということで、住民票が減っているということで、約６００万円減です。","id":"exchange-078"},{"speaker":"木下委員","kind":"質問","question":"１２０ページ、９４.３％増というご説明がありましたけれども、単純に作成報酬は倍になったということなんでしょうか。ここ数年の人数的な面ですとか、今後どのような推移をするのかですとか、お考えになっていらっしゃる部分をちょっとお教え願えればと考えています。","respondent":"蓼沼高齢福祉課長","answer":"区が地域包括支援センターというふうに位置づけられておりまして、新予防給付の予防プラン作成に当たって、介護報酬が入ってくると。区の在宅支援センターが地域包括の機能を一部担っているということで、直接在宅支援センターのほうに報酬を支払うようにしておりましたけれども。","id":"exchange-079"},{"speaker":"木下委員","kind":"質問","question":"私がこの質問をしたのは、利用者の負担が増えるのではないかというので、心配して質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"９２ページ、９３ページおよび都の補助で１０４ページ、その辺のところの耐震診断および改修関係の歳入からお伺いしていきたいと思います。それから学校の耐震改修工事等についての数字等の推移について、所管のほうで所見等があれば、お教えいただきたいということです。","respondent":"片田建築課長、市川庶務課長","answer":"促進計画を含めてということで考えてありますけれども、これまで平成１６年の４月から木造等の民間建築物の耐震診断等々の支援を行ってきてあります。平成１８年度に新たな土地利用現況調査、そういうものを十分含めて… この実施校につきましては、翌年に実施設計を行って、原則としてその翌年に工事を行うという流れで来たものです。平成１９年度において実施する学校についても、その経過の中で実施をする、いわば最後の年度に当たる工事です。","id":"exchange-081"},{"speaker":"原（浩）委員","kind":"意見","question":"校舎のほうから行きますと、学校のほうの耐震関係、改修工事、これは多分国土交通省の告示の１８４および１８５を指針としてやっていらっしゃると思いますけれども、１点、イエスかノーかだけとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"今、委員ご指摘の告示に基づいて行ってあります。","id":"exchange-082"},{"speaker":"原（浩）委員","kind":"確認","question":"そうしますと、前者のほうの一般の木造関係について、これは質問ということになるかどうか、歳入面からですので、１点。これは今現在、私どもインターネットのほうを確認させていただきましたけれども、専門機関に委託されているということ。","respondent":"片田建築課長","answer":"４月から今予定しています、そういうものについては２４万円を今想定して考えてありますけれども、一律の金額の中で行っていきたいと。建築の構造相談担当という職員が１人おりますので、必要なものについてきちっとした診断をしていただこうという形で誘導しています。","id":"exchange-083"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"厳しいとかいう指摘があるものですから、これは要望になるかもわかりませんが、国・都からの歳入関係が多くなるようなことを要望いたしまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"南委員","kind":"質問","question":"６８ページの区営住宅の使用料、そして同じページの自転車駐車場の使用料の２つを質問したいと思います。品川区内の公営住宅の整備率はどういう状況になっているのか、ちょっと全体的な住宅総数との関係で、実態をお知らせください。","respondent":"齋藤住宅課長","answer":"都営住宅は３,５７８戸あります。都民住宅は４０７戸、ＵＲ都市機構の住宅が３,９６７戸、区の区民住宅が１,０５６戸となっております。","id":"exchange-085"},{"speaker":"南委員","kind":"確認","question":"この数字の中で、先ほどおっしゃったように区営住宅については４３９戸、そして都営住宅が３,５７８だから合うのかしら。全住宅戸数が１６万５４０戸、区営住宅の割合は０.３％という数字じゃないかなと考えていますが、この数字について確認をしたいと思います。","respondent":"齋藤住宅課長","answer":"委員おっしゃいました、区の住宅の戸数はその比率で間違いございません。委員のご指摘の相差の部分は、恐らく高齢者住宅や借上住宅、障害者住宅を含むと、４,６５０になると思います。","id":"exchange-086"},{"speaker":"南委員","kind":"質問","question":"昨年の１１月にさきの代表質問でも一部の都営住宅の募集に対して、ここに１,２２１人が申し込んだと聞いておりますが、６４.３倍になるんですよね。東品川の第二都営というところは３８６倍という数字になっているんですが、合わせて品川区の区営住宅の応募実態についてもちょっと説明を求めました。","respondent":"齋藤住宅課長","answer":"実質そういう倍率で言いますと、５０倍前後の倍率になります。ただ西大井六丁目第三に単身向けの３４戸がございまして、そこの応募が大変多くて、これが２００戸ありますので、家族向けの応募は４００人前後です。","id":"exchange-087"},{"speaker":"南委員","kind":"質問","question":"どのくらいの年数がたてば、そういう見解についてはいかがでしょうか。あるいは５年、１０年なのか、ちょっとその辺の傾向を説明を求めました。","respondent":"齋藤住宅課長","answer":"公営住宅は収入の低い方、２５番目までの方が入れることが原則モデルなんですが、今４０番目までの方までが申し込みができる状況にあります。これを平成２０年度までに改正することになっておりますので、申し込みされる方は減ってくるんだろうと考えています。","id":"exchange-088"},{"speaker":"南委員","kind":"質問","question":"今の収入基準の見直しというところがよくわからないんですけど、いわゆる収入分位の低いほうに基準を下げるというふうに理解していいんですか。そこのところをさらに阻む、狭めるものになるんじゃないかなと思うんですけれども、その点についての見解もお願いします。","respondent":"齋藤住宅課長","answer":"国の収入分位で申しますと、今のところ、１００人いらっしゃると収入の低いほうから４０番目までが申し込みができると。国も１０年ぶりに収入基準の見直しをして、一般的なモデルである収入分位２５％までの方に収入基準を改めるです。","id":"exchange-089"},{"speaker":"南委員","kind":"質問・要望","question":"この数字でいいのかどうかもちょっと確認したいんですが、区営住宅の建設を求める方は、２４.８％いらっしゃるんですね。来年度の予算を組んでいる４７億円の半分、そういうところにきちんとした対策をとるべきだと考えていますけれども、その点の認識はいかがか尋ねました。","respondent":"福田まちづくり事業部長","answer":"３年か４年前には都営住宅の移管を受けまして、さらに都営住宅がそれまで持っていた戸数も増加を図るというような努力をしてきております。したがいまして、私どもといたしましては、住宅に困窮する方についての住宅供給について、十分に施策を展開しているという認識です。","id":"exchange-090"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどご紹介したように、少なくとも２４％の方、４人に１人の方が区営住宅の建設を求めておられるんです。この数字はどういうふうに見るのかという、そこのところが行政としての姿勢じゃないんか尋ねました。","respondent":"齋藤住宅課長","answer":"今、国のほうでもさまざまな取り組みを進めておりますので、そういった低所得者の方のための住宅というのも一定程度確保できないか。これは検討する時期だと考えております。","id":"exchange-091"},{"speaker":"南委員","kind":"質問・要望","question":"品川区に住み続けたい。住宅費が高くて出ていかざるを得ないという区民を支えるような姿勢を、さまざまな手法を講じて、とっていただきたいということを求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"福祉高齢事業部にしろ、そういうところでそういう苦情なりいろいろ質問を受けていると思いますが、私は行政の仕事ではないんでしょうかと思います。予算をそちらのほうにかけるべきではないかと思いますが、その辺のご見解を説明を求めました。","respondent":"日下部企画財政課長","answer":"学校の耐震化についても改築だけではなくて耐震補強をまずしっかりやるということを前提に私どもは考えているわけです。において、基金に積み立てをして、トータルで区民サービスの充実を図っているということでご理解いただきたいと思います。","id":"exchange-093"},{"speaker":"須貝委員","kind":"意見","question":"補助金が前は高齢者クラブに１００％行っていたと仮定しますと、何年か前に７割になりました。残り３割ぐらいはお手伝い、もうちょっと補助してやるような仕組みにならないのかどうか、お答えをお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、要望だけで。質問というか、その辺、もっと温かい補助金を品川区のほうも今後展開していただければありがたいなということで質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは１２２ページの雑収入の水族館運営費収入についてお尋ねいたします。それから今年度の来場者数というんですか、前年度に比べて、どれぐらい増えたのかというのをまず１つ教えていただきたい。","respondent":"藤田道路公園課長","answer":"昨年はちょうど４月に品川駅の駅前のほうに水族館ができまして、それとの相乗効果で大分増えたということで考えてあります。１つは回りのレストラン等の改修、あるいは外販等の伸びに加えまして、若干入館料についても見直しをしたということでアップしているものです。","id":"exchange-096"},{"speaker":"山内委員","kind":"質問","question":"アザラシのショーとか、イルカのショーを私も先週行ってきたんですけれども、１日４回やっているんですね。その辺についての民間とのお話し合いというか、今後の運営とかというのは常にお話をされているような状況なんか尋ねました。","respondent":"藤田道路公園課長","answer":"ただ、それだけでは私どもも十分だとは考えてございません。これから水族館と、とにかく何でもいいから、楽しいリピーターがいっぱい来てくれるような見せ方をこれからも工夫していきたいと考えています。","id":"exchange-097"},{"speaker":"山内委員","kind":"質問","question":"区民の皆様にはそういうＰＲをしているというようなことは伺っているんですけれども、大人の場合ですけれども、１,３００円払ってしまうと。従業員の方にどこに表示されているんですかと聞いたら、従業員もわからないような状況だったんですけど、その辺についての改善はどうお考えでしょう。","respondent":"藤田道路公園課長","answer":"約３倍の方が区民割引を今利用するということで、一定の周知は図れているかなとは考えてありますが、私も改善を申し入れております。まだ改善が図れていないのであれば、それにつきましては早急に直したいと思いますので、ご理解のほど、よろしくお願いいたします。","id":"exchange-098"},{"speaker":"山内委員","kind":"質問","question":"最近、いろいろなところでそういうのがありますけれども、例えば品川の水族館でネーミングライツというようなことを考えて収入を上げると。さらなる施設の充実、そのようなことをお考えかどうかというのを最後に説明を求めました。","respondent":"藤田道路公園課長","answer":"もう１つには、その辺の関係もよく見きわめながら、最近はいろいろなところで水族館と業務提携してやりたいというような声も多く聞いております。その辺とあわせながら、考えて進めていきたいと思ってあります。","id":"exchange-099"},{"speaker":"山路委員","kind":"質問","question":"６８ページ、７５ページ、１２１ページのマイガーデン運営費負担金についてお伺いいたします。もう１つは利用者から、何とかその辺も考えていただけないでしょうかという相談を受けたんですが、どのようにお考えか尋ねました。","respondent":"冨岡高齢事業課長、松嶋交通安全担当課長","answer":"すみません、道路絡みのことにつきましては道路所管部署に。まことに申し訳なく思っておりますので、それにつきましては、物を買う等で対応させていただきたいと考えています。そうしますと、１ｍ・１ｍで残して、それを通った人間がどのように解釈するかという部分もあろうかと思います。","id":"exchange-100"},{"speaker":"山路委員","kind":"質問","question":"次に行きます。子どものバレエ教室というのがあるということを伺っておりますが、どういう内容でやられているのか、ちょっとお伺いいたします。","respondent":"谷田部健康課長","answer":"３歳から４歳の体操に始まりまして、あと３歳６カ月から４歳のバレエ、幾つか取り組んです。それからあと、クラシックバレエのほうにも取り組んでいるです。","id":"exchange-101"},{"speaker":"山路委員","kind":"質問","question":"実は小学校５年生の女のお子さんが、抽選に漏れてできなくなったということを非常に残念がられていたんですね。もう少しキャパを広げて、そういう一生懸命になっている方が参加できるような体制は考えられないものか尋ねました。","respondent":"谷田部健康課長","answer":"施設等の関係でいわゆるキャパシティーがございまして、現在、コース型のほうは目いっぱいという状況があります。でまた違うニーズもございまして、その辺のバランスをとりながら、これからも受託運営者とも協議をしてまいりたいと思います。","id":"exchange-102"},{"speaker":"山路委員","kind":"質問・要望","question":"２時間超えますと１００円とか１５０円入れますね。その駐輪場、１００円とか１５０円入れたお金の回収というのはどのような体制でやられているのか、お伺いいたします。","respondent":"松嶋交通安全担当課長","answer":"これは現在、業務委託をいたしております、日本コンピュータ・ダイナミクス、それと昭和建物の２社ですけれども、これは毎日精算をして、銀行に入れて、翌日になりますけれども、区のほうにその部分をすべて報告になっております。","id":"exchange-103"},{"speaker":"山路委員","kind":"質問・要望","question":"非常に不安定なところがありますが、区はチェックしているんですか。この辺について、どのようにお考えか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"そこでも確認をいたします。その後に区にきまして、区でも毎日確認をしますので、そこら辺は間違いなくやられていると思っています。","id":"exchange-104"},{"speaker":"山路委員","kind":"質問","question":"ちょっと厳しい指摘かもしれませんけれども、お話をさせていただきましたので、どうぞ事故がないようによろしくお願いいたします。夏はここは使わせてもらえないんでしょうかという話をちょっと伺ったんですがということで、どういう形で使えるか、ご説明をお願いいたします。","respondent":"富田生涯学習課長","answer":"野球のオンシーズンの間は野球が優先になっておりまして、Ａ・Ｂ面につきまして１２月から２月までをサッカー優先期間として抽選をしているものです。","id":"exchange-105"},{"speaker":"山路委員","kind":"質問","question":"予算書でも野球に比べて、サッカーのほうは約半分の使用率ですよね。夏も使えるということでよろしいんか尋ねました。","respondent":"富田生涯学習課長","answer":"３カ月前の抽選、優先の枠というのは野球でございまして、野球団体対象に抽選を行いまして、その後、あいた時間帯につきましてサッカーの方もご利用いただけるということになっております。","id":"exchange-106"},{"speaker":"山路委員","kind":"質問・要望","question":"続きまして、マイガーデン運営費負担金についてお伺いいたします。マイガーデンは豊町を本年度中に終了して、南大井のほうに新設されることだと思うんですが、この辺の経緯について説明をしてほしいと求めました。","respondent":"藤田道路公園課長","answer":"工事のほうが進んでまいりまして、そういう関係で豊町のほうについては、今年度でおしまいということになります。平成１９年度ご承認いただければ、整備をし、開放していきたいと考えているものです。","id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"東品川の方面の方がマイガーデンがこちらの方面に欲しいという希望を持った方が何人かいらっしゃいまして、どの辺の場所にできるんでしょうか。この辺についてはどのように考えていらっしゃるんか尋ねました。","respondent":"藤田道路公園課長","answer":"それと、施設のあり方については、これから中身についてよく検討してまいります。委員からお話があった、そちらのほうでもボランティア募集みたいなのをやりますので、活用いただければと考えています。","id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私は６３ページ、シルバーセンターに関連してなんですが、そのことと、それからあと８０ページの建築確認手数料に関連して質問いたします。簡単にそのスケジュールを教えていただきたいのと、それから、その改修の内容はどうでしょうかということを説明を求めました。","respondent":"冨岡高齢事業課長、宍戸施設担当課長","answer":"工事の期間ですが、今年７月中旬から、来年の平成２０年２月下旬を予定しております。その他全面内部の改修ということとあわせて、介護予防のための部屋を新設するというところで、シルバーセンターについては予定をいたしております。 全体的なお話で申し上げますと、そのほかの図書館、それから児童センター、保育園につきましても、設備等も含めて、大規模改修を耐震改修にあわせて行うという予定でおります。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから建築確認手数料のほうでありますが、これは先ほど菊地委員から質問がありました。品川区もそうですけれども、どの自治体でも責任を問われる形になっていきますので、まずそのことについての確認をお願いいたします。","respondent":"片田建築課長","answer":"東京都がもし指定されれば、区はその機関と契約を結んで委託をしていくといったような流れになります。あるいは体制等々整えた、東京都がその基準を決めてきますので、その基準に合致したところを東京都が指定するといったシステムになってあります。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"要はそのピアチェック機関が一昨年にあったいろいろな問題を見抜けなかったら、何の意味もないわけですよね。その責任を最終的に品川区がとっていかざるを得ない体制になってしまったわけですから、技術力と言いたいんでしょうか、もう少しはっきりとした。","respondent":"片田建築課長","answer":"基本的には２人というお話を聞いてありますけれども、必ず２人以上の判定員が複数の目で見て、私どもは考えてあります。そんな状況の中で適正に進められていくことを私どものほうも望むところですし、東京都のほうに対しても、十分要請していきたいと考えています。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、プログラムというのは当然更新しないといけないわけですよ。ですから、こういうときだからこそ、はっきりと品川区が国に対して、あるいは東京都に対して物を言っていくべきだと思うんですが、いかがか尋ねました。","respondent":"片田建築課長","answer":"プログラムについても１年ぐらいかけて、引き続き、そういう大臣認定のプログラムの指定する国のほうには要請をしていきたいと。２３区一体となって、都のほうにいろいろな問題提起、課題等をぶつけていきたいと考えています。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問・要望","question":"すごく答弁の熱意は伝わってくるんですけれども、もっとはっきりと言いたいことを言ったらいいんじゃないでしょうかという気持ちがするんですよ。ですから、質問していますので、改めて答弁をお願いいたします。","respondent":"福田まちづくり事業部長","answer":"その実施していないものにでも、地方公共団体の事務だからという理由で責任が問われている。必要なところに必要な申し入れ、あるいは要請、これらについて対応してまいりたいと考えております。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問・要望","question":"恐らくは委員会ですから、本当はもっといろいろなことを言いたいことがあるかもしれないと、私たちは理解しています。ぜひ部長のお話しされたようなことも含めて、確かな形で進めていっていただきますように、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４４ページの特別区民税についてお伺いをしたいと思います。それと２月１日付の広報で、増税になる区民の人数と、このことについてもお聞かせほしいと求めました。","respondent":"太田税務課長","answer":"私のほうから３点についてのご質問にお答えをいたします。それから定率減税廃止による増税ですけれども、今年度、平成１９年度の予算で行けば、約１２億６,０００万円余という数字になってあります。","id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今後への要望なんですけれども、ぜひこういうふうにご検討いただきたいと思うんですが、ひとつお聞かせほしいと求めました。７００万円で６万７,４００円が、ぜひその点をお願いしたいと思うんですが、いかがか尋ねました。","respondent":"太田税務課長","answer":"ただ電話の対応について、どういう内容かについては、今後もつかんでいきたいと思ってあります。所得税のほうが１万２,４００円ということになっています。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今品川区は要介護４と５の方に特別障害者ということで、２３区の中でも１７区が軽度や中度の方に認定書を出すという状況まで増えているんですよね。申請があった場合は認定書を出していただきたいと思うんですが、この２点についてお聞かせほしいと求めました。","respondent":"太田税務課長、蓼沼高齢福祉課長","answer":"私のほうで１点目のほうをお答え申し上げます。それから特集については今後も必要に応じて税の周知という意味ではやっていきたいと思ってあります。これにつきましては、昨年の定例会の質問でもお答えをいたしましたとおり、一様にそれを当てはめるのはいかがかなです。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"手帳を持っている人、持っていない人、公平を欠くことがないように行われる必要があるということで書かれているんですね。なぜ２３区の中で、なぜ品川区ができないのか、ちょっと教えていただけないか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"どの範囲の方をその対象とするかという点で申し上げますと、要介護４、５の方については基本的に異論はないだろうと考えています。今後のご指摘の点については、どういう点でご理解いただけるかという部分については、やはり慎重に検討していくべき課題だろうと考えています。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問","question":"それから６８ページの公園占用料というんでしょうか、それから６０ページの使用料について、お尋ねします。その見通しのもとで、今回の予算が立てられていると思いますけれども、それについてのお考えをお聞きしたいと思います。","respondent":"小林保育課長","answer":"来年度は予定では福祉保険基盤等区市町村包括補助金という形で、それから子育ての施策等に３区分に分けて再構成をするという情報を持っております。保育に関しましては、認証保育所や延長夜間保育等の経費補助金分について、財調へ参入が予定されている件と考えております。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"一般財源か、要は財調の中で入ってくるということになってきますと、今までひもつきというところがなくなってというところがあると思うんですね。その補助金等々の絡みの中で、どういうふうにそれを使っていこうと、用いていこうというふうに考えているんか尋ねました。","respondent":"日下部企画財政課長","answer":"今、ご質問にもございました、冒頭の都の補助金の関係でご説明させていただきました。従前のものについては、基本的にはこれを少なくとも平成１８年度も一般財源として措置をしていくということで変わりはございません。","id":"exchange-120"},{"speaker":"西本委員","kind":"確認","question":"２つほど確認したいんですけれども、補助的なところ、補助金という形ではどれだけ来るものなんだろうかという見通し。それから認定子ども園が今度公立の保育園３園で転換するということですが、財源等々の補助みたいなものがあるのかないのかをお聞きしたいと思います。","respondent":"諸岡児童課長、日下部企画財政課長、高橋幼保一元担当課長","answer":"平成１９年度ベースで算定をいたしますと、約１,０００万円弱という金額です。区のほうでは一般財源で７,０００万円… 児童課長のほうから従前の考え方でご説明させていただきましたが、少なくとも平成１９年度以降は、すべて一般財源で手当をするという形になってまいります。 認定子ども園、公立保育園での認定子ども園というところで、特に財政的なものという補助金はございません。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"認定子ども園については、ちょっとこれは私も残念に思うんですけれども、何かしらあっていいんじゃないかなと思ってはおります。所得制限とか、それがまた一般財源化で全部補助されるということの見通しはまだついていないということの理解でよろしいか尋ねました。","respondent":"日下部企画財政課長","answer":"区としては対象も広げ、なおかつ所得制限もなしということで、平成１７年１月から拡大してやってまいりました。この４月からさらに中学生まで対象拡大いたしますが、これも基本的には所得制限も設けませんので、これも含めて、すべて区として負担をしていくです。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、品川区の持ち出しがあるということですよね。１２２ページの各種保育料ですが、あとオアシスルームの件ですけれども、この利用率がどうなっているのかという動向を教えてほしいと求めました。","respondent":"小林保育課長、高橋幼保一元担当課長","answer":"平成１８年度、まだ第４四半期が終わっておりませんので、横ばい傾向かと思われます。休日、年末保育につきましては曜日の設定等の影響かと思われますが、１割程度の減少傾向が見られます。 まだその傾向等は出ていませんけれども、平成１８年度の実績から見ますと、平成１９年度については若干公立の場合は増えてくる。私立のきんだぁくらぶにつきましては、そのままというか、横ばいというか、現状を維持している状況です。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"生活支援型一時保育というのは、オアシスルームの件だと思うんですが、オアシスルームはいかがか尋ねました。","respondent":"小林保育課長","answer":"オアシスルームの利用ですけれども、生活支援型一時保育、現在のところ、１２月までで２万８,６１０ということで、対前年に比べますと、１割ほどの減にはなっておりますが、下期の動向によっては、同様の水準に至るかと考えております。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"横ばい、むしろ若干下がっているというところでは、やはり必要な方に使っていただけているような状況なのかなと感じております。そこの指導というのがかなりきちんとされてきているのかどうか、むしろ若干下がっていると考えていいものなのか、いかがか尋ねました。","respondent":"小林保育課長","answer":"継続して必要な場合だけ、就業の実態に応じて、現場のほうで状況を確認しながら利用していただいている状況にあります。その各園ごとの状況を見ますと、その傾向が定着化していると考えております。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"預けるということではなくて、子育てというものがどういうものであるのかをきちんと押さえた上で、利用していただきたいと思っています。次に６８ページの公園占用料、これはどういう使い方をすると幾らぐらいと決まっているんか尋ねました。","respondent":"松代管理工事課長","answer":"公園占用料のロケーションですけれども、これは１カ所あたりの占用料が決まっておりまして、９,７２０円ほどいただいております。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"これは例えば貸してくださいと言ったときに貸してあげるということなのか、それとも品川区が積極的に貸しますよと言っているのか、その辺はいかがか尋ねました。","respondent":"松代管理工事課長","answer":"あくまでも占用を目的にしておりませんので、申請があった場合、利用者等の支障がないという範疇で使用を許可しているというものです。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"こういうすばらしいところがあるよというようなところを使っていただくというような工夫ができないかなと。答えられるかちょっとわからないんですけど、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"ロケーション等を受け入れていきたいと考えていますし、また今、新水とみどりのネットワーク構想の中でも観光という視点も１つ入れております。そういった中に今、委員からおっしゃられた点も十分検討の課題にさせていただきたいと思います。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"次に６０ページの使用料の中で、考え方を教えていただきたいんですが、使用料とかが一切入っていないんですね。そういうあれですと、議会で議論する考え方といいますか、それについてお聞きしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"利用料金の収入見込みというのも括弧書きで加えします。中についてはチェックいただくといいますか、そういった形で、そのほかさまざまな場面で必要に応じてご報告をするという方向で考えております。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"では歳出のところで、歳入も含めて議論するという、報告をいただけるという理解でよろしいんでしょうか。品川区としてどういう歳出をしているのかという流れになるかと思いますが、トータル的な説明をいただけるものなのかを。","respondent":"堀越行財政改革担当課長","answer":"今、すべての歳入のほうの説明ということでしたが、歳出のほうで一応の利用料収入についても括弧書きで載せていただいて、そのほか、その中でまた説明をするという考え方です。","id":"exchange-130"},{"speaker":"西本委員","kind":"意見","question":"ぜひ、これから歳出のところで幾つか指定管理者制度を使って予算を立てているというところがありますので、できる限り、詳細について、歳入のところも含めて、今後ご説明いただけますよう、お願いをして終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-131"},{"speaker":"松澤委員","kind":"質問・要望","question":"８０ページの建築確認手数料、３点目は１０３ページの都市計画道路整備費、１６３号線整備に関連してお聞きしたいと思います。初めの問題ですけれども、建築確認手数料、先ほど我が党の伊藤委員が質問しましたけれども、やはり国から仕事が押しつけられてくる。","respondent":"福田まちづくり事業部長","answer":"あの判決は既に確定していますので、これを覆す手段がありません。それで、ご発言にもありましたが、附帯決議を挙げていただきましたので、この附帯決議を懐に入れて、しっかりと物を申していきたいと考えています。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"ところで、国庫委託金の件なんですけれども、昨年の同じ委員会で、我が党の石田委員が質問しました。この１年間、どのような話し合いをしたのか、お答えほしいと求めました。","respondent":"日下部企画財政課長","answer":"それから２３区のレベルでは区長会ということで、国それから東京都に対する要望という形で、これを持ち上げてあります。この超過負担の解消ということも１つの大きな課題として取り上げまして、その解消の申し入れをするということで予定しているものです。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"私たち議会としても、しっかり後押ししますので、しっかり正すべきところは正していっていただきたい。これは品川区に影響が出てくるんだろうかどうか、その辺、しっかりとお答えほしいと求めました。","respondent":"太田税務課長","answer":"私どもも３月２日の新聞を見て、初めて知ったという状況です。基本的には東京都の個人都民税の東京都分を東京都が実施をされるですので、電算システムとか、そういう部分での影響は出てこようかと思ってあります。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問・要望","question":"こういう問題が２３区と都と財調協議あるいは都区協議、突然思いつきのようにぽんと出てくること自体はやっぱりおかしいと思うんですね。いろいろな協議の中で話し合いが事前になければおかしいと思うので、その辺についてちょっと述べていただけますか尋ねました。","respondent":"日下部企画財政課長","answer":"今、委員ご指摘のとおりかと思います。いろいろ協議を進めていく、必要なものについてしっかりした対応策をともに進めていくということが、私ども大変残念に思っているところです。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問・要望","question":"いろいろ協議の場があるんですから、しっかりと抗議をし、意見をいっていただきたいと考えています。土木費補助金で１億５,４８０万円出ておりますけれども、このお金を使って、どのような事業をなされるのかについてお伺いしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"将来、１６３号線が一本橋通りの用地取得ができますれば、高架下のところの東急下の高架下が混雑するというようなことが予測されます。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"正直言って、これはたしか平成１７年度まで４年間で終わる予定になっていたんじゃないですかね。並行して工事をされるのかどうか、私は早急に工事をすべきだと思うんですけれども、その辺のことについてお伺いしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"この１６３号線整備の中に、一部２０５号線沿いのほうに用地を取得した部分がありますので、その工事が始まります。平成１９年、２０年度で何とかすべての工事を終わらせたいと思って、来年度にはこの用地費の中で用地取得したいということで今考えているところです。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"所期の計画では、たしか平成２０年までに完成させるということでしたね。そのおくれというものはないんか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"２年ほど延期したことは事実ございまして、その２年の中で、私どもとすれば、与えられた事業期間の中で、あと残ったのは２年間ですけれども、平成１９年、平成２０年の中で完成したいということで、今、努力しています。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問・要望","question":"２６号線は東京都の事業ですから、３年間でやるだろうというように、私どもは思っているんですね。かえって２６号線が整備されても、大混雑が起きるということなので、とにかく同時に必ず終わらせるように努力していただきたい。","respondent":"浜脇街路事業担当課長","answer":"２年間ですので、何とか平成２０年度に完成したいと考えておりますので、よろしくお願いいたします。","id":"exchange-139"},{"speaker":"土井委員","kind":"質問・要望","question":"その辺はいかがお考えでしょうかということで、その住民基本台帳カードは一体全体、さらに日本中ではどうなっているのかということになるんですね。本来出すべきものをやっぱり今年出しておかなければいけないのではないかという可能性もあるんですが、その辺はどのようにお考えなんか尋ねました。","respondent":"日下部企画財政課長、金子産業振興課長、上川内戸籍住民課長","answer":"つまり、区としては特別交付金は基本的には１件算定で対応といいますか、それではいかがなものかと。これは教育委員会のほうから後でその具体的な内容につ… こちらにつきましては、株式会社が１つと、それからＮＰＯが２つ入って貸し出ししているです。ビジネス支援図書館での活動をしていただいているところ… ちなみに品川区では２,８５３枚ということで、人口３３万の０.８％の普及率ということで、ほぼ全国と同じように進んでいるです。","id":"exchange-140"},{"speaker":"土井委員","kind":"質問・要望","question":"５％に増えたんだというようなお話は伺っておりまして、予算査定的な査定なものですから、あえて質問させていただきました。ベンチャー創業支援センターの件などはよくわかりましたが、このときも、６件すばらしい例があったわけですから、こちらをみんなで喜びましょうよ。","respondent":"小野情報システム課長、日下部企画財政課長","answer":"そういう部分で非常に普及は遅いんですけれども、その部分での評価があって、少しずつ伸びているのではないかなと考えております。国のほうでは公的個人認証を使った電子申請が非常に伸びるのではないかと考えていたところ… 年間で行けば２０年ですから、６,０００万円ということで、非常にばかになりません。ですから、そういう金利の動向は、これから、とりわけ十分注視をしながらその辺の判断というのはしっかりしていかなければいけないと考えています。","id":"exchange-141"},{"speaker":"石田委員","kind":"提案","question":"ページは８８ページと９８ページ、全体のことを最初にお伺いしたいと思っています。先に全体のことを１つ伺いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"ここで基本的な平成１９年度の予算編成に向けての基本方針についても、依命通達という形で、全体に徹底を図ったと。そういう基本的な方針を徹底したところです。","id":"exchange-142"},{"speaker":"石田委員","kind":"提案","question":"それから１３節建築物耐震化改修等補助金、それから１０４ページだと、都の補助金になるんですが、木造住宅耐震化助成補助金というのがあります。この４点をちょっと聞きたいわけですけれども、逆に品川区から提案をして、ここら辺をお聞かせ願いたいと思いますとの意見を述べました。","respondent":"片田建築課長","answer":"端的に言いますと、国および東京都が国については、住宅建築物に関する補助金という制度を立ち上げてまいりました。これらの制度を十分活用しつつ、区としても耐震診断および支援をしていきたいといったような考え方に立つものです。","id":"exchange-143"},{"speaker":"石田委員","kind":"提案","question":"こういうことだと提案をして、それで提案をして取りに行って、内容はいいですとの意見を述べました。","respondent":"片田建築課長","answer":"大変失礼しました。基本的には国がつくった制度を十分活用するという考え方に立ち、十分現行の制度を活用していきたいという考え方に立つものです。","id":"exchange-144"},{"speaker":"石田委員","kind":"提案","question":"それを提案をして、こういうところの補助金がつかないかとか、そういう模索をしていくことも１つの考え方だと思うのね。それからおりていって、こういう考え方をするんだということが、そういう考えをお持ちなのかどうかということをもう１度お聞きしたいとの意見を述べました。","respondent":"片田建築課長","answer":"オーソドックスな制度の中に取り入れていきたいといったような考え方の中で、残念ながらその実現にはなかなか難しいというところがございました。","id":"exchange-145"},{"speaker":"石田委員","kind":"提案","question":"こういう形のものを提案して、東京都の補助金を取ってこよう、また国の補助金を取ってこよう。今、この耐震関係でやれそうだと思われているものが、これなら補助金を取ってこれそうだというのは、課長の中で何か思いがあるなら聞かせてほしいとの意見を述べました。","respondent":"片田建築課長","answer":"そういう意味では来年度、促進計画を区としても策定していく中で、幾つかのメニューを含めて、施策について、あわせて検討していきたいと。なおかつ、それについてはできるだけ早い時期に実施していきたいという考え方です。","id":"exchange-146"},{"speaker":"石田委員","kind":"提案","question":"まさに自助・公助・共助で、そこの中の自助・公助・共助はこれ以上言わないけれども、私は非常にこれをうまく活用した方法論があると思っています。いろいろな意見を提案しますので、ぜひぜひよろしくお願いして、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-147"},{"speaker":"堺委員","kind":"質問・要望","question":"取得に当たっての財源の確保といいましょうか、その辺のところにつきまして、確認をしていきたいと思います。そういう方々からの要望といいましょうか、その辺の仕組みをまず１つ、確認をしておきたいと思います。","respondent":"齋藤住宅課長","answer":"指定管理者は今、３社ありますが、通常の日常の生活にかかわるものにつきましては指定管理者が請けてあります。その他さまざまな要望がありますので、一定のものについては自治会の方と私が直接お話をすることもあります。","id":"exchange-148"},{"speaker":"堺委員","kind":"質問・要望","question":"そうすると、改善というか、要望の中身によっては、指定管理者制度に行く場合もあるし、直接区のほうに来る場合があるということですね。そうしますと最近、区のほう、あるいは宅建協会でもいい、両方どういう要望が来ているのかどうか、教えていただけますか。","respondent":"齋藤住宅課長","answer":"したがって、防犯カメラを設置してくれないか。ついてはさくら会や都の用地も借りたいので調整してくれないかというような要望がございまして、私どものほうで対応しております。","id":"exchange-149"},{"speaker":"堺委員","kind":"質問・要望","question":"今、ファミーユ下神明の具体的な要望が寄せられた中身について教えていただきましたが、自治会の方からそういう要望がございまして。今回の予算の中で計上されて、設置という方向になっているのかどうか、その辺ちょっと確認させていただけますか。","respondent":"齋藤住宅課長","answer":"ファミーユ下神明には４機、そういった文書の要望や、各住宅に最低２機は防犯カメラを設置する予算を計上しております。そして年度に入りましたら、直ちに整備いたします。","id":"exchange-150"},{"speaker":"堺委員","kind":"意見","question":"入居者の方々の安全・安心を守るという視点で、必要に応じては十分調査の上対応していただけるように、お願いをしておきたいと思います。いかがでございましょうかとの意見を述べました。","respondent":"齋藤住宅課長","answer":"区民住宅につきましては、区も自治会の結成をということで、支援をしております。積極的にお話を聞きながら、よりよい住宅、安心・安全に向けて整備をしてまいりたいと思います。","id":"exchange-151"},{"speaker":"堺委員","kind":"質問","question":"６,２７３万３,０００円ですか、内容というんですか、ちょっと参考に教えていただけますか。","respondent":"富田生涯学習課長","answer":"１７地区のスポーツ・レクリエーション活動推進委員会のほうでもって、バドミントンですとか、その他屋内体育館を使っての利用が大変多いです。教室につきましては、普通教室あるいは余裕教室等を含めた、そういった社会教育関係団体の利用が多いです。","id":"exchange-152"},{"speaker":"堺委員","kind":"質問","question":"最近、シルバー世代を含めた方々のダンスが、大変多くなってきているようですが、シルバーセンターとか文化センター等でも、シルバーダンスというんでしょうか、ダンスを利用している方々も大変多いんですが、今、おっしゃっておられたような学校等を利用されているサークル、グループはありますか。","respondent":"富田生涯学習課長","answer":"学校体育館を使っては、わりとシルバー世代で、ヨガですとか太極拳ですとか、そういった利用は聞いておりますが、シルバーダンスについてはまだ申し訳ございません、ちょっと承知しておりません。","id":"exchange-153"},{"speaker":"堺委員","kind":"質問・要望","question":"実はこういう要望があるんですけれども、そういうことができるような改善もやってもらえないでしょうかというような要望があるんですが、いかがか尋ねました。","respondent":"田村地域活動課長","answer":"大井第三地域センターは滑らない床の中では滑る床にしてありまして、しぶしぶ３団体については多少不満もあるようですが、利用しているのが現状です。今後基本設計、実施設計を進めてまいりますので、その中で検討してまいりたいと考えております。","id":"exchange-154"},{"speaker":"堺委員","kind":"質問","question":"そのことによって、利用者の皆さんに喜んでいただけるわけですので、ぜひひとつそういう方向で検討をお願いしておきたいと思います。新規に１５億７,２５０万円申請されているわけですが、こういうものが補助金として交付されるとなったのかどうか、その辺はいかがか尋ねました。","respondent":"日下部企画財政課長","answer":"これから本格的な協議に入っていきますけれども、基本的にはそういう前提の上に立って、予算を計上させていただいているというものです。","id":"exchange-155"},{"speaker":"堺委員","kind":"質問","question":"いわゆる都市計画交付金の対象だからというお話ですね。私がお尋ねしたのは、明確に金額が交付金として来たんですから、どういうことなんでしょうかということを聞いているわけです。","respondent":"日下部企画財政課長","answer":"その事業費の４分の１、これが約１６億円ですので、予算に計上させていただいていると。その辺のルールの裏づけに基づいて、計上させていただいているというものです。","id":"exchange-156"},{"speaker":"堺委員","kind":"質問","question":"今度１１２ページにあります、１７款の繰入金の中で新たに公共施設整備基金繰入金で、８１億９,０００万円計上されている。この中にはどの程度の金額が含まれているんか尋ねました。","respondent":"日下部企画財政課長","answer":"平成１９年度、この都市計画交付金の残り分として、財源として手当をするということで予定をしております。それからもう１点、この分につきましては、平成２０年度から４カ年で財調算定の対象になりますので、財源的にはしっかりしているというものです。","id":"exchange-157"},{"speaker":"沢田委員","kind":"質問・要望","question":"区民の意見を反映するための仕組みづくりが求められていますと、区民の声をお聞きして、私は期待を持っております。議会との関係で、どういう手順で議会の意見をくみ取ろうとしているのか、ちょっとそこらについてよろしくお願いしたいと思います。","respondent":"濱野区長","answer":"施政方針で述べたとおりのことでありまして、改めてお問い合わせをいただきましても、そういうことです。ものによっては、議案説明会の中での説明に若干の詳しい事柄を付与するということでやってまいりたいと思っていますので、その辺。","id":"exchange-158"},{"speaker":"沢田委員","kind":"質問・要望","question":"まだ区長が変わったばかりですから、これがすべてだという思いで言うんじゃなくて、今度の荏原西地区の小中一貫校の母体校に荏原第二中学校を加える。日を追って決定をどういう手順でやったのかを説明願いたいと思います。","respondent":"古里学務課長","answer":"この件につきましては２月９日、１０日に新入学生徒の入学説明会が予定されておりました。昨年の夏からこの建設に当たっての説明会を経過する過程の中で、教育委員会として予算編成をし、そして予算として提案をさせていただいているです。","id":"exchange-159"},{"speaker":"沢田委員","kind":"質問・要望","question":"ごめんなさい、ここでやっているのは歳出のものではなくて、手順でどう決めたかということに限って聞かせてもらっています。事務局での決定と、教育委員会での区教育委員会の決定、その日程を教えてほしいと求めました。","respondent":"古里学務課長","answer":"地域でのいろいろな建設に当たっての説明の中、最終的な判断として予算の中に盛り込み、予算の審議に提案させていただいているです。","id":"exchange-160"},{"speaker":"沢田委員","kind":"意見","question":"私が聞いているのでは、傍聴した方から教育委員会は１３日に決定したと。なぜこんな手順の違いが出てきたのかと聞いているんですとの意見を述べました。","respondent":"古里学務課長","answer":"２月１３日の教育委員会で、昨年来の経過の中では、教育委員会に状況の説明は適宜行ってきてあります。そういう中で、教育委員会としてのコンセンサスは得られていたというふうに判断をしています。","id":"exchange-161"},{"speaker":"沢田委員","kind":"提案","question":"行政をチェックし、区民の要望を行政が取り上げなければ、条例提案だとか予算修正案で区民の声を直接議会が行政のほうに反映をする。私はそんなことではとてもじゃないけど、指定管理者は決められないと思いますけれども、ご見解を、ご回答をお願いしたいと思いますとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"指定管理の部分でお答えをしますと、議会に対してはその都度議決をいただく際にその審議に資するような資料をお出しさせていただいて、議決をいただいていると考えております。","id":"exchange-162"},{"speaker":"沢田委員","kind":"意見","question":"それが不存在だというふうに出たんです。これがうそなのか、実際にそういう資料が不存在なのかということを聞いているわけですとの意見を述べました。","respondent":"木下福祉高齢事業部長","answer":"細かい数字の部分では把握して、当時数字としては持っていなかったということで、そのようなお答えをさせていただいたところです。","id":"exchange-163"},{"speaker":"沢田委員","kind":"質問・要望","question":"今後要望したいと思いますけれども、こういうのをつまびらかに出していただきたい。議会にそれを報告してほしい、資料を提出してほしいと思いますけれども、再度その点をお尋ねしたいと思います。","respondent":"堀越行財政改革担当課長、中川原広報広聴課長","answer":"３月１日、指定管理のモニタリング強化、ガイドラインというのを作成をしております。平成１９年度以降、議会の報告については適宜、必要に応じてご報告をさせていただきたいと考えております。 個人情報保護という観点から、個人が特定するものについては、公開できないということで運営しております。きちんと厳選していただいていますので、今はそういう形で特定されない限りの情報として出させていただいているところです。","id":"exchange-164"},{"speaker":"沢田委員","kind":"質問・要望","question":"たまたま私ども、野党ですから、下手を出しちゃうと追及されて、墓穴を掘るという気持ちがわからないじゃないですけど、それは違う。ぜひ今日、改善できる点は早急に改善してもらうということの検討をしてもらうことを要請いたしまして、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"須藤委員","kind":"質問","question":"４６ページ、たばこ税について質問できる、数少ない議員の１人として質問します。来年度、５,０００万円増額してありますけれども、このプラスした考え方というのは何か尋ねました。","respondent":"太田税務課長","answer":"考え方といたしましては、昨年の７月１日にたばこ税の改定がございました。この部分を加味して、増額させていただいたものです。","id":"exchange-166"},{"speaker":"須藤委員","kind":"質問","question":"何割か当てれば相当な金額になってくるわけなので、そういうことをお考えになることはできないでしょうか。そういったものを底上げするような、何かたばこ税でこうやっていますよというのが見えるような使い方はできないか尋ねました。","respondent":"日下部企画財政課長","answer":"この税の性格自体からしまして、ただ委員おっしゃっている趣旨は、区民に対する一つの普及・啓発という意味合いもあろうかと思います。そういう区民向けのＰＲの中で、どういうことが可能なのか、いろいろこれからひとつ検討課題とさせていただきたいと思います。","id":"exchange-167"},{"speaker":"須藤委員","kind":"質問","question":"もう１つ、いろいろなところに行くと思うんだけれども、そういった考え方はできないか尋ねました。","respondent":"中島経理課長","answer":"庁舎におきます喫煙室につきましては、それぞれ工夫しながら、喫煙者のこと、あるいはたばこを吸わない方のことも含めて、バランスをとりながら、現在設置しています。","id":"exchange-168"},{"speaker":"須藤委員","kind":"質問","question":"何となく隅っこのほうでせせこましく、おいしいたばこもあまりおいしくなくなっちゃうので、ひとつお願いいたします。いろいろな国の施策がおりてきてどうのというようなときに、負担金みたいなのがどこかには見えるんでしょうか、そのあたりを説明を求めました。","respondent":"冨岡高齢事業課長","answer":"後期高齢者の歳出に伴う補助金の関係です。平成１９年度についてもこれで対応できるということで、約２,３００万円ほどの国庫基準に当てはまっておりますので、補正に向けて要求していくです。","id":"exchange-169"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから１１８ページの競馬組合の配分金ですけれども、４億円を切ってきましたという数字になってきましたけれども、いかに考えておくかなと。この分配金自体が各区に対してどの程度まで少なくなってきたときには、危険水域だよというような考え方をしているのか、そのあたりを説明を求めました。","respondent":"桑村総務課長","answer":"平成１９年度の予算をどういうふうに考えているかといいますと、売得金額とすれば、これまでと同様の金額ぐらいできるだろうと考えているところです。","id":"exchange-170"},{"speaker":"須藤委員","kind":"意見","question":"１２１ページの雑入の中で、水道料となっておりますけれども、このあたりはどういう考え方でとってくればいいのかなと。そこの私用というのはどういう、特別養護老人ホームで私用であるというのはどういうことかなと思うんですがとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"そちらのほうでまとめてお支払いしているものについて、この特別養護老人ホームの部分について、区のほうに納入していただいているというものです。","id":"exchange-171"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、ほかの特別養護老人ホームは全然関係ないよという話になる。ほかにどこかに入れているところがあるんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"基本的にその施設で、特別養護老人ホームで要した光熱水費の経費については、それぞれの施設でお支払いいただくということになっております。","id":"exchange-172"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区では２０億円ぐらいのマイナス要因があるよというようなお話を伺うんですけれども、その２０億円というのも何年間かかけての２０億円になる。そうすると、終局的にはその影響というのが逆になってくるのかなという思いがあるんだけれども、そのあたりはどうか尋ねました。","respondent":"日下部企画財政課長","answer":"税源移譲に伴うマイナス約１億６,０００万円程度で見込んでおりますが、そこで発生した２億円ということで、合わせて約２０億円と。これが平成１９年度からマイナス２０億円で、毎年度継続されるということで受けとめてあります。","id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/472478?Template=document&Id=876#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":119586,"voices":395}}]);
